export type GlassMaterial = 'regular' | 'clear';
export type GlassRenderer = 'auto' | 'css' | 'svg';
export type GlassTheme = 'system' | 'light' | 'dark';
export type GlassDensity = 'compact' | 'comfortable';
export type GlassTransparency = 'system' | 'reduced' | 'opaque';
export type GlassMotion = 'system' | 'reduced' | 'none';
export type GlassContrast = 'system' | 'more';
/**
 * Which set of metrics the interface is drawn with.
 *
 * `auto` — the default — reads `(pointer: fine) and (min-width: 768px)`: a cursor, on a screen
 * wide enough that a desktop layout is the honest one. A tablet with a trackpad reports a fine
 * pointer at phone width, and 22px controls there would be the wrong answer to the right
 * question. The resolved value is on the policy as `resolvedPlatform` and, when it was
 * overridden explicitly, on `<html>` as `data-lg-platform`.
 */
export type GlassPlatform = 'auto' | 'desktop' | 'touch';
export type BackdropTone = 'light' | 'dark' | 'mixed';
export type GlassQuality = 'balanced' | 'high';
/**
 * Small glass (buttons, tab bar, toolbar) flips light/dark with what is behind it.
 * Large glass (sidebar, menu, sheet, popover, alert) is thicker, more opaque, has a
 * deeper shadow and stronger lensing, and deliberately does NOT flip — flipping a
 * large surface is distracting.
 */
export type GlassSize = 'small' | 'large';
/** Standard materials belong to the content layer, never to floating controls. */
export type StandardMaterial = 'ultraThin' | 'thin' | 'regular' | 'thick';
/** Web equivalent of Dynamic Type content sizes. `ax1`–`ax5` are the accessibility sizes. */
export type TextSize = 'xs' | 's' | 'm' | 'l' | 'xl' | 'xxl' | 'xxxl' | 'ax1' | 'ax2' | 'ax3' | 'ax4' | 'ax5';
export type TextStyle =
  | 'largeTitle' | 'title1' | 'title2' | 'title3' | 'headline' | 'body'
  | 'callout' | 'subhead' | 'footnote' | 'caption1' | 'caption2';

export interface GlassPolicy {
  material?: GlassMaterial;
  renderer?: GlassRenderer;
  quality?: GlassQuality;
  theme?: GlassTheme;
  density?: GlassDensity;
  transparency?: GlassTransparency;
  motion?: GlassMotion;
  contrast?: GlassContrast;
  platform?: GlassPlatform;
}

/** Optical parameters per material and per glass size. Sizes are CSS pixels. */
export const materialTokens = {
  regular: {
    small: { blur: 14, saturation: 1.15, refraction: 18, edge: 16 },
    large: { blur: 40, saturation: 1.3, refraction: 26, edge: 22 },
  },
  clear: {
    small: { blur: 1.5, saturation: 1.08, refraction: 32, edge: 18 },
    large: { blur: 6, saturation: 1.12, refraction: 40, edge: 24 },
  },
} as const;

/**
 * Touch metrics. The heights here are the iOS ones and are what the stylesheet's
 * `--lg-height-*` tokens hold by default; on a pointer CSS substitutes the table below, so
 * `controlHeight` is the number to reason about in TypeScript rather than the number that will
 * necessarily be drawn. `radius` is not switched by platform: it feeds the refraction geometry,
 * and changing the lens's shape by pointer kind is a different decision from changing its size.
 */
export const densityTokens = {
  compact: { controlHeight: 36, radius: 12, gap: 6 },
  comfortable: { controlHeight: 44, radius: 18, gap: 8 },
} as const;

/** The same two for a pointer, which needs less of a target than a fingertip. See `tokens.css`. */
export const desktopDensityTokens = {
  compact: { controlHeight: 32, radius: 12, gap: 6 },
  comfortable: { controlHeight: 36, radius: 18, gap: 8 },
} as const;

export const motionTokens = { press: 90, release: 220, layout: 280, spring: 520, overlay: 360 } as const;

/** 4pt grid plus the HIG layout metrics that components read from TypeScript. */
export const spacingTokens = {
  space1: 4, space2: 8, space3: 12, space4: 16, space5: 20, space6: 24, space8: 32, space10: 40,
  margin: 16, marginRegular: 20, hitMin: 44, readable: 672, sidebarWidth: 260, controlGap: 8,
} as const;

/** Fixed radii. Capsule is height/2; concentric radii come from `concentricRadius` in core. */
export const radiusTokens = {
  xs: 6, s: 10, m: 14, l: 20, xl: 26, xxl: 34, sheet: 38, window: 24,
} as const;

/**
 * iOS text styles at the Large (default) content size. `tracking` is in em, taken
 * from the HIG "1/1000 em" column so it survives Dynamic Type scaling.
 * 11pt (caption2) is the floor for readable text — nothing may go below it.
 */
export const textStyles: Record<TextStyle, { size: number; leading: number; tracking: number; weight: number; emphasizedWeight: number }> = {
  largeTitle: { size: 34, leading: 41, tracking: .012, weight: 400, emphasizedWeight: 700 },
  title1: { size: 28, leading: 34, tracking: .014, weight: 400, emphasizedWeight: 700 },
  title2: { size: 22, leading: 28, tracking: -.012, weight: 400, emphasizedWeight: 700 },
  title3: { size: 20, leading: 25, tracking: -.023, weight: 400, emphasizedWeight: 600 },
  headline: { size: 17, leading: 22, tracking: -.026, weight: 600, emphasizedWeight: 600 },
  body: { size: 17, leading: 22, tracking: -.026, weight: 400, emphasizedWeight: 600 },
  callout: { size: 16, leading: 21, tracking: -.020, weight: 400, emphasizedWeight: 600 },
  subhead: { size: 15, leading: 20, tracking: -.016, weight: 400, emphasizedWeight: 600 },
  footnote: { size: 13, leading: 18, tracking: -.006, weight: 400, emphasizedWeight: 600 },
  caption1: { size: 12, leading: 16, tracking: 0, weight: 400, emphasizedWeight: 600 },
  caption2: { size: 11, leading: 13, tracking: .006, weight: 400, emphasizedWeight: 600 },
};

/** Multiplier applied to the whole type scale per Dynamic Type content size. */
export const textScale: Record<TextSize, number> = {
  xs: .824, s: .882, m: .941, l: 1, xl: 1.118, xxl: 1.235, xxxl: 1.353,
  ax1: 1.647, ax2: 1.941, ax3: 2.353, ax4: 2.765, ax5: 3.118,
};

/** Overlay stacking bands. A new overlay picks the band it belongs to. */
export const zIndexTokens = {
  content: 0, scrollEdge: 10, sidebar: 15, tabBar: 20,
  sheetBackdrop: 30, sheet: 31, menu: 40, alert: 41, toast: 60,
} as const;

export const defaultPolicy: Required<GlassPolicy> = {
  material: 'regular', renderer: 'auto', quality: 'balanced', theme: 'system',
  density: 'comfortable', transparency: 'system', motion: 'system', contrast: 'system',
  platform: 'auto',
};

import { BoundedCache } from './cache.js';
import { createDisplacementMap, displacementKey, type MapOptions } from './geometry.js';
export interface EncodedMap { url: string; width: number; height: number }
const maps = new BoundedCache<EncodedMap>();
let generated = 0;
let observers = 0;
export function trackObserver(delta: 1 | -1): void { observers = Math.max(0, observers + delta); }
export function getGlassDiagnostics() { return { ...maps.stats, generated, observers }; }
export function clearGlassCache(): void { maps.clear(); }
/** Call on the client only. No DOM screenshots or cross-origin pixel reads. */
export function getDisplacementTexture(options: MapOptions): EncodedMap | null {
  if (typeof document === 'undefined') return null;
  const key = displacementKey(options), hit = maps.get(key);
  if (hit) return hit;
  try {
    const map = createDisplacementMap(options);
    const canvas = document.createElement('canvas'); canvas.width = map.width; canvas.height = map.height;
    const context = canvas.getContext('2d'); if (!context) return null;
    const image = context.createImageData(map.width, map.height); image.data.set(map.data); context.putImageData(image, 0, 0);
    const value = { url: canvas.toDataURL('image/png'), width: map.cssWidth, height: map.cssHeight };
    maps.set(key, value, value.url.length * 2); generated++;
    return value;
  } catch { return null; }
}
/** Syntax detection only; never interpreted as visual correctness or certification. */
export function supportsSvgBackdrop(): boolean {
  return typeof CSS !== 'undefined' && CSS.supports('backdrop-filter', 'url("#glass-probe")');
}

/** Bounded LRU, accounting an explicit approximate retained-byte budget. */
export class BoundedCache<T> {
  private entries = new Map<string, { value: T; bytes: number }>();
  private bytes = 0;
  /* Declared as plain fields rather than constructor parameter properties: that syntax emits
     code, which Node's type stripping refuses, and the unit tests import this source directly. */
  readonly maxEntries: number;
  readonly maxBytes: number;
  constructor(maxEntries = 24, maxBytes = 8 * 1024 * 1024) {
    if (!Number.isFinite(maxEntries) || !Number.isFinite(maxBytes) || maxEntries < 1 || maxBytes < 1) throw new RangeError('Cache limits must be positive');
    this.maxEntries = maxEntries;
    this.maxBytes = maxBytes;
  }
  get(key: string): T | undefined {
    const entry = this.entries.get(key);
    if (!entry) return undefined;
    this.entries.delete(key); this.entries.set(key, entry); return entry.value;
  }
  set(key: string, value: T, bytes: number): void {
    if (!Number.isFinite(bytes) || bytes < 0) throw new RangeError('bytes must be finite and nonnegative');
    this.delete(key);
    if (bytes > this.maxBytes) return;
    this.entries.set(key, { value, bytes }); this.bytes += bytes;
    while (this.entries.size > this.maxEntries || this.bytes > this.maxBytes) this.delete(this.entries.keys().next().value!);
  }
  delete(key: string): void { const old = this.entries.get(key); if (old) this.bytes -= old.bytes; this.entries.delete(key); }
  clear(): void { this.entries.clear(); this.bytes = 0; }
  get stats(): { entries: number; bytes: number; maxEntries: number; maxBytes: number } {
    return { entries: this.entries.size, bytes: this.bytes, maxEntries: this.maxEntries, maxBytes: this.maxBytes };
  }
}

/**
 * Concentric corner radii (WWDC25/356, SwiftUI `ConcentricRectangle`).
 *
 * A shape nested inside a rounded container must share its centre of curvature:
 * inner radius = container radius − the padding between them. Getting it wrong is
 * visible — too large reads as a *pinched* corner, too small as a *flared* one.
 * Components that also appear standalone pass a `minimum` so they keep a sane
 * radius when there is no container to be concentric with.
 */
export interface ConcentricOptions {
  /** Fallback radius when the container radius is unknown or the result would collapse. */
  minimum?: number;
  /** Upper bound, typically half the shorter side of the child. */
  maximum?: number;
}
function nonNegative(x: number, name: string): number {
  if (!Number.isFinite(x) || x < 0) throw new RangeError(`${name} must be finite and nonnegative`);
  return x;
}
export function concentricRadius(containerRadius: number, inset: number, options: ConcentricOptions = {}): number {
  nonNegative(containerRadius, 'containerRadius');
  nonNegative(inset, 'inset');
  const minimum = nonNegative(options.minimum ?? 0, 'minimum');
  const maximum = options.maximum === undefined ? Infinity : nonNegative(options.maximum, 'maximum');
  if (maximum < minimum) throw new RangeError('maximum must be at least minimum');
  return Math.min(maximum, Math.max(minimum, containerRadius - inset));
}
/** The padding that would make a child of `childRadius` concentric inside `containerRadius`. */
export function concentricInset(containerRadius: number, childRadius: number): number {
  nonNegative(containerRadius, 'containerRadius');
  nonNegative(childRadius, 'childRadius');
  return Math.max(0, containerRadius - childRadius);
}
/** Capsule radius for a control of this height: exactly half, never a fixed guess. */
export function capsuleRadius(height: number): number {
  return nonNegative(height, 'height') / 2;
}

/** Geometry-only displacement generation. No browser globals at module load. */
export interface MapOptions {
  width: number;
  height: number;
  radius?: number;
  edge?: number;
  maxResolution?: number;
}
export interface DisplacementMap {
  width: number;
  height: number;
  cssWidth: number;
  cssHeight: number;
  data: Uint8ClampedArray;
}
export const clamp = (x: number, low: number, high: number) => Math.max(low, Math.min(high, x));
function positive(x: number, name: string): number {
  if (!Number.isFinite(x) || x <= 0 || x > 16384) throw new RangeError(`${name} must be finite, positive and at most 16384 CSS pixels`);
  return x;
}
/** Signed distance, negative inside a rounded rectangle, in CSS pixels. */
export function roundedRectDistance(x: number, y: number, w: number, h: number, r: number): number {
  const radius = clamp(r, 0, Math.min(w, h) / 2);
  const qx = Math.abs(x - w / 2) - (w / 2 - radius);
  const qy = Math.abs(y - h / 2) - (h / 2 - radius);
  return Math.hypot(Math.max(qx, 0), Math.max(qy, 0)) + Math.min(Math.max(qx, qy), 0) - radius;
}
export function normalizedMapOptions(options: MapOptions): Required<MapOptions> {
  const width = Math.round(positive(options.width, 'width') * 2) / 2;
  const height = Math.round(positive(options.height, 'height') * 2) / 2;
  const radius = options.radius ?? 18;
  const edge = options.edge ?? 16;
  if (!Number.isFinite(radius) || !Number.isFinite(edge)) throw new RangeError('radius and edge must be finite');
  if (!Number.isFinite(options.maxResolution ?? 256)) throw new RangeError('resolution must be finite');
  return { width: Math.max(.5, width), height: Math.max(.5, height), radius: clamp(radius, 0, Math.min(width, height) / 2),
    edge: clamp(edge, 1, Math.min(width, height) / 2 || 1), maxResolution: clamp(Math.floor(options.maxResolution ?? 256), 16, 512) };
}
export function displacementKey(options: MapOptions): string {
  const o = normalizedMapOptions(options);
  return [o.width, o.height, o.radius, o.edge, o.maxResolution].join(':');
}
export function createDisplacementMap(options: MapOptions): DisplacementMap {
  const o = normalizedMapOptions(options);
  const ratio = Math.min(1, o.maxResolution / Math.max(o.width, o.height), Math.sqrt(131072 / (o.width * o.height)));
  const width = Math.max(1, Math.floor(o.width * ratio));
  const height = Math.max(1, Math.floor(o.height * ratio));
  const data = new Uint8ClampedArray(width * height * 4);
  const distance = (x: number, y: number) => roundedRectDistance(x, y, o.width, o.height, o.radius);
  for (let y = 0; y < height; y++) for (let x = 0; x < width; x++) {
    const px = (x + .5) / width * o.width, py = (y + .5) / height * o.height;
    const d = distance(px, py), i = (y * width + x) * 4;
    data[i] = 128; data[i + 1] = 128; data[i + 2] = 128; data[i + 3] = 255;
    if (d > 0 || d < -o.edge) continue;
    const nx = distance(px + .25, py) - distance(px - .25, py);
    const ny = distance(px, py + .25) - distance(px, py - .25);
    const length = Math.hypot(nx, ny) || 1;
    const weight = Math.pow(1 - clamp(-d / o.edge, 0, 1), 2);
    data[i] = Math.round(127.5 + nx / length * weight * 127.5);
    data[i + 1] = Math.round(127.5 + ny / length * weight * 127.5);
  }
  return { width, height, cssWidth: o.width, cssHeight: o.height, data };
}
/**
 * Polynomial smooth minimum of two signed distances: the union of two shapes with a liquid
 * fillet of blend radius `k` (CSS px) where they meet. Pure maths used to reason about droplet
 * fusion; the render path is an SVG goo filter, never a per-frame rasterisation.
 */
export function smoothUnion(d1: number, d2: number, k: number): number {
  if (!Number.isFinite(d1) || !Number.isFinite(d2)) throw new RangeError('distances must be finite');
  if (!Number.isFinite(k) || k <= 0) return Math.min(d1, d2);
  const h = clamp(.5 + .5 * (d2 - d1) / k, 0, 1);
  return d2 + (d1 - d2) * h - k * h * (1 - h);
}

export * from './geometry.js';
export * from './cache.js';
export * from './browser.js';
export * from './spring.js';
export * from './concentric.js';

/**
 * Damped-spring integrator. Pure maths plus a thin rAF driver, so the same curve
 * can run the press-time refraction, a sheet drag and any future scrub without
 * three copies of the loop. No browser globals are touched at module load.
 */
export interface SpringConfig {
  /** Restoring force. Higher = faster approach. */
  stiffness?: number;
  /** Velocity damping. Near 2*sqrt(stiffness) is critical; below it overshoots. */
  damping?: number;
  /** Distance below which the spring is considered settled. */
  precision?: number;
  /** Velocity below which the spring is considered settled. */
  restVelocity?: number;
}
export interface SpringState { value: number; velocity: number }
export const defaultSpring: Required<SpringConfig> = { stiffness: 320, damping: 22, precision: .05, restVelocity: .5 };

function finite(x: number, name: string): number {
  if (!Number.isFinite(x)) throw new RangeError(`${name} must be finite`);
  return x;
}

/**
 * Advance one step. `dt` is seconds and is clamped to 32ms so a backgrounded tab
 * resuming cannot integrate a single huge step and fling the value.
 */
export function advanceSpring(state: SpringState, target: number, dt: number, config: SpringConfig = {}): SpringState {
  const { stiffness, damping } = { ...defaultSpring, ...config };
  finite(state.value, 'value'); finite(state.velocity, 'velocity'); finite(target, 'target');
  if (!Number.isFinite(stiffness) || stiffness <= 0) throw new RangeError('stiffness must be positive and finite');
  if (!Number.isFinite(damping) || damping < 0) throw new RangeError('damping must be nonnegative and finite');
  const step = Math.max(0, Math.min(.032, Number.isFinite(dt) ? dt : .016));
  const acceleration = (target - state.value) * stiffness - state.velocity * damping;
  const velocity = state.velocity + acceleration * step;
  return { value: state.value + velocity * step, velocity };
}

/** True once the spring is close enough to its target to snap and stop the loop. */
export function springAtRest(state: SpringState, target: number, config: SpringConfig = {}): boolean {
  const { precision, restVelocity } = { ...defaultSpring, ...config };
  return Math.abs(target - state.value) < precision && Math.abs(state.velocity) < restVelocity;
}

export interface SpringHandle {
  /** Retarget; the loop starts if it is not already running. Velocity is preserved, so it is interruptible. */
  to(target: number): void;
  /** Jump to a value with no animation. */
  set(value: number): void;
  stop(): void;
  readonly value: number;
}

/**
 * rAF-driven spring. `apply` receives every intermediate value. Call on the client
 * only; without `requestAnimationFrame` it degrades to an immediate jump so SSR and
 * reduced-motion paths stay correct.
 */
export function createSpring(initial: number, apply: (value: number) => void, config: SpringConfig = {}): SpringHandle {
  let state: SpringState = { value: finite(initial, 'initial'), velocity: 0 };
  let target = initial, frame = 0, last = 0;
  const animated = typeof requestAnimationFrame === 'function';
  const stop = () => { if (frame) cancelAnimationFrame(frame); frame = 0; last = 0; };
  const step = (now: number) => {
    const dt = last ? (now - last) / 1000 : .016; last = now;
    state = advanceSpring(state, target, dt, config);
    if (springAtRest(state, target, config)) { state = { value: target, velocity: 0 }; apply(state.value); stop(); return; }
    apply(state.value);
    frame = requestAnimationFrame(step);
  };
  return {
    to(next) {
      target = finite(next, 'target');
      if (!animated) { state = { value: target, velocity: 0 }; apply(target); return; }
      if (!frame) { last = 0; frame = requestAnimationFrame(step); }
    },
    set(value) { stop(); state = { value: finite(value, 'value'), velocity: 0 }; target = state.value; apply(state.value); },
    stop,
    get value() { return state.value; },
  };
}

'use client';
import { type CSSProperties, type HTMLAttributes, type RefAttributes } from 'react';
import { cx } from '../system/utils.js';

export interface CardProps extends HTMLAttributes<HTMLDivElement>, RefAttributes<HTMLDivElement> {
  /** Corner radius in CSS px. Children marked `Concentric` derive their radius from it. */
  radius?: number;
  /** Inner padding in CSS px. This is also the inset a concentric child subtracts. */
  padding?: number;
  /**
   * `grouped` (default) is the card-on-a-grouped-background pairing used by settings and
   * feed layouts; `plain` sits directly on the app background.
   */
  fill?: 'grouped' | 'plain' | 'secondary';
  /** A resting shadow. Cards are content, so this stays subtle — it is not a glass lift. */
  raised?: boolean;
}

/**
 * A content-layer container. Deliberately not glass: Liquid Glass belongs to the floating
 * control and navigation layer, and a page full of translucent cards is the single most
 * common way an interface stops looking like Apple's. Cards use solid grouped backgrounds
 * so the material above them has something to refract.
 */
export function Card(
  { radius = 26, padding = 16, fill = 'grouped', raised = false, className, style, children, ref, ...props }: CardProps,
) {
  return <div {...props} ref={ref} className={cx('lg-card', className)} data-fill={fill} data-raised={raised ? 'true' : undefined}
    style={{ '--lg-radius-container': `${radius}px`, '--lg-concentric-inset': `${padding}px`, padding: `${padding}px`, borderRadius: `${radius}px`, ...style } as CSSProperties}>
    {children}
  </div>;
}

export interface ConcentricProps extends HTMLAttributes<HTMLDivElement>, RefAttributes<HTMLDivElement> {
  /** Fallback radius for when this element also appears outside a container. */
  minimum?: number;
}
/**
 * Gives a nested element a radius concentric with its container: container radius minus the
 * padding between them, so both corners share a centre of curvature. Getting this wrong is
 * visible — too large reads as a pinched corner, too small as a flared one. Resolved in CSS
 * from the container's own custom properties, so it survives a retune of the radius scale.
 */
export function Concentric({ minimum = 0, className, style, children, ref, ...props }: ConcentricProps) {
  return <div {...props} ref={ref} className={cx('lg-concentric', className)}
    style={{ '--lg-concentric-min': `${minimum}px`, ...style } as CSSProperties}>{children}</div>;
}

'use client';
import { useEffect, useId, useRef, useState, type HTMLAttributes, type ReactNode, type RefAttributes } from 'react';
import { LibraryIcon } from '../system/icon.js';
import { useGlassPolicy } from '../system/provider.js';
import { cx, useControllable } from '../system/utils.js';

export interface DisclosureGroupProps extends Omit<HTMLAttributes<HTMLDetailsElement>, 'onToggle' | 'title'>,
  RefAttributes<HTMLDetailsElement> {
  /**
   * What is behind it, named. "Advanced options", not "More" — the label is the only thing
   * someone has to decide from, and a label that says nothing makes the control a lottery.
   */
  label: ReactNode;
  /** A second line under the label, for the part that does not belong in the label itself. */
  secondaryLabel?: ReactNode;
  children: ReactNode;
  open?: boolean;
  defaultOpen?: boolean;
  onOpenChange?: (open: boolean) => void;
}

/**
 * A row that hides something, on a real `<details>`.
 *
 * The disclosure is native because everything that makes it work is: find-in-page opens a
 * closed `<details>` to reveal a match, the summary is already a button to assistive
 * technology, and Enter and Space already work. A `div` with an `onClick` and `aria-expanded`
 * reimplements three of those and silently drops the first.
 *
 * Content layer — a disclosure is a row of content that folds, not a floating control.
 *
 * Put the thing most people need **above** this, unfolded. A disclosure is for the minority
 * case; if the common one is inside it, everyone pays a click for it.
 */
export function DisclosureGroup({
  label, secondaryLabel, children, open: controlled, defaultOpen = false, onOpenChange,
  className, id: providedId, ref, ...props
}: DisclosureGroupProps) {
  const generated = useId(); const id = providedId ?? generated;
  const [open, setOpen] = useControllable(controlled, defaultOpen, onOpenChange);
  const details = useRef<HTMLDetailsElement>(null);
  const policy = useGlassPolicy();

  /**
   * `<details>` opens itself when the user activates the summary, and when find-in-page
   * reveals a match inside it. Both change the element without going through React, so the
   * state is read back off the element rather than assumed from the click.
   */
  useEffect(() => {
    const node = details.current; if (!node) return;
    const sync = () => setOpen(node.open);
    node.addEventListener('toggle', sync);
    return () => node.removeEventListener('toggle', sync);
  }, [setOpen]);

  // Keep the element in step when the caller drives it.
  useEffect(() => {
    const node = details.current;
    if (node && node.open !== open) node.open = open;
  }, [open]);

  /**
   * Animating to `auto` needs `interpolate-size`, which is not everywhere yet. Where it is
   * missing the content is measured once and published as a length, which is the same
   * animation by another route. Reduce Motion skips both and just shows it.
   */
  const body = useRef<HTMLDivElement>(null);
  const [height, setHeight] = useState<number | null>(null);
  useEffect(() => {
    if (policy.reduceMotion || typeof CSS === 'undefined' || CSS.supports('interpolate-size', 'allow-keywords')) return;
    const node = body.current; if (!node) return;
    const measure = () => setHeight(node.scrollHeight);
    measure();
    const observer = new ResizeObserver(measure); observer.observe(node);
    return () => observer.disconnect();
  }, [policy.reduceMotion, children]);

  return <details {...props} id={id} ref={node => {
    details.current = node;
    if (typeof ref === 'function') ref(node); else if (ref) ref.current = node;
  }} className={cx('lg-disclosure', className)} data-open={open ? 'true' : undefined}
    style={height === null ? props.style : { ...props.style, '--lg-disclosure-height': `${height}px` } as React.CSSProperties}>
    <summary className="lg-disclosure-summary">
      <span className="lg-disclosure-labels">
        <span className="lg-disclosure-label">{label}</span>
        {secondaryLabel && <span className="lg-disclosure-secondary">{secondaryLabel}</span>}
      </span>
      {/* Decoration: the summary is already announced as expanded or collapsed. */}
      <LibraryIcon name="chevronForward" size={15} className="lg-disclosure-chevron" aria-hidden="true" />
    </summary>
    <div ref={body} className="lg-disclosure-body">{children}</div>
  </details>;
}

