'use client';
import { useId, type CSSProperties, type HTMLAttributes, type ReactNode, type RefAttributes } from 'react';
import { cx } from '../system/utils.js';

export interface GroupBoxProps extends Omit<HTMLAttributes<HTMLDivElement>, 'title'>, RefAttributes<HTMLDivElement> {
  /**
   * A short phrase describing what is inside, in sentence case and without ending punctuation.
   * Drawn *above* the box, which is where macOS puts it, and wired to the box with
   * `aria-labelledby` so a screen reader announces the group by that name rather than
   * announcing a box and leaving the reader to work out what it holds.
   */
  title?: ReactNode;
  /** One line under the title, for when the title cannot carry the whole relationship. */
  description?: ReactNode;
  children: ReactNode;
  /** A box separates by background or by border. Not both — two devices for one job. */
  variant?: 'fill' | 'outline';
  radius?: number;
  padding?: number;
}

/**
 * A visually distinct group of related content.
 *
 * The HIG's boxes page is short and every sentence of it is a constraint:
 *
 * - **A border *or* a background**, hence `variant` rather than both at once.
 * - **Keep it small relative to its container.** A box the size of the window stops separating
 *   anything, and that is a caller's decision this component cannot make — it is in the
 *   documentation because there is nowhere else for it to live.
 * - **Don't nest boxes.** Use padding and alignment for subgroups instead; the stylesheet does
 *   not style a box inside a box specially, which is the honest way to say "don't".
 * - **The title goes above the box** on macOS, and the title is optional.
 *
 * Content layer, always. A box is a region of the page, not something floating over it.
 *
 * Against `Card`: a card is a *surface* that carries something — it has a fill, a radius and a
 * shadow, and it is the thing you tap in a feed. A box is a *boundary* around things that
 * belong together, and its title is part of the grouping rather than the content. They look
 * similar and they answer different questions, which is why the box carries a `role="group"`
 * and the card does not.
 */
export function GroupBox({
  title, description, children, variant = 'fill', radius = 14, padding = 16,
  className, style, ref, ...props
}: GroupBoxProps) {
  const generated = useId();
  const labelId = `${generated}-title`;
  return <div {...props} ref={ref} className={cx('lg-groupbox', className)} data-variant={variant}
    style={{ '--lg-radius-container': `${radius}px`, '--lg-concentric-inset': `${padding}px`, ...style } as CSSProperties}>
    {title !== undefined && <div className="lg-groupbox-title" id={labelId}>{title}</div>}
    {description !== undefined && <div className="lg-groupbox-description">{description}</div>}
    <div className="lg-groupbox-body" role="group" aria-labelledby={title !== undefined ? labelId : undefined}
      style={{ padding: `${padding}px`, borderRadius: `${radius}px` }}>
      {children}
    </div>
  </div>;
}

'use client';
import { type HTMLAttributes, type RefAttributes } from 'react';
import { MODIFIER_ORDER, glyphFor, splitKeys, useCommandKey, type Modifier } from '../system/shortcut.js';
import { cx } from '../system/utils.js';

export interface KbdProps extends Omit<HTMLAttributes<HTMLElement>, 'children'>, RefAttributes<HTMLElement> {
  /**
   * The shortcut, as `"⌘K"`, `"Cmd+Shift+P"` or `"mod k"`. Words are turned into glyphs and
   * modifiers are put in the platform's order; anything unrecognised is passed through as
   * typed, so a key this does not know about still renders.
   *
   * `mod` is the one that is resolved rather than translated: Command on Apple hardware,
   * Control everywhere else — the same resolution `useShortcut` binds, so the hint and the
   * binding cannot say different things.
   */
  keys: string;
  /**
   * What a screen reader hears. Defaults to the shortcut spelled out in words, because the
   * glyphs on their own are announced as anything from silence to "place of interest sign".
   */
  'aria-label'?: string;
}

const SPOKEN: Record<string, string> = { '⌃': 'Control', '⌥': 'Option', '⇧': 'Shift', '⌘': 'Command', '↩': 'Return', '⎋': 'Escape', '⇥': 'Tab', '⌫': 'Delete', '␣': 'Space' };

/**
 * A keyboard shortcut, rendered the way the platform renders one.
 *
 * Two things it exists to get right, both of which were being done by hand. The **order** of
 * modifiers is not a preference — ⌃ ⌥ ⇧ ⌘, always, with Command nearest the key. And the
 * glyphs are silent or nonsensical to a screen reader, so the element carries words: "⌘K"
 * announces as "Command K" rather than as one unpronounceable character followed by a letter.
 *
 * Content layer. A shortcut hint is text about a command, not a control.
 */
export function Kbd({ keys, 'aria-label': label, className, ref, ...props }: KbdProps) {
  /**
   * `mod` is the only part that changes with the machine, and deliberately so.
   *
   * The first version of this also swapped the glyphs for words away from Apple hardware —
   * "Ctrl+Alt+Delete" rather than ⌃⌥⌫ — on the reasoning that ⌃ is not printed on a PC
   * keycap. That is true and it is not this component's decision to make: a caller who wrote
   * `"ctrl alt delete"` asked for those keys, and `kbd.spec.ts` was right to fail. The defect
   * being fixed here is narrower than that, and only this: a hint that reads ⌘K while
   * `useShortcut` listens for Ctrl+K is a lie printed on the screen.
   */
  const commandKey = useCommandKey();
  const parts = splitKeys(keys).map(part => (part.toLowerCase() === 'mod'
    ? (commandKey ? '⌘' : '⌃')
    : glyphFor(part)));
  const modifiers = MODIFIER_ORDER.filter(symbol => parts.includes(symbol));
  const rest = parts.filter(part => !MODIFIER_ORDER.includes(part as Modifier));
  const ordered = [...modifiers, ...rest];
  const spoken = ordered.map(part => SPOKEN[part] ?? part).join(' ');

  return <kbd {...props} ref={ref} className={cx('lg-kbd', className)} aria-label={label ?? spoken}>
    {/* The glyphs are decoration once the element has words of its own. */}
    <span aria-hidden="true">{ordered.join('')}</span>
  </kbd>;
}

'use client';
import { type HTMLAttributes, type LiHTMLAttributes, type MouseEvent, type ReactNode, type RefAttributes } from 'react';
import { cx } from '../system/utils.js';
import { LibraryIcon } from '../system/icon.js';
import { Text } from './text.js';

export interface ListProps extends HTMLAttributes<HTMLDivElement>, RefAttributes<HTMLDivElement> {
  /**
   * `insetGrouped` is the settings/forms style: rounded groups inset from the margins.
   * `plain` runs edge to edge for long homogeneous content.
   */
  variant?: 'insetGrouped' | 'plain';
}
/** A content-layer list. Rows are solid; the glass belongs to the bars floating above them. */
export function List({ variant = 'insetGrouped', className, ref, ...props }: ListProps) {
  return <div {...props} ref={ref} data-variant={variant} className={cx('lg-list', className)} />;
}

export interface ListSectionProps extends Omit<HTMLAttributes<HTMLElement>, 'title'>, RefAttributes<HTMLElement> {
  /**
   * Title-style capitalization, not ALL CAPS — the uppercase section header was retired
   * in the iOS 26 design. Pass the words as you want them read.
   */
  header?: ReactNode;
  footer?: ReactNode;
  /**
   * The header's heading level. A group label is a real heading — someone moving by heading uses
   * it to find the group — so it cannot simply stop being one; what it can do is sit at the
   * right depth. `3` suits a list under a page title and a section title, which is the common
   * case; lower it when the list is nested deeper than that.
   */
  headingLevel?: 1 | 2 | 3 | 4 | 5 | 6;
  children: ReactNode;
}
export function ListSection({ header, footer, headingLevel = 3, children, className, ref, ...props }: ListSectionProps) {
  return <section {...props} ref={ref} className={cx('lg-list-section', className)}>
    {header && <Text as={`h${headingLevel}` as const} variant="subhead" emphasized tone="secondary" className="lg-list-header">{header}</Text>}
    <ul className="lg-list-group" role="list">{children}</ul>
    {footer && <Text variant="footnote" tone="secondary" className="lg-list-footer">{footer}</Text>}
  </section>;
}

/**
 * Two keys are taken back from `<li>`: its `value` is the ordered-list number, and its
 * `onSelect` is the text-selection event. A row's `value` is the trailing read-out and its
 * `onSelect` is the row being chosen, which is what a caller means by either word here.
 */
export interface ListRowProps extends Omit<LiHTMLAttributes<HTMLLIElement>, 'value' | 'onSelect'>, RefAttributes<HTMLLIElement> {
  label: ReactNode;
  /** A second line under the label, for context that does not belong in the label itself. */
  secondaryLabel?: ReactNode;
  /** Trailing read-only value, e.g. the current setting. */
  value?: ReactNode;
  /** Leading glyph or avatar. Separators inset past it, as the system does. */
  leading?: ReactNode;
  /** Trailing interactive element (a switch, a stepper). Suppresses the disclosure chevron. */
  accessory?: ReactNode;
  href?: string;
  onSelect?: (event: MouseEvent<HTMLElement>) => void;
  /** Force the chevron on or off; by default it appears for navigating rows. */
  disclosure?: boolean;
  destructive?: boolean;
  disabled?: boolean;
}
/**
 * One row. Navigating rows render as a real link or button so keyboard and assistive
 * technology get the right affordance — a `div` with an onClick is not a row, it is a trap.
 * Minimum height is the 44pt hit region even when the text is a single short line.
 */
export function ListRow({ label, secondaryLabel, value, leading, accessory, href, onSelect, disclosure, destructive, disabled, className, ref, ...props }: ListRowProps) {
  const interactive = !!href || !!onSelect;
  const showChevron = disclosure ?? (interactive && !accessory);
  const body = <>
    {leading && <span className="lg-row-leading" aria-hidden="true">{leading}</span>}
    <span className="lg-row-labels">
      <Text as="span" variant="body" tone={destructive ? 'destructive' : 'primary'} className="lg-row-label">{label}</Text>
      {secondaryLabel && <Text as="span" variant="footnote" tone="secondary" className="lg-row-secondary">{secondaryLabel}</Text>}
    </span>
    {value !== undefined && <Text as="span" variant="body" tone="secondary" className="lg-row-value">{value}</Text>}
    {accessory && <span className="lg-row-accessory">{accessory}</span>}
    {showChevron && <LibraryIcon name="chevronForward" size={17} className="lg-row-chevron" />}
  </>;
  return <li {...props} ref={ref} className={cx('lg-list-row', className)} data-interactive={interactive ? 'true' : undefined} data-disabled={disabled ? 'true' : undefined}>
    {href && !disabled
      ? <a className="lg-row-hit" href={href} draggable={false} onClick={onSelect}>{body}</a>
      : onSelect || href
        /**
         * A disabled navigating row drops its `href` rather than keeping it and adding
         * `aria-disabled`: an anchor with an href navigates on Enter and on click whatever
         * ARIA says about it. `aria-disabled` describes the button; `disabled` is what makes
         * it true, and it is what takes the row out of the tab order.
         */
        ? <button className="lg-row-hit" type="button" onClick={onSelect} disabled={disabled} aria-disabled={disabled || undefined}>{body}</button>
        : <div className="lg-row-hit">{body}</div>}
  </li>;
}

'use client';
import { type HTMLAttributes, type RefAttributes } from 'react';
import type { StandardMaterial } from '../../tokens/index.js';
import { cx } from '../system/utils.js';

export interface MaterialViewProps extends HTMLAttributes<HTMLDivElement>, RefAttributes<HTMLDivElement> {
  /**
   * Thicker materials give text more contrast; thinner ones keep more of the context
   * behind them. Choose by what the surface is for, never by the colour it happens to
   * produce over today's background.
   */
  thickness?: StandardMaterial;
  radius?: number;
}

/**
 * A *standard material* — the content layer's translucency tool, and the right answer
 * whenever the instinct is to reach for glass on something that does not float. It blurs
 * and tints, but it does not lens, does not carry a specular rim and does not flip with its
 * backdrop, because it is part of the content rather than hovering above it.
 *
 * Use vibrant label tones on top (`Text tone="secondary"`), and avoid `quaternary` on the
 * thin and ultraThin variants, where it falls below readable contrast.
 */
export function MaterialView({ thickness = 'regular', radius = 20, className, style, children, ref, ...props }: MaterialViewProps) {
  return <div {...props} ref={ref} className={cx('lg-material-view', className)} data-thickness={thickness}
    style={{ borderRadius: `${radius}px`, ...style }}>{children}</div>;
}

'use client';
import { createElement, type ElementType, type HTMLAttributes, type RefAttributes } from 'react';
import type { TextStyle } from '../../tokens/index.js';
import { cx } from '../system/utils.js';

export type TextTone = 'primary' | 'secondary' | 'tertiary' | 'quaternary' | 'accent' | 'destructive';

export interface TextProps extends Omit<HTMLAttributes<HTMLElement>, 'color'>, RefAttributes<HTMLElement> {
  /**
   * An iOS text style, not a size. Styles carry size, leading and tracking together and
   * scale with Dynamic Type; picking `caption2` and then overriding font-size defeats both.
   */
  variant?: TextStyle;
  /** Semibold/bold companion of the style, per the HIG "Emphasized" column. */
  emphasized?: boolean;
  tone?: TextTone;
  /**
   * The element to render. Defaults to `p` — headings are never inferred, because guessing
   * a level is how documents end up with three `h1`s and an unusable rotor. Pass `as="h2"`.
   */
  as?: ElementType;
  /** Columns of figures and timers line up only with tabular digits. */
  tabular?: boolean;
}

export function Text({ variant = 'body', emphasized = false, tone = 'primary', as = 'p', tabular = false, className, ref, ...props }: TextProps) {
  return createElement(as, {
    ...props,
    ref,
    'data-variant': variant,
    'data-tone': tone,
    'data-emphasized': emphasized ? 'true' : undefined,
    'data-tabular': tabular ? 'true' : undefined,
    className: cx('lg-text', className),
  });
}

'use client';
import { useEffect, useRef, type HTMLAttributes, type ReactNode, type RefAttributes } from 'react';
import { useGlassPolicy } from '../system/provider.js';
import { cx, useMergedRef } from '../system/utils.js';

export interface GlassBadgeProps extends Omit<HTMLAttributes<HTMLSpanElement>, 'children'>, RefAttributes<HTMLSpanElement> {
  /** A count, or text for a status badge. Counts above `max` render as "max+". */
  count?: number;
  max?: number;
  children?: ReactNode;
  tone?: 'notification' | 'neutral' | 'accent';
  /** A bare dot, for "something changed" with no useful number. */
  dot?: boolean;
  /**
   * Badges are read out on their own, so say what the number means. Without this a screen
   * reader announces a naked "3".
   */
  'aria-label'?: string;
}

/**
 * Colour alone never carries the meaning here: the badge always contains a number or a
 * label, and the accessible name spells out what it counts.
 */
export function GlassBadge({ count, max = 99, children, tone = 'notification', dot = false, className, ref, ...props }: GlassBadgeProps) {
  const text = dot ? null : children ?? (count === undefined ? null : count > max ? `${max}+` : String(count));
  const [node, mergedRef] = useMergedRef<HTMLSpanElement>(ref);
  const reduceMotion = useGlassPolicy().reduceMotion;

  /**
   * A number that changed should look like it changed.
   *
   * Two unread becoming three is the whole message a badge carries, and swapping the glyph
   * between frames is the one way to deliver it that the eye can miss entirely. Driven from
   * script rather than a class, because the trigger is the *content* changing — CSS has no
   * selector for that, and the usual workaround (flip an attribute to restart a keyframe) is
   * the same animation with a harder-to-read implementation. Script also means the stylesheet's
   * blanket `animation: none` does not reach it, so the preference is asked about here.
   *
   * Only after the first render: a badge appearing is already motion, and bouncing it on
   * arrival would be two animations telling the reader one thing.
   */
  const previous = useRef<string | null>(null);
  useEffect(() => {
    // The count only. Arbitrary `children` may be an element, and two elements are never
    // usefully comparable — a badge whose content is a node is not reporting a number.
    const value = dot || children !== undefined || text === null ? null : String(text);
    const was = previous.current;
    previous.current = value;
    if (was === null || was === value || value === null || reduceMotion) return;
    node.current?.animate(
      [{ transform: 'scale(1)' }, { transform: 'scale(1.22)', offset: .35 }, { transform: 'scale(1)' }],
      { duration: 320, easing: 'cubic-bezier(.2,.8,.2,1)' });
  }, [text, dot, children, reduceMotion, node]);

  if (!dot && (text === null || text === '')) return null;
  return <span {...props} ref={mergedRef} className={cx('lg-badge', className)} data-tone={tone} data-dot={dot ? 'true' : undefined}>{text}</span>;
}

'use client';
import { useEffect, type ButtonHTMLAttributes, type CSSProperties, type ReactNode, type RefAttributes } from 'react';
import { useGlassSurface, type GlassSurfaceOptions } from '../system/material.js';
import { useSharedSurface } from '../system/surface.js';
import { inDevelopment, warnOnce } from '../system/warn.js';
import { cx } from '../system/utils.js';

/**
 * Style — not size — is what marks the preferred option, and a view should carry at most
 * one prominent button. Everything else stays regular, or the emphasis means nothing.
 *
 * `glass` / `glassProminent` are the floating control-layer styles. `plain`, `gray` and
 * `tinted` are flat and belong wherever a button sits *in* content rather than above it.
 */
export type GlassButtonVariant =
  | 'glass' | 'glassProminent' | 'plain' | 'gray' | 'tinted' | 'destructive' | 'destructiveProminent';
/** Control heights. `small` keeps a 44pt hit region on touch via padding, not a smaller target. */
export type ControlSize = 'small' | 'regular' | 'large' | 'extraLarge';

export interface GlassButtonProps extends ButtonHTMLAttributes<HTMLButtonElement>, RefAttributes<HTMLButtonElement>, GlassSurfaceOptions {
  variant?: GlassButtonVariant;
  /** Visual height of the control. Distinct from `size`, which selects the glass thickness. */
  controlSize?: ControlSize;
  loading?: boolean;
  /** Keep this button's own glass even inside a shared surface. Use sparingly — it is glass on glass. */
  independent?: boolean;
  /**
   * Leading glyph. A slot rather than a child, so the gap between the icon and the words is
   * the same on every button instead of whatever each caller typed between them.
   */
  icon?: ReactNode;
  /** Trailing glyph — a chevron, a disclosure. */
  trailingIcon?: ReactNode;
  /**
   * This button's accent, overriding `--lg-accent` for it alone. One screen can carry
   * differently-toned actions — a green Confirm beside a blue Continue.
   *
   * Any CSS colour. It is not enough on its own: a tint needs a label colour that reads on
   * it, which cannot be derived, so `tintContrast` is the other half and development mode
   * measures the pair and complains if it falls under 4.5:1.
   */
  tint?: string;
  /** The label colour on `tint`. White by default, which is right for most saturated tints. */
  tintContrast?: string;
}

type Rgba = [number, number, number, number];

/**
 * A resolved colour from a computed style: `rgb()`, `rgba()`, or the `color(srgb r g b / a)`
 * form Chrome hands back for anything that went through `color-mix()` — which is every
 * accent-derived value in this stylesheet. Its channels run 0–1, not 0–255, and reading them
 * as bytes turns any accent into near-black, which measures beautifully against a light page.
 */
function parseColour(value: string): Rgba | null {
  const parts = value.match(/[\d.]+/g);
  if (!parts || parts.length < 3) return null;
  const scale = value.startsWith('color(') ? 255 : 1;
  return [Number(parts[0]) * scale, Number(parts[1]) * scale, Number(parts[2]) * scale,
    parts.length > 3 ? Number(parts[3]) : 1];
}

/** `over` composited onto `under`, both straight sRGB. */
const composite = (over: Rgba, under: Rgba): Rgba =>
  [0, 1, 2].map(i => over[i] * over[3] + under[i] * (1 - over[3])).concat(1) as Rgba;

/** Relative luminance, per WCAG. */
function luminance([r, g, b]: Rgba): number {
  const [lr, lg, lb] = [r, g, b].map(channel => {
    const value = channel / 255;
    return value <= 0.03928 ? value / 12.92 : ((value + 0.055) / 1.055) ** 2.4;
  });
  return 0.2126 * lr + 0.7152 * lg + 0.0722 * lb;
}

/**
 * What is painted behind this button's label, flattened.
 *
 * The layers, front to back: the tint layer inside the button's own decoration — which is where
 * a glass button's accent lives, rather than in its `background-color` — then the button, then
 * every ancestor until something opaque. A translucent wash over a white page and the same wash
 * over a dark one are different colours, and the whole question is what the reader sees.
 */
function paintedBehind(node: HTMLElement): Rgba {
  const layers: Rgba[] = [];
  const tint = node.querySelector<HTMLElement>(':scope > .lg-decoration .lg-tint');
  if (tint) {
    const style = getComputedStyle(tint);
    const colour = parseColour(style.backgroundColor);
    // `opacity` on the layer multiplies the alpha of the fill it carries.
    if (colour) layers.push([colour[0], colour[1], colour[2], colour[3] * Number(style.opacity || 1)]);
  }
  for (let element: HTMLElement | null = node; element; element = element.parentElement) {
    const colour = parseColour(getComputedStyle(element).backgroundColor);
    if (colour && colour[3] > 0) {
      layers.push(colour);
      if (colour[3] === 1) break;
    }
  }
  // A page that never declares an opaque background is white, the same as the browser paints it.
  return layers.reduceRight<Rgba>((under, over) => composite(over, under), [255, 255, 255, 1]);
}

const GLASSY = new Set<GlassButtonVariant>(['glass', 'glassProminent']);

export function GlassButton(
  { material, backdropTone, density, renderer, radius = 'pill', refraction, size, chroma,
    className, style, children, variant = 'glass', controlSize = 'regular', loading = false, disabled,
    independent = false, icon, trailingIcon, tint, tintContrast, type = 'button', ref, ...props }: GlassButtonProps,
) {
  const shared = useSharedSurface();
  // Flat variants never grow their own glass, and inside a shared surface neither does anything
  // else: the group is the glass, the children are items on it.
  const flat = !GLASSY.has(variant);
  const glass = useGlassSurface({ material, backdropTone, density, renderer, radius, refraction, size, chroma }, ref, (shared && !independent) || flat, true);
  /**
   * Emphasis is comparative: a second prominent button on the same surface means neither is
   * the preferred option any more, and the reader has to work out what to do from the labels.
   * Counted from the DOM rather than from a context, because the rule is about what ends up
   * next to what — two siblings from different parts of the tree still land on one bar.
   */
  useEffect(() => {
    if (!inDevelopment() || variant !== 'glassProminent') return;
    const node = glass.root.current; if (!node) return;
    const surface = node.parentElement?.closest<HTMLElement>('.lg-root'); if (!surface) return;
    // Keyed on the surface, not on the button: the problem is the pair, and both halves of it
    // run this effect. One message names the situation; two describe it twice.
    if (surface.querySelectorAll('.lg-button[data-variant="glassProminent"]').length > 1) {
      warnOnce(surface, 'two-prominent', 'two glassProminent buttons share one surface. A view has at most one preferred action; the rest stay regular, or the emphasis stops meaning anything.');
    }
  }, [glass.root, variant, children]);

  /**
   * A tint the caller chose, checked rather than trusted. The library cannot pick a readable
   * label colour — that is why there is no global `accent` prop — but it can measure the pair
   * the caller did pick and say so when the result is unreadable.
   *
   * Measured off the rendered button, not off the two props. The first version of this compared
   * `tint` with `tintContrast ?? '#fff'`, which is the pair a *prominent* button paints: white
   * on a solid accent. On `tinted`, `plain` and `destructive` the label is the tint itself over
   * a wash of it, so the check was measuring two colours that were nowhere on the screen — and
   * cheerfully passing a button that rendered at 2.87:1. A guard that measures the wrong pair is
   * worse than no guard: every caller downstream believes they have been looked at.
   */
  useEffect(() => {
    if (!inDevelopment() || !tint) return;
    const node = glass.root.current; if (!node) return;
    const ink = parseColour(getComputedStyle(node).color);
    if (!ink) return;
    const behind = paintedBehind(node);
    const pair = [luminance(composite(ink, behind)), luminance(behind)];
    const ratio = (Math.max(...pair) + 0.05) / (Math.min(...pair) + 0.05);
    if (ratio < 4.5) {
      warnOnce(node, 'tint-contrast',
        `tint ${tint} renders as rgb(${ink.slice(0, 3).map(Math.round).join(' ')}) on rgb(${behind.slice(0, 3).map(Math.round).join(' ')}) — ${ratio.toFixed(2)}:1, under the 4.5:1 floor. Pass tintContrast, or darken the tint.`);
    }
  }, [glass.root, tint, tintContrast, variant]);

  const tinted = tint
    ? { '--lg-accent': tint, '--lg-accent-contrast': tintContrast ?? '#fff' } as CSSProperties
    : undefined;

  return <button {...props} ref={glass.ref} type={type} disabled={disabled || loading} aria-busy={loading || undefined}
    {...glass.attributes} data-variant={variant} data-control-size={controlSize}
    className={cx('lg-root lg-button', className)} style={{ ...glass.style, ...tinted, ...style }}>
    {glass.decoration}<span className="lg-content">
      {loading && <span className="lg-spinner" aria-hidden="true" />}
      {/* Decoration: an icon beside a label says nothing the label does not already say. */}
      {icon && <span className="lg-button-icon" aria-hidden="true">{icon}</span>}
      {children}
      {trailingIcon && <span className="lg-button-icon" data-edge="trailing" aria-hidden="true">{trailingIcon}</span>}
    </span>
  </button>;
}

export interface GlassIconButtonProps extends GlassButtonProps {
  /** Icon-only controls carry no visible text, so the accessible name is mandatory. */
  'aria-label': string;
}
export function GlassIconButton({ className, ...props }: GlassIconButtonProps) {
  return <GlassButton {...props} className={cx('lg-icon-button', className)} />;
}

'use client';
import { useEffect, useId, type LabelHTMLAttributes, type ReactNode, type RefAttributes } from 'react';
import { cx, useControllable, useMergedRef } from '../system/utils.js';

/** `htmlFor` is taken back: the label owns the checkbox it renders and wires itself to it. */
export interface GlassCheckboxProps extends Omit<LabelHTMLAttributes<HTMLLabelElement>, 'htmlFor' | 'onChange' | 'children'>,
  RefAttributes<HTMLLabelElement> {
  /** `true`, `false`, or `'mixed'` — see below; a checkbox is the only control that has three. */
  checked?: boolean | 'mixed';
  defaultChecked?: boolean;
  onCheckedChange?: (checked: boolean) => void;
  disabled?: boolean;
  name?: string;
  value?: string;
  /** The text beside the box. A checkbox almost always has one; a checklist row may not. */
  label?: ReactNode;
  /** A second line under the label, for what the setting means rather than what it is called. */
  description?: ReactNode;
  /** Required when there is no visible `label` — an empty box announces as "checkbox" alone. */
  'aria-label'?: string;
}

/**
 * A small square: empty when off, a checkmark when on, a dash when mixed.
 *
 * **Content layer, not glass.** The HIG is explicit that switches, checkboxes and radio buttons
 * belong in the window *body* and not in the window frame — so this is a flat control on the
 * page, not a floating one. A checkbox rendered as glass would be a control claiming to hover
 * over the form it is part of.
 *
 * Reach for it over `GlassSwitch` when the change needs a Save button to take effect, when the
 * settings form a hierarchy (a parent governing its children is what `'mixed'` is for), or
 * simply when there are several of them: a column of checkboxes aligns and reads as a group,
 * where a column of switches reads as a control panel.
 *
 * `'mixed'` is a **display** state, never one the reader can choose. Pressing a mixed checkbox
 * turns it on, because "partly" is not something a person can mean by clicking — it is
 * something the subordinate boxes have made true.
 */
export function GlassCheckbox({
  checked, defaultChecked = false, onCheckedChange, disabled, name, value,
  label, description, 'aria-label': ariaLabel, className, ref, ...props
}: GlassCheckboxProps) {
  const id = useId();
  const mixed = checked === 'mixed';
  const [on, setOn] = useControllable(mixed ? false : checked, defaultChecked, onCheckedChange);
  const [box, mergedRef] = useMergedRef<HTMLLabelElement>(ref);

  /**
   * `indeterminate` is a property, not an attribute — there is no `indeterminate=""` for React
   * to render, so it has to be set on the element after every render that could have changed
   * it. Without this the box would look mixed (the stylesheet can see `data-state`) and
   * announce as unchecked, which is the half of the state assistive technology gets.
   */
  useEffect(() => {
    const input = box.current?.querySelector('input');
    if (input) input.indeterminate = mixed;
  }, [mixed, box]);

  return <label {...props} ref={mergedRef} htmlFor={id}
    className={cx('lg-checkbox', className)}
    data-state={mixed ? 'mixed' : on ? 'on' : 'off'} data-disabled={disabled ? 'true' : undefined}>
    <input id={id} type="checkbox" name={name} value={value} disabled={disabled}
      checked={mixed ? false : on} aria-label={ariaLabel}
      aria-describedby={description ? `${id}-description` : undefined}
      onChange={event => setOn(mixed ? true : event.currentTarget.checked)} />
    {/* Two shapes, not one shape in two colours: "avoid relying solely on different colours to
        communicate state, because not everyone can perceive the differences." */}
    <span className="lg-checkbox-box" aria-hidden="true">
      <svg viewBox="0 0 16 16" className="lg-checkbox-mark" focusable="false">
        {mixed
          ? <path d="M4 8h8" />
          : <path d="M3.5 8.5 6.5 11.5 12.5 4.5" />}
      </svg>
    </span>
    {(label || description) && <span className="lg-checkbox-text">
      {label && <span className="lg-checkbox-label">{label}</span>}
      {description && <span className="lg-checkbox-description" id={`${id}-description`}>{description}</span>}
    </span>}
  </label>;
}

'use client';
import { useId, type InputHTMLAttributes, type RefAttributes } from 'react';
import { cx, useControllable } from '../system/utils.js';

/**
 * A quick pick.
 *
 * The name is required rather than optional, and that is the whole point of the type: a row of
 * coloured squares is meaning carried by colour alone, which is exactly what the HIG says not
 * to do. "Sky blue" is a name; `#0a84ff` is not one, but it is at least readable aloud and is
 * what the field falls back to.
 */
export interface ColorSwatch {
  value: string;
  label: string;
}

export interface ColorWellProps extends Omit<InputHTMLAttributes<HTMLInputElement>,
  'type' | 'value' | 'defaultValue' | 'onChange' | 'size'>, RefAttributes<HTMLInputElement> {
  /** What the colour is for. Required: a coloured square says nothing about what it colours. */
  'aria-label': string;
  /** `#rrggbb`. The element is a real colour input, so this is the format it speaks. */
  value?: string;
  defaultValue?: string;
  onValueChange?: (value: string) => void;
  /** Offered beside the well, for the common choices. Each one needs a name. */
  swatches?: ColorSwatch[];
  /**
   * Show the hex value next to the well. On by default, because otherwise the control's entire
   * state is a colour — unreadable to anyone who cannot distinguish it, and unquotable by
   * anyone trying to describe it to someone else.
   */
  showValue?: boolean;
  disabled?: boolean;
}

/**
 * Pick a colour.
 *
 * A real `<input type="color">` under a glass-free shell, so the picker that opens is the
 * operating system's own — with its eyedropper, its recent colours and its accessibility —
 * rather than a re-implementation that has none of them. The shell exists to give it the
 * library's shape, a 44×44 hit region and a focus ring; it does not try to replace the picker.
 *
 * Content layer. A colour well is a form control sitting in what you are reading, not
 * something floating over it.
 */
export function ColorWell({
  'aria-label': label, value, defaultValue = '#0a84ff', onValueChange,
  swatches, showValue = true, disabled, className, ref, ...props
}: ColorWellProps) {
  const [current, setCurrent] = useControllable(value, defaultValue, onValueChange);
  const valueId = useId();
  const normalised = current.toLowerCase();
  /* The hex is part of the control's description, not a replacement for whatever the caller
     already attached — a field with a hint would otherwise lose it by turning the value on. */
  const describedBy = [showValue ? valueId : null, props['aria-describedby']].filter(Boolean).join(' ') || undefined;

  return <div className={cx('lg-color-well', className)} data-disabled={disabled || undefined}>
    <span className="lg-color-well-box">
      {/*
        The input is the control, laid over its own swatch at full size rather than hidden
        behind a button: hiding it and clicking it from script is what loses the keyboard, the
        focus ring and the form. The visible swatch is `background-color` on the parent, which
        is why the input itself is transparent.
      */}
      <input {...props} ref={ref} type="color" className="lg-color-well-input"
        aria-label={label} aria-describedby={describedBy}
        disabled={disabled} value={current}
        onChange={event => setCurrent(event.target.value)} />
      <span className="lg-color-well-swatch" aria-hidden="true" style={{ background: current }} />
    </span>
    {showValue && <span className="lg-color-well-value" id={valueId}>{normalised}</span>}
    {swatches && swatches.length > 0 && <span className="lg-color-well-swatches">
      {swatches.map(swatch => {
        const chosen = swatch.value.toLowerCase() === normalised;
        return <button key={swatch.value} type="button" className="lg-color-well-quick"
          /* Pressed, not checked: these are shortcuts to a value the well already holds, not a
             second, competing control for the same choice. */
          aria-pressed={chosen} aria-label={swatch.label} disabled={disabled}
          onClick={() => setCurrent(swatch.value)}>
          <span aria-hidden="true" style={{ background: swatch.value }} />
        </button>;
      })}
    </span>}
  </div>;
}

'use client';
import { type HTMLAttributes, type RefAttributes } from 'react';
import { GlassSegmentedControl } from './segmented.js';
import { GlassMenuButton } from '../overlays/menu-button.js';
import { useSizeClass } from '../system/size-class.js';
import { cx } from '../system/utils.js';

/**
 * One value on offer. Values, not commands — a picker reports a choice, it does not run one.
 *
 * No icon slot, deliberately: the same picker renders as a segmented control at one width and
 * as a menu at another, and a segmented control that mixes icons with text breaks the HIG's
 * rule for its own group. An option that needs a glyph to be understood needs a better label.
 */
export interface PickerOption {
  value: string;
  label: string;
  disabled?: boolean;
}

/**
 * Above this many options a segmented control stops being readable: the segments get narrower
 * than their labels, and the HIG's own limit for a segmented control is 2–5.
 */
const INLINE_MAX = 4;

/**
 * Below this many options the control stays inline whatever the width.
 *
 * A menu of two costs a press to reveal less than the two segments it replaced — the same
 * argument `GlassMenuButton` makes in development mode, and it was this component that kept
 * tripping it: eight documentation pages printed that warning on a phone, because a two-option
 * picker in a compact window collapsed into exactly the menu the rule is about. Two segments
 * fit in any layout that can hold a pop-up button naming the longer of the two labels.
 */
const ALWAYS_INLINE = 2;

export interface PickerProps extends Omit<HTMLAttributes<HTMLDivElement>, 'defaultValue' | 'onChange'>,
  RefAttributes<HTMLDivElement> {
  /** What is being chosen. Shown beside the control, and is also the control's spoken name. */
  label: string;
  /** Hide the words but keep the name. For a picker whose surroundings already say what it is. */
  labelHidden?: boolean;
  options: PickerOption[];
  value?: string;
  defaultValue?: string;
  onValueChange?: (value: string) => void;
  /**
   * How it is presented. `automatic` — the default and the one to use — decides from the option
   * count and the size class, which is the rule the HIG states for layout generally: decide by
   * how much room there is, never by what device it is.
   */
  presentation?: 'automatic' | 'inline' | 'menu';
  disabled?: boolean;
  /** Form field name. Only the inline form participates in a form; the menu form has no input. */
  name?: string;
}

/**
 * Choose one value from a small set, in whichever form fits.
 *
 * This is the part that is not a pop-up button with a label stuck on it. A picker's job is the
 * *choice*; its shape is a consequence of how many options there are and how much room the
 * layout has, and hard-coding either at every call site is how an interface ends up with a
 * five-segment control squeezed onto a phone.
 *
 * - Two options: an inline segmented control at any width.
 * - Up to four options in a regular-width layout: the same, because they are all visible at
 *   once and switching costs one press.
 * - More options, or a compact layout: a pop-up button, whose label shows the current choice.
 *
 * Both forms are single-selection and report the same thing, so the reader's mental model does
 * not change with the window. Layer follows the host: the inline form is a glass segmented
 * control, the menu form defaults to the flat grey button that belongs in a form row.
 */
export function Picker({
  label, labelHidden, options, value, defaultValue, onValueChange,
  presentation = 'automatic', disabled, name, className, ref, ...props
}: PickerProps) {
  const sizeClass = useSizeClass();
  const inline = presentation === 'inline'
    || (presentation === 'automatic'
      && (options.length <= ALWAYS_INLINE || (options.length <= INLINE_MAX && sizeClass === 'regular')));

  return <div {...props} ref={ref} className={cx('lg-picker', className)}
    data-presentation={inline ? 'inline' : 'menu'}>
    {/*
      The words are decoration here, and that is deliberate. The control carries `label` as its
      own accessible name, so announcing the span as well would read the same words twice; and
      because the name is character-for-character the visible text, Voice Control still hits the
      control when someone says it.
    */}
    {!labelHidden && <span className="lg-picker-label" aria-hidden="true">{label}</span>}
    {inline
      ? <GlassSegmentedControl aria-label={label} items={options} disabled={disabled} name={name}
        value={value} defaultValue={defaultValue} onValueChange={onValueChange} />
      : <GlassMenuButton kind="popUp" aria-label={label} options={options} variant="gray"
        disabled={disabled} value={value} defaultValue={defaultValue} onValueChange={onValueChange} />}
  </div>;
}

'use client';
import type { CSSProperties, HTMLAttributes, RefAttributes } from 'react';
import { cx } from '../system/utils.js';
import { clamp } from '../../core/index.js';

export interface GlassProgressProps extends Omit<HTMLAttributes<HTMLDivElement>, 'children'>, RefAttributes<HTMLDivElement> {
  /** Omit for an indeterminate indicator. Provide it as soon as the duration is known. */
  value?: number;
  total?: number;
  'aria-label': string;
  /** `bar` for a known task, `circular` for a short indefinite wait. */
  variant?: 'bar' | 'circular';
}

/**
 * Determinate whenever the duration is known — an indeterminate spinner tells the user
 * nothing except that the app is still alive. Never blocks the interface: show content as
 * soon as any of it exists, and prefer a skeleton that matches the final layout over a
 * spinner in the middle of an empty page.
 */
export function GlassProgress({ value, total = 100, 'aria-label': label, variant = 'bar', className, style, ref, ...props }: GlassProgressProps) {
  if (!Number.isFinite(total) || total <= 0) throw new RangeError('GlassProgress requires total > 0');
  const determinate = Number.isFinite(value);
  const fraction = determinate ? clamp(value! / total, 0, 1) : 0;
  const aria = determinate
    ? { 'aria-valuenow': Math.round(fraction * 100), 'aria-valuemin': 0, 'aria-valuemax': 100 }
    : {};
  return <div {...props} ref={ref} role="progressbar" aria-label={label} {...aria}
    className={cx('lg-progress', className)} data-variant={variant} data-determinate={determinate ? 'true' : 'false'}
    style={{ '--lg-progress': fraction, ...style } as CSSProperties}>
    {variant === 'bar'
      ? <span className="lg-progress-track"><span className="lg-progress-fill" /></span>
      : <span className="lg-progress-ring" />}
  </div>;
}

'use client';
import { useId, type HTMLAttributes, type ReactNode, type RefAttributes } from 'react';
import { inDevelopment } from '../system/warn.js';
import { cx, useControllable } from '../system/utils.js';

export interface RadioOption {
  value: string;
  label: ReactNode;
  /** A second line saying what the choice means. Read out with the option, not after it. */
  description?: ReactNode;
  disabled?: boolean;
}

export interface RadioGroupProps extends Omit<HTMLAttributes<HTMLFieldSetElement>, 'onChange' | 'defaultValue'>,
  RefAttributes<HTMLFieldSetElement> {
  /**
   * What the set of options is about. Visible by default, because a group of radio buttons
   * without one is a list of answers to an unasked question.
   */
  label: ReactNode;
  labelHidden?: boolean;
  options: RadioOption[];
  value?: string;
  defaultValue?: string;
  onValueChange?: (value: string) => void;
  /** `vertical` — the default — is the form layout. `horizontal` needs short labels. */
  orientation?: 'vertical' | 'horizontal';
  /** Shared `name` for the inputs. Generated when it is not given. */
  name?: string;
}

/** Past this, the HIG says to use a pop-up button instead. */
const CROWDED = 5;

/**
 * Two to five mutually exclusive choices, each with its own label.
 *
 * **Content layer**, like every other control that belongs in the window body rather than the
 * window frame. The circle fills when chosen; nothing here is glass.
 *
 * It is built on real `<input type="radio">` elements sharing a `name`, which is not an
 * implementation detail but the entire keyboard model: the browser makes the group **one** tab
 * stop, moves the selection with the arrow keys, wraps at the ends, and skips the disabled
 * options — the roving-tabindex behaviour a hand-written version has to reimplement and
 * usually gets subtly wrong. Nothing here overrides any of it.
 *
 * When to use something else, from the HIG's own list: more than about five options is a
 * `Picker`; a single on/off is a `GlassCheckbox`, because the presence of a checkmark reads
 * faster than one of two filled circles; several choices at once is a column of checkboxes.
 */
export function RadioGroup({
  label, labelHidden = false, options, value, defaultValue, onValueChange,
  orientation = 'vertical', name, className, ref, ...props
}: RadioGroupProps) {
  const generated = useId();
  const group = name ?? generated;
  const first = options.find(option => !option.disabled)?.value ?? '';
  const [selected, setSelected] = useControllable(value, defaultValue ?? first, onValueChange);

  if (inDevelopment() && options.length > CROWDED) {
    console.warn(`[liquid-glass-ui] RadioGroup has ${options.length} options. `
      + 'Past about five, a long column of radio buttons takes a lot of room and is a lot to '
      + 'read; the HIG points at a pop-up button — this library\'s Picker — instead.');
  }

  return <fieldset {...props} ref={ref} className={cx('lg-radio-group', className)}
    data-orientation={orientation}>
    {/* A real `<legend>`: it is what names the group to a screen reader, and `aria-label` on a
        fieldset is not announced consistently. Hidden visually when the surrounding form
        already asks the question. */}
    <legend className={cx('lg-radio-legend', labelHidden && 'lg-visually-hidden')}>{label}</legend>
    {options.map(option => {
      const id = `${group}-${option.value}`;
      return <label key={option.value} htmlFor={id} className="lg-radio"
        data-state={selected === option.value ? 'on' : 'off'}
        data-disabled={option.disabled ? 'true' : undefined}>
        <input id={id} type="radio" name={group} value={option.value}
          checked={selected === option.value} disabled={option.disabled}
          aria-describedby={option.description ? `${id}-description` : undefined}
          onChange={() => setSelected(option.value)} />
        <span className="lg-radio-dot" aria-hidden="true" />
        <span className="lg-radio-text">
          <span className="lg-radio-label">{option.label}</span>
          {option.description && <span className="lg-radio-description" id={`${id}-description`}>{option.description}</span>}
        </span>
      </label>;
    })}
  </fieldset>;
}

'use client';
import { useId, useRef, type HTMLAttributes, type ReactNode, type RefAttributes, type RefObject } from 'react';
import { GlassSurface } from '../system/surface.js';
import { type GlassSurfaceOptions } from '../system/material.js';
import { splitSurface } from '../system/props.js';
import { cx, useControllable, useMeasureEffect } from '../system/utils.js';
import { usePull, elementAt } from '../system/pull.js';
import { useFusion } from '../system/fusion.js';
import { useGlassPolicy } from '../system/provider.js';

export interface GlassChoice { value: string; label: ReactNode; disabled?: boolean }

/**
 * Centre of the slot the lens belongs to, i.e. where it would sit with no pull applied: its
 * measured centre with the live offset taken back off. Used as the reference the drag is
 * measured from, so a selection change mid-drag moves the slot while the lens stays put.
 *
 * This is only exact because the lens composes its own transform with the scale applied *last*
 * (see `--lg-slot-*` in the stylesheet). The individual `scale` property applies before
 * `transform`, so it would multiply the slot offset, and the resulting error would feed back
 * into the next frame's offset — a control that shakes as long as you hold it.
 */
export function lensOrigin(lens: HTMLElement | null) {
  if (!lens) return null;
  const box = lens.getBoundingClientRect();
  const shiftX = parseFloat(lens.style.getPropertyValue('--lg-shift-x')) || 0;
  const shiftY = parseFloat(lens.style.getPropertyValue('--lg-shift-y')) || 0;
  return { x: box.left + box.width / 2 - shiftX, y: box.top + box.height / 2 - shiftY };
}

/**
 * Measures the selected child and positions a single shared lens that glides between choices.
 *
 * Both axes are tracked, not just the horizontal one: the same lens has to follow a row of
 * segments and a vertical column of sidebar rows, and a column's items all share `offsetLeft`.
 *
 * The geometry is written straight to the lens element rather than returned as a style object.
 * The very first placement has to land with the transition switched off — otherwise every
 * control on the page springs open from nothing on load — and that ordering (suppress, place,
 * make the browser resolve it, restore) needs the DOM write to happen when we say it does,
 * which React state does not promise.
 */
export function useSelectionLens<T extends HTMLElement>(root: RefObject<T | null>, lens: RefObject<HTMLElement | null>, selector: string, deps: unknown[]) {
  const placed = useRef(false);
  const slot = useRef({ x: 0, y: 0 });
  // Before paint, not after: a slot written a frame late is a frame of the lens in the wrong place.
  useMeasureEffect(() => {
    const node = root.current, pill = lens.current; if (!node || !pill) return;
    const update = () => {
      const target = node.querySelector<HTMLElement>(selector);
      const first = !placed.current;
      if (first) pill.style.transition = 'none';
      if (target && target.offsetWidth) {
        const x = target.offsetLeft, y = target.offsetTop;
        /**
         * Mid-drag the slot moves out from under a lens the finger is still holding, and the
         * offset that is about to be added to it was measured against the slot it just left.
         * Adding the two would throw the lens a whole segment clear of the track until the next
         * frame corrects it. Absorb the move instead — same pixels on screen, and the offset once
         * again means what it says.
         */
        if (!first && pill.getAttribute('data-pulling') === 'true') {
          const shiftX = parseFloat(pill.style.getPropertyValue('--lg-shift-x')) || 0;
          const shiftY = parseFloat(pill.style.getPropertyValue('--lg-shift-y')) || 0;
          pill.style.setProperty('--lg-shift-x', `${(shiftX - (x - slot.current.x)).toFixed(2)}px`);
          pill.style.setProperty('--lg-shift-y', `${(shiftY - (y - slot.current.y)).toFixed(2)}px`);
        }
        slot.current = { x, y };
        pill.style.width = `${target.offsetWidth}px`;
        pill.style.height = `${target.offsetHeight}px`;
        // Custom properties, not `transform`: the stylesheet composes the slot, the drag offset
        // and the deformation into one chain, in the order that keeps them independent.
        pill.style.setProperty('--lg-slot-x', `${x}px`);
        pill.style.setProperty('--lg-slot-y', `${y}px`);
        // `--lg-lens-shown`, not `opacity`: the fusion layer also has a say in whether the lens
        // is the thing painting the pill, and an inline opacity would overrule it.
        pill.style.setProperty('--lg-lens-shown', '1');
        placed.current = true;
      } else {
        pill.style.setProperty('--lg-lens-shown', '0');
      }
      // Forces the placement to resolve while the transition is still off, so nothing animates.
      if (first) { void pill.offsetWidth; pill.style.transition = ''; }
    };
    update(); const observer = new ResizeObserver(update); observer.observe(node);
    if (typeof document !== 'undefined' && 'fonts' in document) document.fonts.ready.then(update, () => {});
    return () => observer.disconnect();
    // eslint-disable-next-line react-hooks/exhaustive-deps
  }, [root, lens, selector, ...deps]);
}

/**
 * How far the lens may be carried, measured from its resting centre, before it starts to resist:
 * exactly as far as the track lets it go without leaving either end.
 */
export function trackSpan(track: HTMLElement | null, lens: HTMLElement | null, axis: 'x' | 'y' = 'x') {
  const origin = lensOrigin(lens);
  if (!track || !lens || !origin) return null;
  const box = track.getBoundingClientRect();
  // A control that is not laid out has no span to give; rubber-band from the origin instead.
  if (!box.width || !box.height) return null;
  const span = (start: number, end: number): [number, number] => start <= end ? [start, end] : [0, 0];
  if (axis === 'y') {
    const half = lens.offsetHeight / 2;
    return { y: span(box.top + half - origin.y, box.bottom - half - origin.y) };
  }
  const half = lens.offsetWidth / 2;
  return { x: span(box.left + half - origin.x, box.right - half - origin.x) };
}

/** `defaultValue` and `onChange` here would mean the radio inputs the control renders, not the control. */
export interface GlassSegmentedControlProps extends Omit<HTMLAttributes<HTMLDivElement>, 'children' | 'defaultValue' | 'onChange'>, RefAttributes<HTMLDivElement>, GlassSurfaceOptions {
  items: GlassChoice[]; value?: string; defaultValue?: string; onValueChange?: (value: string) => void;
  'aria-label': string; name?: string; disabled?: boolean;
}

/**
 * Two to five equal-width segments, text **or** icons but never both mixed. Native radio
 * inputs underneath provide form participation and arrow-key selection.
 *
 * It is a scrubber, not a row of buttons: press the selected segment and slide, and the lens
 * tracks the pointer 1:1, stretches with the drag and updates the selection *live* as it
 * crosses each segment, settling on a spring. This is the interaction most often missing
 * from imitations of the system control.
 */
export function GlassSegmentedControl({ items, value, defaultValue, onValueChange, name, disabled, className, 'aria-label': label, ref, ...rest }: GlassSegmentedControlProps) {
  const [surface, props] = splitSurface(rest);
  const id = useId();
  const [selected, setSelected] = useControllable(value, defaultValue ?? items.find(x => !x.disabled)?.value ?? '', onValueChange);
  const root = useRef<HTMLDivElement>(null);
  const policy = useGlassPolicy();
  const lensRef = useRef<HTMLSpanElement>(null);
  useSelectionLens(root, lensRef, '.lg-segment:has(input:checked)', [selected, items]);
  const fusion = useFusion(root, { itemSelector: '.lg-segment:not([data-disabled="true"])', lensSelector: '.lg-selection-lens' });
  usePull(root, {
    axis: 'x', limit: 18, stretch: .8,
    targets: () => lensRef.current ? [lensRef.current] : [],
    origin: () => lensOrigin(lensRef.current),
    // The lens is carried across the whole track by the finger and only resists at the ends.
    range: () => trackSpan(root.current, lensRef.current),
    disabled: event => !!disabled || !!(event.target as HTMLElement).closest('[data-disabled="true"]'),
    /**
     * The capsule is what you drag, so the press has to land on it. Pressing another segment is
     * a click; the lens stays where the selection is and slides over once the click resolves.
     * Letting any press carry it meant the capsule jumped under the finger before the click had
     * even happened, which is the single most visible way this control can look broken.
     */
    grab: event => !!(event.target as HTMLElement).closest('.lg-segment')?.querySelector('input:checked'),
    /**
     * Only a move picks. Selecting on the press as well would mean a plain tap on another segment
     * changes the selection before the reader has let go, so there is no way to slide off and
     * change your mind. Left to the label's own click, which lands after the gesture has ended,
     * the lens slides across the way the system control does.
     */
    onMove: event => pick(event),
  }, !policy.reduceMotion && !disabled);
  function pick(event: PointerEvent) {
    const hit = elementAt(event, '.lg-segment'); const input = hit?.querySelector<HTMLInputElement>('input');
    if (input && !input.disabled && input.value !== selected && root.current?.contains(input)) setSelected(input.value);
  }
  return <GlassSurface {...props} {...surface} ref={ref} radius={surface.radius ?? 'pill'} className={cx('lg-segmented', className)}>
    <div className="lg-segmented-track" ref={root} role="radiogroup" aria-label={label}>
      {fusion}<span aria-hidden="true" className="lg-selection-lens" ref={lensRef} />
      {items.map(item => <label key={item.value} className="lg-segment" data-disabled={disabled || item.disabled ? 'true' : 'false'}>
        <input type="radio" name={name ?? `segment-${id}`} value={item.value} checked={selected === item.value} disabled={disabled || item.disabled} onChange={() => setSelected(item.value)} />
        <span>{item.label}</span>
      </label>)}
    </div>
  </GlassSurface>;
}

'use client';
import { useEffect, type CSSProperties, type HTMLAttributes, type ReactNode, type RefAttributes } from 'react';
import { usePull } from '../system/pull.js';
import { useGlassSurface, type GlassSurfaceOptions } from '../system/material.js';
import { splitSurface } from '../system/props.js';
import { useGlassPolicy } from '../system/provider.js';
import { cx, useControllable, useMergedRef } from '../system/utils.js';
import { clamp } from '../../core/index.js';
import { inDevelopment, warnOnce } from '../system/warn.js';

/** `defaultValue` and `onChange` belong to the `<input type="range">` this wraps, not to the wrapper. */
export interface GlassSliderProps extends Omit<HTMLAttributes<HTMLDivElement>, 'children' | 'defaultValue' | 'onChange'>, RefAttributes<HTMLDivElement>, GlassSurfaceOptions {
  value?: number; defaultValue?: number; onValueChange?: (value: number) => void;
  min?: number; max?: number; step?: number; disabled?: boolean; name?: string;
  'aria-label': string;
  /** Spoken value when the bare number is ambiguous — "62 percent", "4 of 10". */
  formatValue?: (value: number) => string;
  /** Glyphs at the ends of the track, e.g. a small and a large speaker. */
  minLabel?: ReactNode; maxLabel?: ReactNode;
  /**
   * Tick marks along the track. `true` places one at every `step`; an array places them at
   * the values given. Marks say the scale is discrete, so only use them when it is — a
   * hundred ticks on a volume slider is a hatched line, not information.
   *
   * They are decoration for the eye: the value a screen reader hears comes from the input
   * and from `formatValue`, and the marks add nothing to it.
   */
  marks?: boolean | number[];
}

/**
 * A real `<input type="range">` under a drawn track and knob. Rebuilding the input would
 * cost keyboard support, form participation and `aria-valuetext` for nothing.
 *
 * The knob is quiet at rest and **lifts into glass only while it is being manipulated** —
 * a transient control in the content layer, per the Liquid Glass rules. A knob that is
 * permanently glass is glass in the content layer.
 */
export function GlassSlider({ value, defaultValue = 50, onValueChange, min = 0, max = 100, step = 1, disabled, name, 'aria-label': label, formatValue, minLabel, maxLabel, marks, className, style, ref, ...rest }: GlassSliderProps) {
  const [surface, props] = splitSurface(rest);
  if (![min, max, step].every(Number.isFinite) || min >= max || step <= 0) throw new RangeError('GlassSlider requires finite min < max and step > 0');
  const [current, setCurrent] = useControllable(value, defaultValue, onValueChange);
  const safe = clamp(Number.isFinite(current) ? current : min, min, max), progress = (safe - min) / (max - min);
  const [root, mergedRef] = useMergedRef<HTMLDivElement>(ref);
  /**
   * `true` means one per step, which is only sane while the steps are countable. Past that
   * the ticks merge into a hatched line and stop saying anything, so it is capped and the
   * caller is told to pass the values they actually mean.
   */
  const tickValues = !marks ? null : Array.isArray(marks)
    ? marks.filter(tick => tick >= min && tick <= max)
    : (max - min) / step <= 20
      ? Array.from({ length: Math.floor((max - min) / step) + 1 }, (_, index) => min + index * step)
      : null;
  useEffect(() => {
    if (!inDevelopment() || marks !== true || tickValues) return;
    const node = root.current; if (!node) return;
    warnOnce(node, 'slider-marks-dense',
      `marks={true} on a range of ${(max - min) / step} steps would draw them as a hatched line. Pass the values you mean — marks={[0, 25, 50, 75, 100]} — or leave them off.`);
  }, [root, marks, tickValues, min, max, step]);
  const policy = useGlassPolicy();
  // The knob keeps its glass machinery mounted so the displacement texture is not rebuilt on
  // every press; CSS decides whether that machinery is visible.
  const knob = useGlassSurface<HTMLSpanElement>({ ...surface, radius: 'pill' });
  usePull(root, {
    limit: 10, stretch: 1,
    targets: () => knob.root.current ? [knob.root.current] : [],
    // Horizontal motion is the value itself; only vertical pull stretches the knob, horizontal shows the lag.
    origin: () => { const box = knob.root.current?.getBoundingClientRect(); return box ? { x: box.left + box.width / 2, y: box.top + box.height / 2 } : null; },
    disabled: () => !!disabled,
  }, !policy.reduceMotion);
  return <div {...props} ref={mergedRef} className={cx('lg-slider', className)} data-disabled={disabled ? 'true' : 'false'} style={{ '--lg-progress': progress, ...style } as CSSProperties}>
    {minLabel && <span className="lg-slider-edge" aria-hidden="true">{minLabel}</span>}
    <span className="lg-slider-rail">
      <span className="lg-slider-track" aria-hidden="true"><span className="lg-slider-fill" /></span>
      {tickValues && <span className="lg-slider-marks" aria-hidden="true">
        {tickValues.map(tick => <span key={tick} className="lg-slider-mark"
          data-passed={tick <= safe ? 'true' : undefined}
          style={{ '--lg-mark': (tick - min) / (max - min) } as CSSProperties} />)}
      </span>}
      <span ref={knob.ref} {...knob.attributes} className="lg-root lg-slider-lens" style={knob.style} aria-hidden="true">{knob.decoration}</span>
      <input type="range" aria-label={label} aria-valuetext={formatValue?.(safe)} min={min} max={max} step={step} value={safe} disabled={disabled} name={name}
        onChange={event => setCurrent(Number(event.currentTarget.value))} />
    </span>
    {maxLabel && <span className="lg-slider-edge" aria-hidden="true">{maxLabel}</span>}
  </div>;
}

'use client';
import { useCallback, useEffect, useRef, type HTMLAttributes, type PointerEvent as ReactPointerEvent, type RefAttributes } from 'react';
import { cx, useControllable } from '../system/utils.js';
import { LibraryIcon } from '../system/icon.js';
import { clamp } from '../../core/index.js';
import { useGlassStrings } from '../system/strings.js';

export interface GlassStepperProps extends Omit<HTMLAttributes<HTMLDivElement>, 'children' | 'defaultValue' | 'onChange'>, RefAttributes<HTMLDivElement> {
  value?: number; defaultValue?: number; onValueChange?: (value: number) => void;
  min?: number; max?: number; step?: number; disabled?: boolean;
  'aria-label': string;
  /** Spoken and displayed form of the value. The number alone is rarely enough. */
  formatValue?: (value: number) => string;
  /** Render the value inside the control. Off when the value already appears next to it in a row. */
  showValue?: boolean;
  decrementLabel?: string;
  incrementLabel?: string;
  /**
   * How much Shift multiplies a press by. The HIG's steppers page asks for a larger step over
   * a wide range; `1` turns it off for a stepper whose whole range is a handful of values.
   */
  shiftMultiplier?: number;
}

/** Hold for this long before it starts repeating, then one step every `REPEAT`. */
const HOLD = 400, REPEAT = 90;

/**
 * Two segments sharing one surface, for small integer ranges only — past a handful of taps
 * a slider or a field is the honest control. The value is always visible, either inside the
 * stepper or immediately beside it.
 */
export function GlassStepper({
  value, defaultValue = 0, onValueChange, min = -Infinity, max = Infinity, step = 1, disabled,
  'aria-label': label, formatValue, showValue = true, decrementLabel, incrementLabel,
  shiftMultiplier = 10, className, ref, ...props
}: GlassStepperProps) {
  const strings = useGlassStrings();
  if (!Number.isFinite(step) || step <= 0) throw new RangeError('GlassStepper requires step > 0');
  if (min >= max) throw new RangeError('GlassStepper requires min < max');
  const [current, setCurrent] = useControllable(value, defaultValue, onValueChange);
  const safe = clamp(Number.isFinite(current) ? current : 0, min, max);
  const shown = formatValue ? formatValue(safe) : String(safe);

  /**
   * The repeat reads the latest value from a ref rather than from the render it started in.
   * A timer closes over the value it was created with, so a chain of them all compute
   * `safe + step` from the same starting number and the control moves exactly one step no
   * matter how long it is held.
   */
  const latest = useRef(safe); latest.current = safe;
  const bounds = useRef({ min, max, step }); bounds.current = { min, max, step };
  const timers = useRef<ReturnType<typeof setTimeout>[]>([]);
  const stop = useCallback(() => { for (const timer of timers.current) clearTimeout(timer); timers.current = []; }, []);
  useEffect(() => stop, [stop]);

  const nudge = useCallback((direction: 1 | -1, multiplier = 1) => {
    const { min: low, max: high, step: size } = bounds.current;
    const next = clamp(latest.current + direction * size * multiplier, low, high);
    if (next === latest.current) { stop(); return false; }
    latest.current = next;
    setCurrent(next);
    return true;
  }, [setCurrent, stop]);

  /**
   * Press and hold to keep going, which is what the system control does and the only reason a
   * stepper is usable over a range wider than a few values. It stops on release, on cancel,
   * and on its own once the value has reached the end — a repeat that keeps firing into a
   * clamp is a timer nobody can see still running.
   */
  const hold = (event: ReactPointerEvent<HTMLButtonElement>, direction: 1 | -1) => {
    if (event.button !== 0 || !event.isPrimary || disabled) return;
    const multiplier = event.shiftKey ? shiftMultiplier : 1;
    // The first step is the click's; this only schedules what comes after it.
    const tick = () => { if (nudge(direction, multiplier)) timers.current.push(setTimeout(tick, REPEAT)); };
    timers.current.push(setTimeout(tick, HOLD));
    const release = () => { stop(); window.removeEventListener('pointerup', release); window.removeEventListener('pointercancel', release); };
    window.addEventListener('pointerup', release); window.addEventListener('pointercancel', release);
  };

  const button = (direction: 1 | -1) => ({
    type: 'button' as const,
    className: 'lg-stepper-button',
    'aria-label': direction === -1 ? decrementLabel ?? strings.decrease : incrementLabel ?? strings.increase,
    disabled: disabled || (direction === -1 ? safe <= min : safe >= max),
    onClick: (event: { shiftKey: boolean }) => nudge(direction, event.shiftKey ? shiftMultiplier : 1),
    // Reduce Motion is about movement, not about repetition, so the hold stays either way.
    onPointerDown: (event: ReactPointerEvent<HTMLButtonElement>) => hold(event, direction),
  });

  return <div {...props} ref={ref} className={cx('lg-stepper', className)} role="group" aria-label={label} data-disabled={disabled ? 'true' : undefined}>
    <button {...button(-1)}><LibraryIcon name="minus" size={18} /></button>
    {showValue && <output className="lg-stepper-value" aria-live="off">{shown}</output>}
    <button {...button(1)}><LibraryIcon name="plus" size={18} /></button>
  </div>;
}

'use client';
import { useId, useRef, type LabelHTMLAttributes, type RefAttributes } from 'react';
import { usePull } from '../system/pull.js';
import { useGlassSurface, type GlassSurfaceOptions } from '../system/material.js';
import { splitSurface } from '../system/props.js';
import { cx, useControllable, useMergedRef } from '../system/utils.js';

/** `htmlFor` is taken back: the label owns the checkbox it renders and wires itself to it. */
export interface GlassSwitchProps extends Omit<LabelHTMLAttributes<HTMLLabelElement>, 'htmlFor' | 'children' | 'onChange'>, RefAttributes<HTMLLabelElement>, GlassSurfaceOptions {
  checked?: boolean; defaultChecked?: boolean; onCheckedChange?: (checked: boolean) => void;
  disabled?: boolean; name?: string;
  /** Describe the **on** state — "Wi-Fi", not "Enable Wi-Fi" and never "Enable/Disable". */
  'aria-label': string;
  label?: string;
}

/**
 * A capsule toggle, green when on, over a real `<input type="checkbox" role="switch">`.
 *
 * It is a drag target as well as a tap target: throw the knob and it lands on the nearer
 * side, tracking the pointer 1:1 and stretching along the drag before it springs. A
 * click-only switch is one of the clearest tells that an interface is not Apple's.
 */
export function GlassSwitch({ checked, defaultChecked = false, onCheckedChange, disabled, name, 'aria-label': label, label: visibleLabel, className, ref, ...rest }: GlassSwitchProps) {
  const [surface, props] = splitSurface(rest);
  const id = useId();
  const [active, setActive] = useControllable(checked, defaultChecked, onCheckedChange);
  const glass = useGlassSurface<HTMLSpanElement>({ ...surface, radius: 'pill' });
  const thumb = useRef<HTMLSpanElement>(null); const dragged = useRef(false);
  // The label is both the drag surface and what the caller's ref should point at.
  const [labelRef, mergedRef] = useMergedRef<HTMLLabelElement>(ref);
  usePull(labelRef, {
    axis: 'x', limit: 10, stretch: 1.2,
    targets: () => [thumb.current!, glass.root.current!].filter(Boolean) as HTMLElement[],
    /**
     * The thumb crosses the track under the finger and only resists past the ends. `--lg-travel`
     * already holds whichever side it started on, so the free span is the remaining travel.
     */
    range: () => {
      const track = glass.root.current, knob = thumb.current;
      if (!track || !knob) return null;
      const travel = track.clientWidth - knob.offsetWidth - 6;
      if (travel <= 0) return null;
      return { x: [(active ? -travel : 0), (active ? 0 : travel)] as [number, number] };
    },
    disabled: () => !!disabled,
    onRelease: ({ dx, cancelled }) => {
      if (cancelled || Math.abs(dx) < 6) { dragged.current = false; return; }
      // A deliberate drag decides by direction and suppresses the label's synthetic click.
      dragged.current = true; const next = dx > 0; if (next !== active) setActive(next);
    },
  }, !glass.policy.reduceMotion);
  return <label {...props} ref={mergedRef} className={cx('lg-switch', className)} data-disabled={disabled ? 'true' : 'false'} htmlFor={id}
    onClickCapture={event => { if (dragged.current) { dragged.current = false; event.preventDefault(); event.stopPropagation(); } }}>
    <input id={id} type="checkbox" role="switch" aria-label={label} name={name} checked={active} disabled={disabled} onChange={event => setActive(event.currentTarget.checked)} />
    <span ref={glass.ref} {...glass.attributes} className="lg-root lg-switch-track" data-checked={active ? 'true' : 'false'} style={glass.style} aria-hidden="true">
      {glass.decoration}<span className="lg-switch-thumb" ref={thumb} />
    </span>{visibleLabel && <span className="lg-switch-label">{visibleLabel}</span>}
  </label>;
}

'use client';
import { useEffect, useId, useRef, useState, type InputHTMLAttributes, type ReactNode, type RefAttributes } from 'react';
import { cx, useControllable, useMergedRef } from '../system/utils.js';
import { LibraryIcon } from '../system/icon.js';
import { useGlassSurface, type GlassSurfaceOptions } from '../system/material.js';
import { useGlassStrings } from '../system/strings.js';

/** The ref, like every other attribute here, lands on the `<input>` — the thing worth holding. */
export interface SearchFieldProps extends Omit<InputHTMLAttributes<HTMLInputElement>, 'value' | 'defaultValue' | 'onChange' | 'size' | 'type'>, RefAttributes<HTMLInputElement>, GlassSurfaceOptions {
  value?: string;
  defaultValue?: string;
  onValueChange?: (value: string) => void;
  onSubmitQuery?: (value: string) => void;
  'aria-label': string;
  clearLabel?: string;
  /**
   * Suggestions for what is typed so far. Pass them and the field becomes a combobox: Down
   * and Up move through the list, Enter takes the highlighted one, Escape closes it.
   *
   * Filtering is the caller's, always. Only the application knows what "matching" means for
   * its data — prefix, fuzzy, ranked, remote — and a library that guessed would be wrong
   * for most of them and impossible to override.
   */
  suggestions?: SearchSuggestion[];
  /** A suggestion was taken. The field's value follows it; this is the "go" signal. */
  onSuggestionSelect?: (suggestion: SearchSuggestion) => void;
}

export interface SearchSuggestion {
  /** What goes into the field when this is taken, and what identifies it. */
  value: string;
  /** What is drawn, if it is more than the value: a match with its category, say. */
  label?: ReactNode;
  icon?: ReactNode;
}

/**
 * A capsule search field on its own glass surface — top-trailing on wide layouts, and on a
 * phone either the trailing search tab or a field that rises with the keyboard.
 *
 * `type="search"` gives the right on-screen keyboard and the platform's own clear gesture;
 * the drawn clear button is the pointer affordance on top of that. The focus ring lands on
 * the glass container via `:focus-within`, because the input's own outline is suppressed and
 * something has to replace it.
 */
export function SearchField(
  { value, defaultValue = '', onValueChange, onSubmitQuery, 'aria-label': label, clearLabel,
    suggestions, onSuggestionSelect,
    className, material, backdropTone, density, renderer, radius, refraction, size, chroma, id: providedId, ref, ...props }: SearchFieldProps,
) {
  // A caller's id has to win: it is how a `<label for>` or an `aria-controls` reaches the input.
  const strings = useGlassStrings();
  const generated = useId(); const id = providedId ?? `${generated}-search`;
  const [query, setQuery] = useControllable(value, defaultValue, onValueChange);
  const [input, mergedRef] = useMergedRef<HTMLInputElement>(ref);
  const glass = useGlassSurface<HTMLDivElement>({ material, backdropTone, density, renderer, radius: radius ?? 'pill', refraction, size, chroma });
  const form = useRef<HTMLFormElement>(null);

  /**
   * The combobox half, which only exists when there is something to suggest.
   *
   * `aria-activedescendant` rather than moving focus: focus stays in the field so typing keeps
   * working, and the highlighted option is named by id. Moving real focus into the list is the
   * common mistake — it stops the next keystroke reaching the input.
   */
  const listId = `${generated}-suggestions`;
  const [active, setActive] = useState(-1);
  const [open, setOpen] = useState(false);
  const list = suggestions ?? [];
  const showing = open && list.length > 0;
  /**
   * A suggestion list that changes under a highlight would leave it pointing at the wrong row.
   *
   * Keyed on what the list *contains*, not on the array's identity. Filtering is the caller's,
   * so `suggestions` is almost always built inline — `matches.map(value => ({ value }))` — and
   * is therefore a new array on every render. Keying on identity meant this effect fired after
   * every render, including the one that had just moved the highlight: press Down, the
   * highlight appears, the re-render hands over a new array, and the effect clears it again.
   * It was a race, which is why it looked like it worked.
   */
  const listKey = list.map(suggestion => suggestion.value).join('�');
  useEffect(() => { setActive(-1); }, [listKey]);

  const take = (index: number) => {
    const suggestion = list[index]; if (!suggestion) return;
    setQuery(suggestion.value);
    setOpen(false); setActive(-1);
    onSuggestionSelect?.(suggestion);
    onSubmitQuery?.(suggestion.value);
  };

  const onKeyDown = (event: React.KeyboardEvent<HTMLInputElement>) => {
    if (!showing) {
      if (event.key === 'ArrowDown' && list.length) { event.preventDefault(); setOpen(true); setActive(0); }
      return;
    }
    if (event.key === 'ArrowDown') { event.preventDefault(); setActive(index => (index + 1) % list.length); }
    else if (event.key === 'ArrowUp') { event.preventDefault(); setActive(index => (index - 1 + list.length) % list.length); }
    else if (event.key === 'Home') { event.preventDefault(); setActive(0); }
    else if (event.key === 'End') { event.preventDefault(); setActive(list.length - 1); }
    else if (event.key === 'Enter' && active >= 0) { event.preventDefault(); take(active); }
    /* Escape closes the list and stops there. The browser's own Escape on `type="search"`
       clears the field, and losing a query because the suggestions were open would be its
       own small disaster. */
    else if (event.key === 'Escape') { event.preventDefault(); setOpen(false); setActive(-1); }
  };

  return <form ref={form} role="search" className={cx('lg-search', className)} onSubmit={event => { event.preventDefault(); onSubmitQuery?.(query); }}>
    <div ref={glass.ref} {...glass.attributes} className="lg-root lg-search-box" style={glass.style}>
      {glass.decoration}
      <div className="lg-content">
        <LibraryIcon name="search" size={17} className="lg-search-icon" />
        <input {...props} ref={mergedRef} id={id} type="search" aria-label={label} className="lg-search-input"
          value={query}
          onChange={event => { setQuery(event.currentTarget.value); if (suggestions) setOpen(true); }}
          {...(suggestions ? {
            role: 'combobox',
            autoComplete: 'off',
            'aria-expanded': showing,
            'aria-controls': listId,
            'aria-autocomplete': 'list' as const,
            'aria-activedescendant': showing && active >= 0 ? `${listId}-${active}` : undefined,
            onKeyDown,
            onFocus: () => { if (list.length) setOpen(true); },
            /* Closed on the way out, not on blur of the input: a pointer press on an option
               blurs the field before the click lands, and closing there would eat it. */
            onBlur: event => { if (!event.currentTarget.closest('form')?.contains(event.relatedTarget as Node)) setOpen(false); },
          } : {})} />
        {query !== '' && <button type="button" className="lg-search-clear" aria-label={clearLabel ?? strings.clearSearch}
          onClick={() => { setQuery(''); input.current?.focus(); }}>
          <LibraryIcon name="clear" size={17} />
        </button>}
      </div>
    </div>
    {showing && <ul id={listId} role="listbox" aria-label={label} className="lg-search-suggestions">
      {list.map((suggestion, index) => <li
        key={suggestion.value}
        id={`${listId}-${index}`}
        role="option"
        aria-selected={index === active}
        className="lg-search-suggestion"
        /* `pointerdown`, not `click`: click fires after blur, and by then the list is gone. */
        onPointerDown={event => { event.preventDefault(); take(index); }}
        onPointerEnter={() => setActive(index)}>
        {suggestion.icon && <span className="lg-search-suggestion-icon" aria-hidden="true">{suggestion.icon}</span>}
        <span>{suggestion.label ?? suggestion.value}</span>
      </li>)}
    </ul>}
  </form>;
}

'use client';
import {
  useId, type InputHTMLAttributes, type ReactNode, type RefAttributes, type TextareaHTMLAttributes,
} from 'react';
import { cx } from '../system/utils.js';
import { Text } from '../content/text.js';
import type { ControlSize } from '../controls/button.js';

/** Everything both forms share. The ref is not here: it points at a different element in each. */
interface FieldShape {
  /** A real, visible label. A placeholder is a hint about the format, never a substitute. */
  label: ReactNode;
  /** Supporting text shown under the field. Announced with the input. */
  hint?: ReactNode;
  /**
   * Error text. Presence marks the field invalid and wires up `aria-describedby`, so the
   * meaning never rests on a red border alone.
   */
  error?: ReactNode;
  leading?: ReactNode;
  trailing?: ReactNode;
  /** Hide the label visually but keep it for assistive technology and Voice Control. */
  labelHidden?: boolean;
  /**
   * Control height. `small` is a denser form; it does **not** shrink the text, which stays at
   * 16px or above so iOS Safari does not zoom the page when the field is focused.
   */
  controlSize?: Extract<ControlSize, 'small' | 'regular' | 'large'>;
}

/** The single-line form. `ref` lands on the `<input>`, as it always has. */
export interface SingleLineFieldProps extends Omit<InputHTMLAttributes<HTMLInputElement>, 'size'>,
  RefAttributes<HTMLInputElement>, FieldShape {
  multiline?: false;
}

/**
 * The multi-line form. A real `<textarea>`, so Enter inserts a newline, the browser's own
 * resize affordance is there, and spellcheck and dictation behave as they do everywhere else.
 */
export interface MultilineFieldProps extends Omit<TextareaHTMLAttributes<HTMLTextAreaElement>, 'size' | 'rows'>,
  RefAttributes<HTMLTextAreaElement>, FieldShape {
  multiline: true;
  /** Visible lines before it scrolls. `auto` grows with the content instead. */
  rows?: number | 'auto';
}

/**
 * `multiline` is a discriminated union rather than a boolean on one shape, because the two
 * forms genuinely differ: a `<textarea>` has `rows` and no `type`, an `<input>` has `type` and
 * no `rows`, and `ref` points at a different element. Flattening them would make `ref` a union
 * on the single-line form too, which every existing caller would then have to widen.
 */
export type TextFieldProps = SingleLineFieldProps | MultilineFieldProps;

/**
 * A rounded text field with a real `<label for>`.
 *
 * The details that make a web form feel native are all here and all easy to forget:
 * `autocomplete` and `inputmode` should be set by the caller for the field's purpose,
 * the font-size stays at 16px or above so iOS Safari does not zoom on focus, and the focus
 * ring is an `outline` on the container rather than a `box-shadow`.
 */
export function TextField(props: TextFieldProps) {
  const {
    label, hint, error, leading, trailing, labelHidden = false, controlSize = 'regular',
    className, id, ...rest
  } = props;
  const generated = useId();
  const fieldId = id ?? `${generated}-field`;
  const hintId = hint ? `${generated}-hint` : undefined;
  const errorId = error ? `${generated}-error` : undefined;
  const describedBy = [errorId, hintId].filter(Boolean).join(' ') || undefined;

  const shared = {
    id: fieldId,
    className: 'lg-field-input',
    'aria-invalid': error ? true : undefined,
    'aria-describedby': describedBy,
  } as const;

  let control: ReactNode;
  if (rest.multiline) {
    const { multiline: _multiline, rows = 4, ref, ...textarea } = rest as MultilineFieldProps;
    control = <textarea {...textarea} {...shared} ref={ref}
      /* `auto` is `field-sizing: content` where it exists and the given rows where it does
         not — a textarea that does not grow is still a working textarea. */
      rows={rows === 'auto' ? 2 : rows}
      data-autosize={rows === 'auto' ? 'true' : undefined} />;
  } else {
    const { multiline: _multiline, type = 'text', ref, ...input } = rest as SingleLineFieldProps;
    control = <input {...input} {...shared} ref={ref} type={type} />;
  }

  return <div className={cx('lg-field', className)} data-invalid={error ? 'true' : undefined}
    data-control-size={controlSize} data-multiline={rest.multiline ? 'true' : undefined}>
    <Text as="label" variant="subhead" emphasized className={cx('lg-field-label', labelHidden && 'lg-visually-hidden')} {...{ htmlFor: fieldId }}>{label}</Text>
    <div className="lg-field-box">
      {leading && <span className="lg-field-leading" aria-hidden="true">{leading}</span>}
      {control}
      {trailing && <span className="lg-field-trailing">{trailing}</span>}
    </div>
    {error && <Text id={errorId} variant="footnote" tone="destructive" className="lg-field-message">{error}</Text>}
    {hint && !error && <Text id={hintId} variant="footnote" tone="secondary" className="lg-field-message">{hint}</Text>}
  </div>;
}

