export interface FormProps extends FormHTMLAttributes<HTMLFormElement>, RefAttributes<HTMLFormElement> {
  children: ReactNode;
}

/**
 * A settings form: grouped sections of labelled rows.
 *
 * A real `<form>`, so Enter submits, the browser can autofill it, and a submit button means
 * what it says. Content layer — a form is what you are reading, not something floating over it.
 */
export function Form({ children, className, ref, ...props }: FormProps) {
  return <form {...props} ref={ref} className={cx('lg-form', className)}>{children}</form>;
}

export interface FormSectionProps extends Omit<HTMLAttributes<HTMLElement>, 'title'>, RefAttributes<HTMLElement> {
  /**
   * Title case, not ALL CAPS — the uppercase section header went with the iOS 26 design.
   * Rendered as a real heading, so it is a landmark a screen reader can jump between.
   */
  header?: ReactNode;
  /** Explanation under the group. Attached to the section, so it is read with it. */
  footer?: ReactNode;
  children: ReactNode;
}

export function FormSection({ header, footer, children, className, ref, ...props }: FormSectionProps) {
  const generated = useId();
  const headerId = header ? `${generated}-header` : undefined;
  const footerId = footer ? `${generated}-footer` : undefined;
  return <section {...props} ref={ref} className={cx('lg-form-section', className)}
    aria-labelledby={headerId} aria-describedby={footerId}>
    {header && <Text as="h3" id={headerId} variant="subhead" emphasized tone="secondary" className="lg-form-header">{header}</Text>}
    <div className="lg-form-group">{children}</div>
    {footer && <Text id={footerId} variant="footnote" tone="secondary" className="lg-form-footer">{footer}</Text>}
  </section>;
}

export interface FormRowProps extends Omit<HTMLAttributes<HTMLDivElement>, 'title'>, RefAttributes<HTMLDivElement> {
  /**
   * What the control is for. Pass a string and the row wires it up as a real `<label for>`
   * around the control — which is also what gives the label a 44pt hit region of its own.
   */
  label: ReactNode;
  /** A second line under the label. */
  description?: ReactNode;
  /**
   * The error for this row. It goes under the control and is connected with
   * `aria-describedby`, so it is heard rather than only seen in red.
   */
  error?: ReactNode;
  /** The control. A field, a switch, a stepper, a menu button. */
  children: ReactNode;
  /**
   * `inline` puts the control on the same line as the label, which is right for a switch or a
   * short value. `stacked` puts it underneath, which is what a text field needs at any width
   * the label might wrap at.
   */
  layout?: 'inline' | 'stacked';
}

/**
 * One labelled row.
 *
 * The title is a `<span>`, not a `<label>`, and that is deliberate. The obvious version wraps
 * the control in a `<label>` so the words are part of its hit region — which is how a settings
 * row behaves and was the first thing tried here. It does not work, for two reasons that both
 * point the same way:
 *
 * - Every control in this library already carries its own accessible name; `GlassSwitch`,
 *   `GlassStepper` and `GlassSlider` all require `aria-label`, and `TextField` takes a real
 *   `label`. Wrapping them adds a second name rather than the first one.
 * - `GlassSwitch` and `TextField` render a `<label>` of their own. A `<label>` inside a
 *   `<label>` is invalid, and the browser's answer is that the outer one stops working:
 *   measured, clicking the row's words did nothing at all.
 *
 * So the row lays out and groups, and naming stays where it already was. Where the words
 * should also be a hit region, give the control `labelHidden` and let it own them.
 */
export function FormRow({
  label, description, error, children, layout = 'inline', className, ref, ...props
}: FormRowProps) {
  const generated = useId();
  const errorId = error ? `${generated}-error` : undefined;
  return <div {...props} ref={ref} className={cx('lg-form-row', className)}
    data-layout={layout} data-invalid={error ? 'true' : undefined}>
    <div className="lg-form-row-label">
      <span className="lg-form-row-labels">
        <Text as="span" variant="body" className="lg-form-row-title">{label}</Text>
        {description && <Text as="span" variant="footnote" tone="secondary">{description}</Text>}
      </span>
      <span className="lg-form-row-control" aria-describedby={errorId}>{children}</span>
    </div>
    {error && <Text id={errorId} variant="footnote" tone="destructive" className="lg-form-row-error">{error}</Text>}
  </div>;
}

'use client';
import { useEffect, useRef, type CSSProperties, type HTMLAttributes, type ReactNode, type RefAttributes } from 'react';
import { inDevelopment, warnOnce } from '../system/warn.js';
import { cx } from '../system/utils.js';

/** The HIG's minimum between controls, and the room a focus ring needs. */
const MIN_GAP = 8;

export interface GridProps extends HTMLAttributes<HTMLDivElement>, RefAttributes<HTMLDivElement> {
  children: ReactNode;
  /**
   * The narrowest an item may be before the grid drops a column. Columns are derived from it,
   * which is what makes the layout answer to the space it is in rather than to a guess about
   * the device.
   */
  minItemWidth?: number;
  /** A fixed column count instead. Use it only where the count is the design. */
  columns?: number;
  /**
   * Gap between items, from the spacing grid. Floored at 8 — the HIG's minimum between
   * controls, and the room a focus ring needs.
   *
   * There is deliberately no `itemPadding`. The first version of this put padding on every
   * child to make that room, which fights whatever padding the child already had and loses
   * to it: measured, `.lg-button`'s own padding won and the setting did nothing.
   */
  gap?: number;
}

/**
 * A grid of same-kind items that reflows by the space it has.
 *
 * `minItemWidth` rather than a breakpoint list: the grid is asked to fit items of a certain
 * size and works out the columns, so it is right inside a sidebar, inside a split view's
 * middle column, and full width, without any of those being enumerated anywhere.
 *
 * Content layer. Items on a grid are content; the glass belongs to whatever floats over them.
 *
 * **No virtualisation**, deliberately. It is a real need at a few thousand items and it is a
 * different component with different trade-offs — measured heights, scroll anchoring, and a
 * keyboard model that has to work with rows that do not exist yet. Doing a shallow version
 * here would make the honest one harder to add later.
 */
export function Grid({
  children, minItemWidth = 220, columns, gap = 16, className, style, ref, ...props
}: GridProps) {
  const root = useRef<HTMLDivElement>(null);
  useEffect(() => {
    if (!inDevelopment() || gap >= MIN_GAP || !root.current) return;
    warnOnce(root.current, 'grid-gap',
      `Grid gap is ${gap}px. Under ${MIN_GAP} an item's focus ring is drawn over its neighbour, which only the people navigating by keyboard ever see.`);
  }, [gap]);
  return <div {...props} ref={node => {
    root.current = node;
    if (typeof ref === 'function') ref(node); else if (ref) ref.current = node;
  }} className={cx('lg-grid', className)} style={{
    '--lg-grid-min': `${minItemWidth}px`,
    '--lg-grid-gap': `${Math.max(MIN_GAP, gap)}px`,
    ...(columns ? { '--lg-grid-columns': String(columns) } : {}),
    ...style,
  } as CSSProperties} data-fixed={columns ? 'true' : undefined}>{children}</div>;
}

'use client';
import {
  createContext, useCallback, useContext, useEffect, useId, useMemo, useRef, useState,
  type HTMLAttributes, type ReactNode, type RefAttributes,
} from 'react';
import { GlassButton } from '../controls/button.js';
import { NavigationBar } from '../navigation/nav-bar.js';
import { LibraryIcon } from '../system/icon.js';
import { useGlassPolicy } from '../system/provider.js';
import { useGlassStrings } from '../system/strings.js';
import { cx } from '../system/utils.js';

/** One screen on the stack. `key` is what identifies it; `title` is what the bar says. */
export interface NavigationPage {
  key: string;
  title: string;
  subtitle?: ReactNode;
  /** Trailing controls for this screen's bar. Group by function; the primary action alone. */
  trailing?: ReactNode;
  content: ReactNode;
}

interface StackApi {
  push: (page: NavigationPage) => void;
  pop: () => void;
  /** Back to the first screen in one step, the way a long-press on Back does. */
  popToRoot: () => void;
  /** How deep we are. 1 is the root. */
  depth: number;
  canGoBack: boolean;
}

const StackContext = createContext<StackApi | null>(null);

/**
 * The stack, from inside it. A screen pushes the next one without being handed a callback
 * through three layers of props.
 *
 * Throws outside a `NavigationStack`, rather than returning a no-op: a push that silently does
 * nothing is a dead button, and a dead button is harder to find than an error.
 */
export function useNavigationStack(): StackApi {
  const api = useContext(StackContext);
  if (!api) throw new Error('useNavigationStack must be used inside a <NavigationStack>. Wrap the screen that calls it.');
  return api;
}

export interface NavigationStackProps extends Omit<HTMLAttributes<HTMLDivElement>, 'title' | 'children'>,
  RefAttributes<HTMLDivElement> {
  /** The screen at the bottom of the stack. Always present; it cannot be popped. */
  root: NavigationPage;
  /**
   * Drive the stack yourself — from a router, say. Omit it and the component keeps its own.
   * The array is the screens *above* the root, in order.
   */
  pages?: NavigationPage[];
  onPagesChange?: (pages: NavigationPage[]) => void;
  /**
   * What the back button says. `title` carries the previous screen's name, which is what the
   * system does when it fits; `chevron` is the bare arrow for when it does not.
   */
  backLabel?: 'title' | 'chevron';
  /** Heading level for the root screen's large title. See `NavigationBar.headingLevel`. */
  headingLevel?: 1 | 2 | 3 | 4 | 5 | 6;
}

/**
 * A stack of screens with one bar that follows it.
 *
 * The back button is the whole point and the part that is usually wrong. It carries the
 * **previous screen's title**, because "Back" tells you the direction and not the
 * destination — you already know you are going back. Its accessible name says both, so a
 * screen reader hears "Back to Settings" rather than a chevron.
 *
 * Pushing and popping move focus to the new screen's `<main>`. Without that, a keyboard user
 * presses a row, the screen changes, and their next Tab continues from wherever the row they
 * pressed used to be — on a screen that no longer exists.
 *
 * The transition is a cross-fade with a small slide, mirrored for a pop and for RTL, and it
 * is the slide that Reduce Motion removes: direction is the thing that reads as movement, and
 * a fade alone still says "this is different now".
 */
export function NavigationStack({
  root, pages: controlled, onPagesChange, backLabel = 'title', headingLevel = 1, className, ref, ...props
}: NavigationStackProps) {
  const [own, setOwn] = useState<NavigationPage[]>([]);
  const pages = controlled ?? own;
  const strings = useGlassStrings();
  const policy = useGlassPolicy();
  const generated = useId();
  const mainRef = useRef<HTMLElement>(null);
  const first = useRef(true);
  /** Which way the last change went, so the animation knows whether it is a push or a pop. */
  const [direction, setDirection] = useState<'push' | 'pop'>('push');

  const commit = useCallback((next: NavigationPage[], way: 'push' | 'pop') => {
    setDirection(way);
    if (controlled === undefined) setOwn(next);
    onPagesChange?.(next);
  }, [controlled, onPagesChange]);

  const api = useMemo<StackApi>(() => ({
    push: page => commit([...pages, page], 'push'),
    pop: () => commit(pages.slice(0, -1), 'pop'),
    popToRoot: () => commit([], 'pop'),
    depth: pages.length + 1,
    canGoBack: pages.length > 0,
  }), [pages, commit]);

  const current = pages[pages.length - 1] ?? root;
  const previous = pages.length > 1 ? pages[pages.length - 2] : pages.length === 1 ? root : null;

  /**
   * Focus follows the screen. Not on the first render: focus belongs wherever the browser put
   * it, and moving it on load skips past whatever the page put before the content.
   */
  useEffect(() => {
    if (first.current) { first.current = false; return; }
    mainRef.current?.focus({ preventScroll: true });
    mainRef.current?.scrollTo?.({ top: 0 });
  }, [current.key]);

  const back = previous && <GlassButton
    variant="plain" controlSize="small" className="lg-stack-back"
    /* The visible words are the destination; the spoken name says the direction too, because
       "Settings" on its own does not tell a screen-reader user that this goes back. */
    aria-label={`${strings.back} ${previous.title}`}
    onClick={() => api.pop()}>
    <LibraryIcon name="chevronForward" size={17} className="lg-stack-back-chevron" />
    {backLabel === 'title' && <span className="lg-stack-back-title">{previous.title}</span>}
  </GlassButton>;

  return <StackContext.Provider value={api}>
    <div {...props} ref={ref} className={cx('lg-stack', className)} data-depth={api.depth}>
      <NavigationBar
        title={current.title}
        subtitle={current.subtitle}
        leading={back}
        trailing={current.trailing}
        /* The root screen gets the large title; a screen you navigated into starts compact,
           because the back button is already naming where you came from on the same line. */
        largeTitle={pages.length === 0}
        headingLevel={headingLevel}
        aria-label={current.title} />
      <main
        ref={mainRef}
        id={`${generated}-screen`}
        tabIndex={-1}
        className="lg-stack-screen"
        data-direction={policy.reduceMotion ? 'none' : direction}
        /* Keyed on the screen: React replaces the subtree, which is what restarts the entry
           animation and what makes the outgoing screen's state go away rather than leak into
           the next one. */
        key={current.key}>
        {current.content}
      </main>
    </div>
  </StackContext.Provider>;
}

'use client';
import { useEffect, useRef, useState, type CSSProperties, type HTMLAttributes, type ReactNode, type RefAttributes } from 'react';
import { ScrollEdge } from '../navigation/scroll-edge.js';
import { cx, useMergedRef } from '../system/utils.js';

export interface ScreenProps extends Omit<HTMLAttributes<HTMLDivElement>, 'title'>, RefAttributes<HTMLDivElement> {
  /** Floating navigation pinned to the top: a navigation bar, a toolbar. */
  top?: ReactNode;
  /** Floating navigation pinned to the bottom: a tab bar. */
  bottom?: ReactNode;
  children: ReactNode;
  /**
   * `container` makes the screen its own scroll view, the full height of the viewport — what
   * an application shell wants. `page` leaves the document scrolling and pins the bars to the
   * viewport instead, for a site that is a long document with navigation floating over it.
   */
  scroll?: 'container' | 'page';
  /**
   * The scroll edge effect under the bars. `soft` is the iOS dissolve, `hard` the macOS
   * boundary, `none` for a screen whose bars are opaque anyway.
   */
  edge?: 'soft' | 'hard' | 'none';
  /** Height of the dissolve. Keep it the same across the columns of a split view. */
  edgeHeight?: number;
  /**
   * Extra breathing room under the bottom bar, on top of the measured bar height. The default
   * is the spacing the system leaves between a tab bar and the content above it.
   */
  inset?: number;
}

/**
 * The screen: bars that float, content that runs underneath them, and one scroll edge effect.
 *
 * Three rules from the HIG's layout and scroll-views pages, made into the default rather than
 * something each application re-derives:
 *
 * - The background extends under the bars — content is continuous, and what separates the bar
 *   from it is the **scroll edge effect**, never a bar background, a border or a divider. That
 *   is exactly the custom bar treatment the current design removed.
 * - Controls stay inside the safe area, so the insets go on the **bars**, not on the content.
 *   Padding the content instead leaves a strip of blank page above a bar that is already clear
 *   of the notch.
 * - **One scroll edge effect per view.** It belongs to the scroll view, so the screen owns it;
 *   nesting another inside means two dissolves fighting over the same boundary.
 *
 * The content's padding is the measured height of each bar, not a number copied from a design:
 * a bar is as tall as its own contents, which change with the text size, and a hard-coded
 * reservation is wrong for everyone who is not using the default.
 */
export function Screen({
  top, bottom, children, scroll = 'container', edge = 'soft', edgeHeight = 44, inset = 12,
  className, style, ref, ...props
}: ScreenProps) {
  const topBar = useRef<HTMLDivElement>(null);
  const bottomBar = useRef<HTMLDivElement>(null);
  const [scroller, scrollerRef] = useMergedRef<HTMLDivElement>(undefined);
  const [bars, setBars] = useState({ top: 0, bottom: 0 });

  /**
   * Measured, and re-measured whenever a bar changes size — which is what happens at the
   * largest accessibility text sizes, when a tab bar minimizes on scroll, and when the
   * keyboard changes the viewport.
   */
  useEffect(() => {
    const nodes = [topBar.current, bottomBar.current].filter(Boolean) as HTMLElement[];
    if (!nodes.length) { setBars({ top: 0, bottom: 0 }); return; }
    const measure = () => setBars({
      top: topBar.current?.offsetHeight ?? 0,
      bottom: bottomBar.current?.offsetHeight ?? 0,
    });
    const observer = new ResizeObserver(measure);
    for (const node of nodes) observer.observe(node);
    measure();
    return () => observer.disconnect();
  }, [top, bottom]);

  const container = scroll === 'container';
  const variables = {
    '--lg-screen-top': `${bars.top}px`,
    '--lg-screen-bottom': `${bars.bottom}px`,
    '--lg-screen-inset': `${inset}px`,
  } as CSSProperties;

  return <div {...props} ref={ref} className={cx('lg-screen', className)} data-scroll={scroll}
    style={{ ...variables, ...style }}>
    {top && <div ref={topBar} className="lg-screen-bar" data-edge="top">{top}</div>}

    <div ref={container ? scrollerRef : undefined} className="lg-screen-scroll">
      {/* One per view, and it belongs to the scroll view rather than to either bar. */}
      {edge !== 'none' && top && <ScrollEdge
        targetRef={container ? scroller : undefined}
        edge="top" variant={edge} height={edgeHeight} className="lg-screen-edge" />}
      <div className="lg-screen-content">{children}</div>
    </div>

    {bottom && <div ref={bottomBar} className="lg-screen-bar" data-edge="bottom">{bottom}</div>}
  </div>;
}

'use client';
import {
  useCallback, useEffect, useId, useRef, useState,
  type CSSProperties, type HTMLAttributes, type ReactNode, type RefAttributes,
} from 'react';
import { useGlassStrings } from '../system/strings.js';
import { cx, useControllable } from '../system/utils.js';
import { useSizeClass } from '../system/size-class.js';
import { useToggling } from '../system/leave.js';
import { NavigationStack, type NavigationPage } from './navigation-stack.js';

export interface SplitViewProps extends Omit<HTMLAttributes<HTMLDivElement>, 'title'>, RefAttributes<HTMLDivElement> {
  /** The leading column: a sidebar of destinations. */
  sidebar: ReactNode;
  /** The title of the whole split view. One title, on the view — not one per column. */
  title: string;
  /** What the sidebar's current selection is showing. */
  children: ReactNode;
  /** The trailing column: details about the current selection. See `Inspector`. */
  inspector?: ReactNode;

  /** Sidebar width in px, and the range a drag may move it through. */
  sidebarWidth?: number;
  minSidebarWidth?: number;
  maxSidebarWidth?: number;
  onSidebarWidthChange?: (width: number) => void;

  /** Whether the sidebar is showing. Hideable, because a wide view is not always wanted. */
  sidebarVisible?: boolean;
  defaultSidebarVisible?: boolean;
  onSidebarVisibleChange?: (visible: boolean) => void;

  inspectorVisible?: boolean;
  defaultInspectorVisible?: boolean;
  onInspectorVisibleChange?: (visible: boolean) => void;
  inspectorWidth?: number;

  /**
   * What the compact environment pushes on top of the sidebar: the current selection, named.
   *
   * Pass it whenever something is selected. The columns cannot sit side by side on a phone, so
   * this is the only thing that shows there — a split view without it is a sidebar and nothing
   * else, which is a legitimate state (nothing selected yet) and a bad default.
   */
  compact?: { title: string; content: ReactNode };
  /**
   * Back was pressed in the compact stack. The detail closes either way; this is how the
   * caller hears about it, so their selection state can follow.
   */
  onCompactBack?: () => void;
}

const DEFAULT_SIDEBAR = 260, MIN_SIDEBAR = 180, MAX_SIDEBAR = 400, DEFAULT_INSPECTOR = 300;
/** The divider's own width, which the columns do not get to use. */
const DIVIDER = 1;

/**
 * Two or three columns, and the rules that make them a split view rather than three divs.
 *
 * From the HIG's split-views page, in the order they are usually got wrong:
 *
 * - **Only in a regular environment.** Columns cannot sit side by side in a compact one, so
 *   this collapses into a `NavigationStack` below 768px — which is what the system does, and
 *   why `compact` is not optional: a split view that simply vanished on a phone would be a
 *   blank screen.
 * - **One title for the whole view**, not one per column.
 * - **A visible divider**, 1pt, that can be dragged — and clamped to a sensible range, so a
 *   drag cannot leave a column too narrow to use or wide enough to swallow the content.
 * - **The sidebar can be hidden**, and there is more than one way to bring it back.
 *
 * The divider is also a control for the keyboard: `role="separator"` with arrow keys, because
 * a column width that can only be set by dragging is a column width a keyboard user cannot set.
 */
export function SplitView({
  sidebar, title, children, inspector,
  sidebarWidth: controlledWidth, minSidebarWidth = MIN_SIDEBAR, maxSidebarWidth = MAX_SIDEBAR,
  onSidebarWidthChange,
  sidebarVisible: controlledSidebar, defaultSidebarVisible = true, onSidebarVisibleChange,
  inspectorVisible: controlledInspector, defaultInspectorVisible = true, onInspectorVisibleChange,
  inspectorWidth = DEFAULT_INSPECTOR,
  compact, onCompactBack, className, style, ref, ...props
}: SplitViewProps) {
  const compactEnvironment = useSizeClass() === 'compact';
  const strings = useGlassStrings();
  const generated = useId();
  const root = useRef<HTMLDivElement>(null);

  const [width, setWidth] = useControllable(controlledWidth, DEFAULT_SIDEBAR, onSidebarWidthChange);
  const [sidebarOn] = useControllable(controlledSidebar, defaultSidebarVisible, onSidebarVisibleChange);
  const [inspectorOn] = useControllable(controlledInspector, defaultInspectorVisible, onInspectorVisibleChange);
  /* Only a show or a hide animates the column's width. Resizing it — by drag or by arrow key —
     has to be exactly as fast as the input, and an animated `flex-basis` made both feel broken. */
  const sidebarToggling = useToggling(sidebarOn);
  const inspectorToggling = useToggling(inspectorOn);

  /**
   * How wide the view itself is, so the range can be bounded by the room there actually is.
   *
   * Without this the sidebar could be set to its declared maximum inside a container too narrow
   * to give it — `aria-valuenow` said 400 while the column rendered at 304. A width nobody has
   * is not a width, and a screen reader reading it out is being told something untrue.
   */
  const [available, setAvailable] = useState(0);
  useEffect(() => {
    const node = root.current;
    if (!node || typeof ResizeObserver === 'undefined') return;
    const observer = new ResizeObserver(([entry]) => setAvailable(entry.contentRect.width));
    observer.observe(node);
    return () => observer.disconnect();
  }, [compactEnvironment]);

  /** What the content column must keep whatever the sidebar asks for. */
  const MIN_CONTENT = 160;
  const ceiling = available
    ? Math.max(minSidebarWidth, available - (inspector && inspectorOn ? inspectorWidth : 0) - DIVIDER - MIN_CONTENT)
    : maxSidebarWidth;
  const reachableMax = Math.min(maxSidebarWidth, ceiling);

  const clamp = useCallback(
    (value: number) => Math.min(reachableMax, Math.max(minSidebarWidth, Math.round(value))),
    [minSidebarWidth, reachableMax],
  );

  /**
   * The divider drag. Measured against the root rather than against the last pointer position,
   * so a drag that outruns the pointer does not accumulate error, and mirrored in RTL because
   * the sidebar is on the leading side.
   */
  const [dragging, setDragging] = useState(false);

  /** Set by Back in the compact stack, cleared by the next selection. */
  const [backed, setBacked] = useState(false);
  const lastTitle = useRef(compact?.title);
  if (compact?.title !== lastTitle.current) { lastTitle.current = compact?.title; if (backed) setBacked(false); }
  const onDividerDown = (event: React.PointerEvent<HTMLDivElement>) => {
    if (event.button !== 0 || !event.isPrimary) return;
    const node = root.current; if (!node) return;
    const box = node.getBoundingClientRect();
    const rtl = getComputedStyle(node).direction === 'rtl';
    event.currentTarget.setPointerCapture(event.pointerId);
    setDragging(true);
    let frame = 0;
    const move = (moveEvent: PointerEvent) => {
      cancelAnimationFrame(frame);
      frame = requestAnimationFrame(() => setWidth(clamp(rtl ? box.right - moveEvent.clientX : moveEvent.clientX - box.left)));
    };
    const end = () => {
      cancelAnimationFrame(frame); setDragging(false);
      window.removeEventListener('pointermove', move);
      window.removeEventListener('pointerup', end); window.removeEventListener('pointercancel', end);
    };
    window.addEventListener('pointermove', move, { passive: true });
    window.addEventListener('pointerup', end); window.addEventListener('pointercancel', end);
  };

  /**
   * Compact: a stack, not a narrower set of columns.
   *
   * `NavigationSplitView` degrades exactly this way on iPhone — the sidebar becomes the root
   * screen and a selection pushes the detail on top of it — so the back button leads to the
   * list, which is the relationship the columns were expressing all along.
   */
  if (compactEnvironment) {
    const rootPage: NavigationPage = { key: 'sidebar', title, content: sidebar };
    const detail: NavigationPage[] = compact && !backed
      ? [{ key: 'detail', title: compact.title, content: compact.content }]
      : [];
    return <NavigationStack {...props} className={cx('lg-split', className)} root={rootPage} pages={detail}
      onPagesChange={next => {
        if (next.length) return;
        /* Back has to actually go back. Driving the stack purely from `compact` made it a
           dead button: the caller's selection had not changed, so the next render put the
           detail straight back and nothing moved. The local flag closes it now; a new
           selection — a different title — clears the flag and pushes again, which is what the
           two columns were doing all along. */
        setBacked(true);
        onCompactBack?.();
      }} />;
  }

  return <div {...props} ref={node => {
    root.current = node;
    if (typeof ref === 'function') ref(node); else if (ref) ref.current = node;
  }} className={cx('lg-split', className)} data-dragging={dragging ? 'true' : undefined}
    /* The clamped width, not the requested one: a controlled caller may ask for more than the
       view can give, and what is drawn and what is announced have to be the same number. */
    style={{ '--lg-split-sidebar': `${clamp(width)}px`, '--lg-split-inspector': `${inspectorWidth}px`, ...style } as CSSProperties}>
    {/**
      * The columns stay in the tree when they are hidden, so that hiding one can be watched.
      *
      * A column that is simply not rendered goes from 260px to nothing between two frames, and
      * the reader is left to work out whether it collapsed, moved, or was never there. The
      * stylesheet closes it to nothing and then turns its visibility off, which is what takes
      * it off the tab order and out of the accessibility tree once it is gone.
      *
      * The cost, and it is a real one: the content you pass as `sidebar` or `inspector` stays
      * mounted while hidden. Its effects keep running. Anything expensive enough to mind about
      * should be unmounted by the caller, which is the only place that knows.
      */}
    <div className="lg-split-column" data-column="sidebar" data-hidden={sidebarOn ? undefined : 'true'}
      data-toggling={sidebarToggling ? 'true' : undefined}>
      <div className="lg-split-inner">{sidebar}</div>
    </div>
    {sidebarOn && <>
      {/**
        * "Make the divider always visible" and "let people resize". Both, and the keyboard
        * equivalent: a width that can only be set by dragging cannot be set without a pointer.
        */}
      <div
        role="separator"
        aria-orientation="vertical"
        aria-label={strings.resizeSidebar}
        aria-valuenow={clamp(width)}
        aria-valuemin={minSidebarWidth}
        /* The reachable maximum, which in a narrow view is less than the declared one. */
        aria-valuemax={reachableMax}
        aria-controls={`${generated}-sidebar`}
        tabIndex={0}
        className="lg-split-divider"
        onPointerDown={onDividerDown}
        onDoubleClick={() => setWidth(DEFAULT_SIDEBAR)}
        onKeyDown={event => {
          const step = event.shiftKey ? 40 : 8;
          if (event.key === 'ArrowRight') setWidth(clamp(width + step));
          else if (event.key === 'ArrowLeft') setWidth(clamp(width - step));
          else if (event.key === 'Home') setWidth(minSidebarWidth);
          else if (event.key === 'End') setWidth(maxSidebarWidth);
          else return;
          event.preventDefault();
        }} />
    </>}

    <div className="lg-split-column" data-column="content" id={`${generated}-sidebar`}>
      <div className="lg-split-inner">{children}</div>
    </div>

    {inspector && <div className="lg-split-column" data-column="inspector" data-hidden={inspectorOn ? undefined : 'true'}
      data-toggling={inspectorToggling ? 'true' : undefined}>
      <div className="lg-split-inner">{inspector}</div>
    </div>}
  </div>;
}

/** `title` is the column's heading, not an HTML tooltip — the same trade the overlays make. */
export interface InspectorProps extends Omit<HTMLAttributes<HTMLElement>, 'title'>, RefAttributes<HTMLElement> {
  /** What is being inspected. A heading for the column, not for the whole view. */
  title?: ReactNode;
  children: ReactNode;
}

/**
 * The trailing column: details about whatever is selected.
 *
 * Trailing, always — the sidebar chooses, the content shows, the inspector refines, and that
 * order is the reading order. Its controls are dense, so they use rounded rectangles rather
 * than capsules: a column of capsules at this width is mostly gap.
 *
 * Content layer. It is a region of the window, not something floating over it; giving it glass
 * would put a translucent panel between the reader and the thing they are editing.
 */
export function Inspector({ title, children, className, ref, ...props }: InspectorProps) {
  return <aside {...props} ref={ref} className={cx('lg-inspector', className)}>
    {title && <header className="lg-inspector-title">{title}</header>}
    <div className="lg-inspector-body">{children}</div>
  </aside>;
}

'use client';
import { useEffect, useRef, useState, type HTMLAttributes, type KeyboardEvent, type PointerEvent, type RefAttributes } from 'react';
import { useGlassSurface, type GlassSurfaceOptions } from '../system/material.js';
import { splitSurface } from '../system/props.js';
import { SharedSurface } from '../system/surface.js';
import { cx, useControllable } from '../system/utils.js';
import { inDevelopment, warnOnce } from '../system/warn.js';
import { GlassMenu, type GlassMenuItem } from '../overlays/menu.js';

export interface MenuBarMenu {
  key: string;
  /**
   * One word wherever one word will do — the titles are scanned, not read, and the bar has to
   * survive a narrow window. Title case if it takes more than one.
   */
  title: string;
  items: GlassMenuItem[];
  /**
   * What a checkmark in this menu means, exactly as on `GlassMenu`. `multiple` (the default)
   * is a set of independent toggles; `single` is one choice out of the list.
   *
   * It is per menu rather than per bar because one menu bar routinely has both: Appearance is
   * one choice out of three, and the accessibility switches are three independent ones. A menu
   * of radios announced as checkboxes tells a screen-reader user that picking another will
   * leave the first one on, which is not what happens.
   */
  selection?: 'multiple' | 'single';
  /**
   * A whole menu that does not apply right now. Still drawn: a menu bar that changes shape is
   * a menu bar nobody can learn. Same rule one level down — disable an item, never hide it.
   */
  disabled?: boolean;
}

export interface MenuBarProps extends Omit<HTMLAttributes<HTMLDivElement>, 'children'>, RefAttributes<HTMLDivElement>, GlassSurfaceOptions {
  menus: MenuBarMenu[];
  'aria-label': string;
  /** Which menu is open, if the application wants to drive it. `null` is "none". */
  open?: string | null;
  defaultOpen?: string | null;
  onOpenChange?: (key: string | null) => void;
}

/**
 * The command surface of a desktop application: a row of titles, each one a menu.
 *
 * What separates it from a row of menu buttons is what happens once one is open. The bar takes
 * over: moving the pointer across the titles walks the open menu along with it, and so do the
 * arrow keys — **one** press per menu, not close-then-open. That is the behaviour people have
 * from every Mac they have ever used, and without it a menu bar is a row of buttons that
 * happen to be next to each other.
 *
 * The rest is the same contract `GlassMenu` already keeps: Down opens, the menu keyboard model
 * takes over inside, Escape closes and hands focus back to the title. The whole bar is one tab
 * stop, so Tab crosses it rather than walking through every menu in it.
 *
 * Navigation layer, so it is glass — but only the bar. The titles are items on it.
 */
export function MenuBar({
  menus, 'aria-label': label, open: controlledOpen, defaultOpen = null, onOpenChange,
  className, style, ref, ...rest
}: MenuBarProps) {
  const [surface, props] = splitSurface(rest);
  const glass = useGlassSurface<HTMLDivElement>({ ...surface, radius: surface.radius ?? 'pill' }, ref);
  const [openKey, setOpenKey] = useControllable<string | null>(controlledOpen, defaultOpen, onOpenChange);

  /**
   * Which title Tab lands on. Follows the menu that is open, and otherwise the last one
   * touched — a menu bar you tab back into should be where you left it.
   */
  const [focusKey, setFocusKey] = useState<string | null>(null);
  const enabled = menus.filter(menu => !menu.disabled);
  const current = openKey ?? focusKey;
  const tabStop = enabled.find(menu => menu.key === current)?.key ?? enabled[0]?.key;

  useEffect(() => {
    if (!inDevelopment()) return;
    const node = glass.root.current; if (!node) return;
    const empty = menus.find(menu => menu.items.length === 0);
    if (empty) {
      warnOnce(node, 'menubar-empty',
        `MenuBar menu "${empty.title}" has no items, so it is a title that opens nothing. Give it its commands, disabled if they do not apply, or leave the menu out.`);
    }
  }, [menus, glass.root]);

  const titleAt = (key: string) =>
    glass.root.current?.querySelector<HTMLButtonElement>(`[data-menu-key="${CSS.escape(key)}"]`) ?? null;

  const jump = (menu: MenuBarMenu | undefined) => {
    if (!menu) return;
    setFocusKey(menu.key);
    titleAt(menu.key)?.focus();
  };

  const move = (from: string | null, delta: number) => {
    if (!enabled.length) return;
    const index = enabled.findIndex(menu => menu.key === from);
    const next = enabled[(index + delta + enabled.length) % enabled.length] ?? enabled[0];
    setFocusKey(next.key);
    /* Open stays open. This is the part a row of menu buttons cannot do: the arrow key moves
       the open menu rather than closing one and opening another, so there is no frame in
       between with nothing on screen. */
    if (openKey !== null) setOpenKey(next.key); else titleAt(next.key)?.focus();
  };

  const keyboard = (event: KeyboardEvent<HTMLDivElement>) => {
    /* The open menu's own keyboard model runs first and marks what it used — Up and Down,
       Home and End, type-ahead, Escape. Only what it left goes to the bar. */
    if (event.defaultPrevented || event.ctrlKey || event.metaKey) return;
    const rtl = getComputedStyle(event.currentTarget).direction === 'rtl';
    const forward = rtl ? 'ArrowLeft' : 'ArrowRight';
    const backward = rtl ? 'ArrowRight' : 'ArrowLeft';
    if (event.key === forward) { event.preventDefault(); move(current, 1); }
    else if (event.key === backward) { event.preventDefault(); move(current, -1); }
    else if (event.key === 'ArrowDown' && openKey === null && tabStop) { event.preventDefault(); setOpenKey(tabStop); }
    else if (event.key === 'Home' && openKey === null) { event.preventDefault(); jump(enabled[0]); }
    else if (event.key === 'End' && openKey === null) { event.preventDefault(); jump(enabled[enabled.length - 1]); }
  };

  /**
   * Where the pointer was the last time the bar heard from it.
   *
   * Not bookkeeping — it is the difference between "the pointer moved onto this title" and
   * "this title moved under the pointer". Opening a menu with the mouse leaves the cursor
   * parked on that title; walking to the next menu with the arrow keys hides one panel and
   * shows another, and the browser then re-runs its boundary logic and delivers a pointer
   * event at the cursor's unchanged position. Read as a hover, that yanks the menu straight
   * back to where the mouse happens to be sitting — press Right, watch it go right and bounce
   * back. A synthesised event repeats the last coordinates exactly, so comparing them is what
   * tells the two apart.
   */
  const lastPoint = useRef<{ x: number; y: number } | null>(null);

  /**
   * Moving the pointer onto a title while a menu is open switches to it, and only then: with
   * nothing open the pointer is passing over, not asking for anything.
   *
   * Mouse and pen only. A finger dragging across the bar is scrolling or is on its way
   * somewhere, and opening four menus on the way past is not what it asked for.
   */
  const hover = (event: PointerEvent<HTMLButtonElement>, menu: MenuBarMenu) => {
    if (event.pointerType === 'touch' || openKey === null || menu.disabled || menu.key === openKey) return;
    const previous = lastPoint.current;
    if (previous && previous.x === event.clientX && previous.y === event.clientY) return;
    setFocusKey(menu.key);
    setOpenKey(menu.key);
  };
  /* Recorded on the way up through the bar, so a title's own handler has run first and is
     still comparing against the position before this event. */
  const seen = (event: PointerEvent<HTMLDivElement>) => {
    lastPoint.current = { x: event.clientX, y: event.clientY };
  };

  return <div {...props} ref={glass.ref} {...glass.attributes} role="menubar" aria-label={label} aria-orientation="horizontal"
    className={cx('lg-root lg-menubar', className)} style={{ ...glass.style, ...style }} onKeyDown={keyboard}
    onPointerMove={seen} onPointerDown={seen}>
    {glass.decoration}
    <div className="lg-content"><SharedSurface value={true}>
      {menus.map(menu => <GlassMenu
        key={menu.key}
        aria-label={menu.title}
        items={menu.items}
        selection={menu.selection}
        align="start"
        placement="below"
        open={openKey === menu.key}
        /* Reported by the panel rather than only by the title: a press outside light-dismisses
           it in the browser, and the bar has to hear about that or it would still believe a
           menu is open and keep walking the pointer along the titles. */
        onOpenChange={next => { setFocusKey(menu.key); setOpenKey(next ? menu.key : null); }}
        trigger={<button type="button" role="menuitem" className="lg-menubar-title"
          data-menu-key={menu.key} disabled={menu.disabled}
          tabIndex={menu.key === tabStop ? 0 : -1}
          onFocus={() => setFocusKey(menu.key)}
          onPointerEnter={event => hover(event, menu)}>{menu.title}</button>} />)}
    </SharedSurface></div>
  </div>;
}

'use client';
import { useEffect, useRef, useState, type HTMLAttributes, type ReactNode, type RefAttributes } from 'react';
import { cx } from '../system/utils.js';
import { Text } from '../content/text.js';

/**
 * `title` is taken back from HTML: here it is the heading the bar displays, not a tooltip.
 * The ref and the remaining attributes land on the `<header>`; `children` render after it,
 * below the large title, which is the only place they make sense.
 */
export interface NavigationBarProps extends Omit<HTMLAttributes<HTMLElement>, 'title'>, RefAttributes<HTMLElement> {
  title: string;
  /** Controls at the leading edge — a back affordance, a menu. */
  leading?: ReactNode;
  /** Controls at the trailing edge. Group them by function; the primary action stands alone. */
  trailing?: ReactNode;
  /**
   * Show the large title in the content flow. Turn it off for secondary screens, which use
   * the compact title from the start.
   */
  largeTitle?: boolean;
  /** Subtitle shown under the large title only; the compact bar stays to one line. */
  subtitle?: ReactNode;
  /**
   * Heading level for the large title. `1` is right when the bar is the top of the document,
   * which is the usual case and the default. Lower it when the bar sits inside a page that
   * already has an `<h1>` — a stack embedded in a longer document, a demo. A component that
   * always emits `h1` can only be used once per page, and two `h1`s break the heading
   * navigation a screen-reader user relies on to move around.
   *
   * The range runs to 6 because 3 was not low enough for the one place this is actually used:
   * a documentation page whose own example titles are already `h3`, where a bar stuck at 3
   * interleaves sample titles with the page outline and a reader listening to the heading list
   * hears "Settings, Settings, Basics, Adjust, Inbox" as one flat run.
   */
  headingLevel?: 1 | 2 | 3 | 4 | 5 | 6;
  children?: ReactNode;
}

/**
 * A large title that hands over to a compact one as it scrolls away.
 *
 * The compact title is hidden while the large title is still on screen — showing both means
 * the same words twice, which is the most common way this pattern is misread. The bar itself
 * carries no background, border or shadow of its own: separation comes from the glass of the
 * control groups inside it and from the scroll edge effect beneath.
 */
export function NavigationBar({ title, leading, trailing, largeTitle = true, subtitle, headingLevel = 1, 'aria-label': label, className, children, ref, ...props }: NavigationBarProps) {
  const [compact, setCompact] = useState(!largeTitle);
  const sentinel = useRef<HTMLDivElement>(null);
  useEffect(() => {
    if (!largeTitle) { setCompact(true); return; }
    const node = sentinel.current;
    if (!node || typeof IntersectionObserver === 'undefined') return;
    const observer = new IntersectionObserver(([entry]) => setCompact(!entry.isIntersecting), { threshold: 0 });
    observer.observe(node);
    return () => observer.disconnect();
  }, [largeTitle]);
  return <>
    <header {...props} ref={ref} className={cx('lg-navbar', className)} aria-label={label} data-compact={compact ? 'true' : undefined}>
      <div className="lg-navbar-leading">{leading}</div>
      {/* aria-hidden: the large title below is the real heading, so this must not duplicate it. */}
      <div className="lg-navbar-title" aria-hidden="true">{title}</div>
      <div className="lg-navbar-trailing">{trailing}</div>
    </header>
    {largeTitle && <div className="lg-largetitle">
      <Text as={`h${headingLevel}` as const} variant="largeTitle" emphasized>{title}</Text>
      {subtitle && <Text variant="subhead" tone="secondary">{subtitle}</Text>}
      <div ref={sentinel} className="lg-largetitle-sentinel" aria-hidden="true" />
    </div>}
    {children}
  </>;
}

'use client';
import { useEffect, useRef, type HTMLAttributes, type RefAttributes } from 'react';
import { useGlassSurface, type GlassSurfaceOptions } from '../system/material.js';
import { splitSurface } from '../system/props.js';
import { attachPull } from '../system/pull.js';
import { inDevelopment, warnOnce } from '../system/warn.js';
import { cx, useControllable } from '../system/utils.js';

export interface PageControlProps extends Omit<HTMLAttributes<HTMLDivElement>, 'onChange' | 'defaultValue'>,
  RefAttributes<HTMLDivElement>, GlassSurfaceOptions {
  count: number;
  page?: number;
  defaultPage?: number;
  onPageChange?: (page: number) => void;
  /** What the pages are. Required: a row of dots says nothing about what it is counting. */
  'aria-label': string;
  /** How each page is named, for the dot's own label. Defaults to "n / total". */
  formatPage?: (page: number, count: number) => string;
  orientation?: 'horizontal' | 'vertical';
}

/** Past this many, a reader cannot count the dots and the control stops being a position. */
const LEGIBLE = 10;

/**
 * Where you are in an **ordered** set of pages.
 *
 * Order is the whole premise: a page control says "third of five", which is only meaningful
 * if there is a first and a last. A set of unordered destinations is a tab bar, and using
 * this for one tells the reader there is a sequence when there is not.
 *
 * Draggable along its own capsule, because that is how the system one works — a row of dots
 * you can only tap is the same tell as a segmented control you can only click. Each dot is
 * also a real button, so the pointer gesture is an addition to the keyboard path rather than
 * a replacement for it.
 */
export function PageControl({
  count, page: controlled, defaultPage = 0, onPageChange, 'aria-label': label, formatPage,
  orientation = 'horizontal', className, style, ref, ...rest
}: PageControlProps) {
  const [surface, props] = splitSurface(rest);
  const [current, setCurrent] = useControllable(controlled, defaultPage, onPageChange);
  const glass = useGlassSurface<HTMLDivElement>({ ...surface, radius: 'pill' }, ref);
  const clamped = Math.min(Math.max(Math.round(current), 0), Math.max(0, count - 1));

  useEffect(() => {
    if (!inDevelopment() || !glass.root.current || count <= LEGIBLE) return;
    warnOnce(glass.root.current, 'page-control-too-many',
      `PageControl has ${count} pages. Past about ${LEGIBLE} the dots stop being countable, so they no longer say where you are — show a "${clamped + 1} / ${count}" label instead.`);
  }, [count, clamped, glass.root]);

  /**
   * Drag along the capsule. The page is whichever dot the finger is over, resolved from the
   * track geometry rather than by hit-testing — the dots are far smaller than a finger, and a
   * drag that only changed page when it happened to be exactly over one would feel broken.
   */
  const latest = useRef({ count, setCurrent }); latest.current = { count, setCurrent };
  useEffect(() => {
    const node = glass.root.current; if (!node) return;
    const pick = (event: PointerEvent) => {
      const { count: total, setCurrent: set } = latest.current;
      if (total < 2) return;
      const box = node.getBoundingClientRect();
      const along = orientation === 'vertical'
        ? (event.clientY - box.top) / box.height
        : getComputedStyle(node).direction === 'rtl'
          ? (box.right - event.clientX) / box.width
          : (event.clientX - box.left) / box.width;
      set(Math.min(total - 1, Math.max(0, Math.round(along * (total - 1)))));
    };
    /* `limit: 0` and no targets: this borrows the gesture plumbing — one primary pointer, a
       frame loop, clean release and cancel — without the deformation. There is nothing here
       to stretch, so Reduce Motion has nothing to turn off. */
    return attachPull(node, () => ({
      limit: 0, stretch: 0,
      axis: orientation === 'vertical' ? 'y' : 'x',
      targets: () => [node],
      onPress: pick,
      onMove: pick,
    }));
  }, [glass.root, orientation]);

  if (count < 1) return null;
  const name = (index: number) => formatPage?.(index, count) ?? `${index + 1} / ${count}`;

  return <div {...props} ref={glass.ref} {...glass.attributes}
    className={cx('lg-root lg-page-control', className)} style={{ ...glass.style, ...style }}
    data-orientation={orientation} role="tablist" aria-label={label} aria-orientation={orientation}>
    {glass.decoration}
    <div className="lg-content">
      {Array.from({ length: count }, (_, index) => <button
        key={index} type="button" role="tab" className="lg-page-dot"
        aria-selected={index === clamped} aria-label={name(index)}
        /* One tab stop for the whole control, as a tab list is: the arrow keys move within it
           and Tab moves past it. */
        tabIndex={index === clamped ? 0 : -1}
        onClick={() => setCurrent(index)}
        onKeyDown={event => {
          const forward = orientation === 'vertical' ? 'ArrowDown' : 'ArrowRight';
          const back = orientation === 'vertical' ? 'ArrowUp' : 'ArrowLeft';
          let next = clamped;
          if (event.key === forward) next = Math.min(count - 1, clamped + 1);
          else if (event.key === back) next = Math.max(0, clamped - 1);
          else if (event.key === 'Home') next = 0;
          else if (event.key === 'End') next = count - 1;
          else return;
          event.preventDefault();
          setCurrent(next);
          // Focus follows selection here: there is nothing to preview, only a position.
          (event.currentTarget.parentElement?.children[next] as HTMLElement | undefined)?.focus();
        }}>
        <span aria-hidden="true" />
      </button>)}
    </div>
  </div>;
}

'use client';
import { type HTMLAttributes, type MouseEvent, type ReactNode, type RefAttributes } from 'react';
import { cx } from '../system/utils.js';
import { useOverflow } from '../system/overflow.js';
import { useGlassStrings } from '../system/strings.js';
import { LibraryIcon } from '../system/icon.js';
import { GlassMenu, type GlassMenuItem } from '../overlays/menu.js';

export interface PathComponent {
  /** Stable identity. Falls back to the label, which is enough for a path. */
  key?: string;
  /** What this level is called. */
  label: string;
  /** A small leading glyph — a disk, a folder, the document itself. */
  icon?: ReactNode;
  /** Where this level goes. Omit on the last one: you are already there. */
  onSelect?: () => void;
  href?: string;
}

export interface PathBarProps extends Omit<HTMLAttributes<HTMLElement>, 'onSelect'>, RefAttributes<HTMLElement> {
  /** Root first, current item last. */
  items: PathComponent[];
  /** Names the trail for assistive technology, e.g. "位置". */
  'aria-label': string;
}

/**
 * Where the thing you are looking at sits, and a way back up.
 *
 * The HIG's path-controls page describes the Finder's path bar, and three of its sentences are
 * the whole design:
 *
 * - **"A linear list that includes the root disk, parent folders, and selected item."** Root
 *   first, current last, and the current one is not a link — it is where you already are. It
 *   carries `aria-current="page"`, which is how a screen reader says the same thing.
 * - **"If the list is too long to fit within the control, it hides names between the first and
 *   last items."** Measured, not a `maxVisible` the caller guesses at — see `useOverflow`. What
 *   is hidden goes into a menu under an ellipsis, so it is still reachable rather than merely
 *   gone. The first and the last never collapse: they are the two levels that say what this is.
 * - **"Use a path control in the window body, not the window frame."** So this is content
 *   layer. It is not glass and it does not belong in a toolbar; the stylesheet gives it a
 *   hairline and nothing else.
 *
 * `<nav>` with an ordered list, because the order is the meaning. The separators are drawn by
 * the stylesheet rather than written into the markup — a chevron between two names is not a
 * word, and a screen reader reading "chevron" between every level is noise.
 */
export function PathBar({ items, 'aria-label': label, className, ref, ...props }: PathBarProps) {
  const strings = useGlassStrings();
  /* Only the middle can collapse, so only the middle is measured. */
  const middle = items.slice(1, Math.max(1, items.length - 1));
  const { containerRef, itemRef, triggerRef, hidden, measuring } = useOverflow(middle.length);
  const collapsed = measuring ? 0 : Math.min(hidden, middle.length);
  /* From the front of the middle outwards: the levels nearest the root are the ones you can
     most afford to lose, because the root above them still says where this is. */
  const folded = middle.slice(0, collapsed);
  const shown = middle.slice(collapsed);

  const menuItems: GlassMenuItem[] = folded.map((item, index) => ({
    key: item.key ?? `${item.label}-${index}`,
    label: item.label,
    icon: item.icon,
    onSelect: () => item.onSelect?.(),
    disabled: !item.onSelect && !item.href,
  }));

  const level = (item: PathComponent, index: number, position: 'root' | 'middle' | 'leaf') => {
    const current = position === 'leaf';
    const content = <>
      {item.icon && <span className="lg-path-icon" aria-hidden="true">{item.icon}</span>}
      <span className="lg-path-label">{item.label}</span>
    </>;
    const press = (event: MouseEvent) => {
      if (!item.onSelect) return;
      /* A path level with both an `href` and a handler is a link the application handles
         itself — the same trade every navigation component here makes. */
      if (!item.href) event.preventDefault();
      item.onSelect();
    };
    return <li key={item.key ?? `${item.label}-${index}`} className="lg-path-item"
      ref={position === 'middle' ? itemRef(index) : undefined}>
      {current || (!item.onSelect && !item.href)
        ? <span className="lg-path-level" aria-current={current ? 'page' : undefined}>{content}</span>
        : <a className="lg-path-level" href={item.href ?? '#'} onClick={press}>{content}</a>}
    </li>;
  };

  return <nav {...props} ref={ref} className={cx('lg-path', className)} aria-label={label}>
    <ol className="lg-path-list" ref={containerRef as (node: HTMLOListElement | null) => void}>
      {items.length > 0 && level(items[0], 0, items.length === 1 ? 'leaf' : 'root')}
      {/* The ref is on the row, not on the button: the row carries the separator chevron in a
          `::before`, and reserving only the button's width would leave that chevron unpaid for. */}
      {collapsed > 0 && <li className="lg-path-item lg-path-folded" ref={triggerRef as (node: HTMLLIElement | null) => void}>
        <GlassMenu aria-label={strings.morePathLevels} items={menuItems} align="start" trigger={
          <button type="button" className="lg-path-level lg-path-more" aria-label={strings.morePathLevels}>
            <LibraryIcon name="ellipsis" size={15} />
          </button>
        } />
      </li>}
      {(measuring ? middle : shown).map((item, index) => level(item, collapsed + index, 'middle'))}
      {items.length > 1 && level(items[items.length - 1], items.length - 1, 'leaf')}
    </ol>
  </nav>;
}

'use client';
import { useEffect, useState, type HTMLAttributes, type RefAttributes, type RefObject } from 'react';
import { useGlassPolicy } from '../system/provider.js';
import { cx } from '../system/utils.js';

export interface ScrollEdgeProps extends Omit<HTMLAttributes<HTMLDivElement>, 'children'>, RefAttributes<HTMLDivElement> {
  /**
   * The scroll container this watches. Not where the ref goes — that is this element.
   *
   * Omit it to watch the page itself, which is the right answer when the document scrolls
   * rather than a box inside it. That case cannot be expressed as a ref: the page's scroll
   * event fires at `document` and never reaches `documentElement`, so it needs its own path.
   */
  targetRef?: RefObject<HTMLElement | null>;
  edge?: 'top' | 'bottom';
  /**
   * `soft` dissolves content progressively as it approaches the bar — the iOS default.
   * `hard` draws a uniform, more opaque boundary, which is what macOS uses for pinned column
   * headers and for controls that have no background of their own.
   */
  variant?: 'soft' | 'hard';
  /** Height of the dissolve in CSS px. Keep it consistent across the columns of a split view. */
  height?: number;
}

/**
 * The scroll edge effect: what replaced opaque bar backgrounds and hairline dividers.
 *
 * It is not decoration and not a colour block — it exists only where content actually passes
 * beneath floating UI, and there is exactly one per scroll view. Use it instead of giving a
 * bar its own background: that is precisely the custom bar treatment the new design removes.
 */
export function ScrollEdge({ targetRef, edge = 'top', variant = 'soft', height = 44, className, style, ref, ...props }: ScrollEdgeProps) {
  const [active, setActive] = useState(false);
  const policy = useGlassPolicy();
  useEffect(() => {
    const page = !targetRef;
    const target = page ? (document.scrollingElement as HTMLElement | null) : targetRef.current;
    if (!target) return;
    // The page's scroll event is dispatched at `document`; an element's, at the element.
    const source: EventTarget = page ? document : target;
    let frame = 0;
    const update = () => {
      cancelAnimationFrame(frame);
      frame = requestAnimationFrame(() => setActive(edge === 'top'
        ? target.scrollTop > 1
        : target.scrollTop + target.clientHeight < target.scrollHeight - 1));
    };
    const observer = new ResizeObserver(update); observer.observe(target);
    if (target.firstElementChild) observer.observe(target.firstElementChild);
    const mutation = new MutationObserver(update); mutation.observe(target, { childList: true, subtree: true, characterData: true });
    source.addEventListener('scroll', update, { passive: true }); update();
    return () => { observer.disconnect(); mutation.disconnect(); source.removeEventListener('scroll', update); cancelAnimationFrame(frame); };
  }, [targetRef, edge]);
  return <div {...props} ref={ref} aria-hidden="true" className={cx('lg-scroll-edge', className)} data-lg-theme={policy.resolvedTheme}
    data-edge={edge} data-variant={variant} data-active={active ? 'true' : 'false'}
    style={{ height: `${height}px`, ...style }} />;
}

'use client';
import { type HTMLAttributes, type ReactNode, type RefAttributes } from 'react';
import { GlassSurface } from '../system/surface.js';
import { type GlassSurfaceOptions } from '../system/material.js';
import { cx } from '../system/utils.js';

export interface SidebarProps extends Omit<HTMLAttributes<HTMLElement>, 'title'>, RefAttributes<HTMLElement>, GlassSurfaceOptions {
  'aria-label': string;
  header?: ReactNode;
  footer?: ReactNode;
  children: ReactNode;
  /** Trailing placement makes this an inspector rather than a navigation sidebar. */
  side?: 'leading' | 'trailing';
}

/**
 * An inset, floating sidebar on large glass. Content scrolls *beneath* it rather than being
 * pushed aside, which is why it needs the thicker, non-flipping large material: a surface
 * this big that flipped light/dark as content passed under it would be unreadable.
 *
 * A capsule radius would make a 260x600 panel a lozenge, so large surfaces take a fixed
 * radius. Anything nested inside should be concentric with it.
 */
export function Sidebar(
  { 'aria-label': label, header, footer, children, side = 'leading', className,
    material, backdropTone, density, renderer, radius, refraction, chroma, ref, ...props }: SidebarProps,
) {
  return <aside {...props} ref={ref} aria-label={label} className={cx('lg-sidebar', className)} data-side={side}>
    <GlassSurface material={material} backdropTone={backdropTone} density={density} renderer={renderer}
      refraction={refraction} chroma={chroma} size="large" radius={radius ?? 26} className="lg-sidebar-surface">
      {header && <div className="lg-sidebar-header">{header}</div>}
      <div className="lg-sidebar-body">{children}</div>
      {footer && <div className="lg-sidebar-footer">{footer}</div>}
    </GlassSurface>
  </aside>;
}

'use client';
import { useEffect, useRef, useState, type HTMLAttributes, type MouseEvent, type ReactNode, type RefAttributes } from 'react';
import { GlassSurface } from '../system/surface.js';
import { type GlassSurfaceOptions } from '../system/material.js';
import { splitSurface } from '../system/props.js';
import { cx } from '../system/utils.js';
import { usePull, elementAt } from '../system/pull.js';
import { useGlassPolicy, useMediaQuery } from '../system/provider.js';
import { useSelectionLens, lensOrigin, trackSpan } from '../controls/segmented.js';
import { GlassBadge } from '../controls/badge.js';

export interface TabBarItem {
  key: string;
  href: string;
  label: ReactNode;
  icon?: ReactNode;
  /** Count shown on the tab. Give the badge an accessible name that says what it counts. */
  badge?: number;
  badgeLabel?: string;
  /** Intercept navigation for a client router or an in-page demo. */
  onSelect?: (event: MouseEvent<HTMLAnchorElement>) => void;
}

/** The ref and any HTML attributes land on the `<nav>`, which is the whole bar. */
export interface TabBarProps extends Omit<HTMLAttributes<HTMLElement>, 'children'>, RefAttributes<HTMLElement>, GlassSurfaceOptions {
  items: TabBarItem[];
  /** `key` of the current section. */
  current?: string;
  /**
   * The search destination. Search gets its own tab at the trailing end, on its own glass
   * background so it reads as separate from the content sections.
   */
  search?: TabBarItem;
  'aria-label': string;
  /** Collapse to a compact pill while the user scrolls down; expands again on the way up. */
  minimizeOnScroll?: boolean;
  /**
   * Width at which the bar becomes a sidebar. The tab bar and the sidebar are one
   * navigational element that scales, not two components to keep in sync.
   */
  sidebarBreakpoint?: number;
  /** Optional heading shown above the items in sidebar form. */
  sidebarHeader?: ReactNode;
  /** Persistent accessory (a now-playing strip, a status line). Never screen-specific actions. */
  accessory?: ReactNode;
}

/**
 * The app's primary navigation: a floating capsule at the bottom on phones, the same element
 * expanded into a sidebar at regular width.
 *
 * It is a `<nav>` of links with `aria-current="page"`, **not** a tablist — these navigate
 * between sections rather than swapping panels in place. Three to five sections is the usable
 * range; anything more belongs in a sidebar. Tabs navigate, so never put actions in here.
 */
export function TabBar({
  items, current, search, 'aria-label': label, minimizeOnScroll = false,
  sidebarBreakpoint = 1024, sidebarHeader, accessory, className, ref, ...rest
}: TabBarProps) {
  const [surface, props] = splitSurface(rest);
  const policy = useGlassPolicy();
  const asSidebar = useMediaQuery(`(min-width: ${sidebarBreakpoint}px)`);
  const [minimized, setMinimized] = useState(false);
  const list = useRef<HTMLDivElement>(null);
  const lensRef = useRef<HTMLSpanElement>(null);
  const activeKey = items.find(item => item.key === current)?.key ?? (search?.key === current ? current : undefined);
  useSelectionLens(list, lensRef, 'a[aria-current="page"]', [activeKey, items.length, asSidebar]);

  /**
   * Sliding the lens changes section as it crosses each one, the same way the segmented control
   * works — a lens you can drag but that decides nothing is worse than no drag at all. Only a
   * move does this: a plain press-and-release is the link's own click.
   */
  const dragged = useRef(false);
  function pick(event: PointerEvent) {
    const hit = elementAt(event, '.lg-tab-link');
    if (!hit || !list.current?.contains(hit) || hit.getAttribute('aria-current') === 'page') return;
    // Lowered around the synthetic click so the guard below only ever swallows the real one.
    dragged.current = false;
    hit.click();
    dragged.current = true;
  }
  usePull(list, {
    axis: asSidebar ? 'y' : 'x', limit: 18, stretch: .8,
    targets: () => lensRef.current ? [lensRef.current] : [],
    origin: () => lensOrigin(lensRef.current),
    range: () => trackSpan(list.current, lensRef.current, asSidebar ? 'y' : 'x'),
    // The highlight is carried only from the item it is on; see `GlassSegmentedControl`.
    grab: event => !!(event.target as HTMLElement).closest('.lg-tab-link[aria-current="page"]'),
    onMove: pick,
  }, !policy.reduceMotion);

  useEffect(() => {
    if (!minimizeOnScroll || asSidebar || policy.reduceMotion) { setMinimized(false); return; }
    let previous = window.scrollY, frame = 0;
    const onScroll = () => {
      cancelAnimationFrame(frame);
      frame = requestAnimationFrame(() => {
        const y = window.scrollY;
        // Only a deliberate scroll counts, so the bar does not flicker on rubber-banding.
        if (Math.abs(y - previous) > 6) { setMinimized(y > previous && y > 64); previous = y; }
      });
    };
    window.addEventListener('scroll', onScroll, { passive: true });
    return () => { window.removeEventListener('scroll', onScroll); cancelAnimationFrame(frame); };
  }, [minimizeOnScroll, asSidebar, policy.reduceMotion]);

  /* draggable={false}: a link that is also a drag target would otherwise start a native drag on
     the first pointer move, which both shows the URL ghost and cancels the gesture. */
  const link = (item: TabBarItem, kind: 'tab' | 'search') => <a key={item.key} className="lg-tab-link" data-kind={kind}
    href={item.href} draggable={false} aria-current={item.key === current ? 'page' : undefined}
    onClick={item.onSelect ? event => item.onSelect!(event) : undefined}>
    {item.icon && <span className="lg-tab-icon" aria-hidden="true">{item.icon}</span>}
    <span className="lg-tab-label">{item.label}</span>
    {item.badge !== undefined && <GlassBadge count={item.badge} aria-label={item.badgeLabel} className="lg-tab-badge" />}
  </a>;

  return <nav {...props} ref={ref} aria-label={label} className={cx('lg-tabbar', className)}
    data-layout={asSidebar ? 'sidebar' : 'tabbar'} data-minimized={minimized ? 'true' : undefined}>
    {asSidebar && sidebarHeader && <div className="lg-tabbar-header">{sidebarHeader}</div>}
    <GlassSurface {...surface} size={asSidebar ? 'large' : 'small'} radius={asSidebar ? 26 : 'pill'} className="lg-tabbar-group">
      {/* The drag already navigated; the click that ends it must not navigate a second time. */}
      <div className="lg-tab-links" ref={list}
        onClickCapture={event => { if (dragged.current) { dragged.current = false; event.preventDefault(); event.stopPropagation(); } }}>
        <span aria-hidden="true" className="lg-selection-lens" ref={lensRef} />
        {items.map(item => link(item, 'tab'))}
      </div>
    </GlassSurface>
    {/* Search sits on its own glass so it reads as a separate destination, not a sixth section. */}
    {search && <GlassSurface {...surface} size={asSidebar ? 'large' : 'small'} radius={asSidebar ? 26 : 'pill'} className="lg-tabbar-group lg-tabbar-search">
      <div className="lg-tab-links">{link(search, 'search')}</div>
    </GlassSurface>}
    {accessory && <div className="lg-tabbar-accessory">{accessory}</div>}
  </nav>;
}

'use client';
import { useId, useRef, type HTMLAttributes, type ReactNode, type RefAttributes } from 'react';
import { GlassSurface } from '../system/surface.js';
import { type GlassSurfaceOptions } from '../system/material.js';
import { splitSurface } from '../system/props.js';
import { cx, useControllable } from '../system/utils.js';
import { usePull, elementAt } from '../system/pull.js';
import { useGlassPolicy } from '../system/provider.js';
import { useSelectionLens, lensOrigin, trackSpan, type GlassChoice } from '../controls/segmented.js';

export interface GlassTab extends GlassChoice { content: ReactNode }
export interface GlassTabsProps extends Omit<HTMLAttributes<HTMLDivElement>, 'children' | 'defaultValue' | 'onChange'>, RefAttributes<HTMLDivElement>, GlassSurfaceOptions {
  items: GlassTab[]; value?: string; defaultValue?: string; onValueChange?: (value: string) => void;
  'aria-label': string;
}

/**
 * In-page tabs that swap content — `role="tablist"` with real panels. This is deliberately
 * not the app's tab bar: navigating between sections of the app is a `<nav>` of links
 * (`TabBar`), because a tablist tells assistive technology the content is swapping in place.
 */
export function GlassTabs({ items, value, defaultValue, onValueChange, 'aria-label': label, className, ref, ...rest }: GlassTabsProps) {
  const [surface, props] = splitSurface(rest);
  const id = useId();
  const [selected, setSelected] = useControllable(value, defaultValue ?? items.find(x => !x.disabled)?.value ?? '', onValueChange);
  const refs = useRef<(HTMLButtonElement | null)[]>([]);
  const list = useRef<HTMLDivElement>(null);
  const policy = useGlassPolicy();
  const lensRef = useRef<HTMLSpanElement>(null);
  useSelectionLens(list, lensRef, '.lg-tab[aria-selected="true"]', [selected, items]);
  usePull(list, {
    axis: 'x', limit: 18, stretch: .8,
    targets: () => lensRef.current ? [lensRef.current] : [],
    origin: () => lensOrigin(lensRef.current),
    range: () => trackSpan(list.current, lensRef.current),
    disabled: event => !!(event.target as HTMLElement).closest('button:disabled'),
    // The indicator is carried only from the tab it is on; see `GlassSegmentedControl`.
    grab: event => !!(event.target as HTMLElement).closest('.lg-tab[aria-selected="true"]'),
    onPress: event => pick(event), onMove: event => pick(event),
    onRelease: ({ event, cancelled }) => { if (!cancelled) (elementAt(event, '.lg-tab') as HTMLButtonElement | null)?.focus({ preventScroll: true }); },
  }, !policy.reduceMotion);
  function pick(event: PointerEvent) {
    const hit = elementAt(event, '.lg-tab') as HTMLButtonElement | null; const index = refs.current.indexOf(hit);
    if (hit && !hit.disabled && index >= 0 && items[index].value !== selected) setSelected(items[index].value);
  }
  return <div {...props} ref={ref} className={cx('lg-tabs', className)}>
    <GlassSurface {...surface} className="lg-tabs-surface" radius="pill">
      <div className="lg-tab-list" role="tablist" aria-label={label} ref={list}>
        <span aria-hidden="true" className="lg-selection-lens" ref={lensRef} />
        {items.map((item, index) => <button key={item.value} ref={node => { refs.current[index] = node; }} type="button" role="tab"
          id={`${id}-tab-${index}`} aria-controls={`${id}-panel-${index}`} aria-selected={selected === item.value}
          tabIndex={selected === item.value ? 0 : -1} disabled={item.disabled} className="lg-tab" onClick={() => setSelected(item.value)}
          onKeyDown={event => {
            const enabled = items.map((x, i) => x.disabled ? -1 : i).filter(i => i >= 0); const current = enabled.indexOf(index);
            let next: number;
            const rtl = getComputedStyle(event.currentTarget).direction === 'rtl';
            if (event.key === (rtl ? 'ArrowLeft' : 'ArrowRight')) next = enabled[(current + 1) % enabled.length];
            else if (event.key === (rtl ? 'ArrowRight' : 'ArrowLeft')) next = enabled[(current - 1 + enabled.length) % enabled.length];
            else if (event.key === 'Home') next = enabled[0];
            else if (event.key === 'End') next = enabled.at(-1)!;
            else return;
            event.preventDefault(); setSelected(items[next].value); refs.current[next]?.focus();
          }}>{item.label}</button>)}
      </div>
    </GlassSurface>
    {/**
      * One cell, all the panels in it.
      *
      * The outgoing panel has to still be displayed to animate out, and two displayed panels
      * in normal flow would stack vertically — the page would grow to twice the height for the
      * length of the swap and then collapse. Stacked in a single grid cell they overlap
      * instead, and the container is as tall as the taller of the two while they cross.
      */}
    <div className="lg-tab-panels">
      {items.map((item, index) => <div key={item.value} role="tabpanel" id={`${id}-panel-${index}`} aria-labelledby={`${id}-tab-${index}`} hidden={selected !== item.value} tabIndex={0} className="lg-tab-panel">{item.content}</div>)}
    </div>
  </div>;
}

'use client';
import { useCallback, useEffect, type HTMLAttributes, type KeyboardEvent, type ReactNode, type RefAttributes } from 'react';
import { useFusion } from '../system/fusion.js';
import { GlassSurface, SharedSurface, type GlassSurfaceProps } from '../system/surface.js';
import { inDevelopment, warnOnce } from '../system/warn.js';
import { cx, useMergedRef } from '../system/utils.js';
import { useOverflow } from '../system/overflow.js';
import { useGlassStrings } from '../system/strings.js';
import { LibraryIcon } from '../system/icon.js';
import { GlassButton, GlassIconButton } from '../controls/button.js';
import { GlassMenu } from '../overlays/menu.js';

export interface GlassToolbarProps extends HTMLAttributes<HTMLDivElement>, RefAttributes<HTMLDivElement> {
  orientation?: 'horizontal' | 'vertical';
  'aria-label': string;
}

/**
 * The toolbar itself carries no background: it is a row of *groups*, and each group is the
 * glass. Removing custom bar backgrounds, borders and darkening overlays is what lets the
 * material and the scroll edge effect do the separating.
 *
 * Roving focus covers the buttons of every group, so the whole bar is one tab stop with
 * arrow-key traversal. Complex input widgets belong outside this primitive.
 */
export function GlassToolbar(
  { className, children, orientation = 'horizontal', onKeyDown, onFocusCapture, ref, ...props }: GlassToolbarProps,
) {
  const [root, merged] = useMergedRef<HTMLDivElement>(ref);
  const items = () => Array.from(root.current?.querySelectorAll<HTMLButtonElement>('button:not(:disabled)') ?? [])
    .filter(b => b.closest('[role="toolbar"]') === root.current && !b.closest('[popover]') && b.getClientRects().length > 0);
  const setTabStop = (target: HTMLElement) => { for (const item of items()) item.tabIndex = item === target ? 0 : -1; };
  useEffect(() => {
    const node = root.current; if (!node) return;
    const reset = () => { const available = items(); const current = available.find(item => item === document.activeElement) ?? available.find(item => item.tabIndex === 0) ?? available[0]; if (current) setTabStop(current); };
    reset();
    const observer = new MutationObserver(reset); observer.observe(node, { childList: true, subtree: true, attributes: true, attributeFilter: ['disabled'] });
    return () => observer.disconnect();
  });
  const keyboard = (event: KeyboardEvent<HTMLDivElement>) => {
    onKeyDown?.(event); if (event.defaultPrevented || event.altKey || event.ctrlKey || event.metaKey) return;
    const available = items(); const index = available.indexOf(document.activeElement as HTMLButtonElement); if (index < 0) return;
    const rtl = getComputedStyle(event.currentTarget).direction === 'rtl';
    const previous = orientation === 'horizontal' ? (rtl ? 'ArrowRight' : 'ArrowLeft') : 'ArrowUp';
    const next = orientation === 'horizontal' ? (rtl ? 'ArrowLeft' : 'ArrowRight') : 'ArrowDown';
    let target = index;
    if (event.key === next) target = (index + 1) % available.length;
    else if (event.key === previous) target = (index - 1 + available.length) % available.length;
    else if (event.key === 'Home') target = 0;
    else if (event.key === 'End') target = available.length - 1;
    else return;
    event.preventDefault(); setTabStop(available[target]); available[target].focus();
  };
  return <div {...props} ref={merged} role="toolbar" aria-orientation={orientation}
    className={cx('lg-toolbar', className)} data-orientation={orientation} onKeyDown={keyboard}
    onFocusCapture={event => { onFocusCapture?.(event); if ((event.target as HTMLElement).tagName === 'BUTTON') setTabStop(event.target as HTMLElement); }}>
    {children}
  </div>;
}

export interface ToolbarItem {
  key: string;
  /** The name of the action. Visible on a text item, the accessible name on an icon one. */
  label: string;
  /** A monochrome symbol. Present means an icon button; absent means a text button. */
  icon?: ReactNode;
  onSelect: () => void;
  disabled?: boolean;
  /** Shown in the overflow menu, where there is room for it. */
  shortcut?: string;
}

export interface ToolbarGroupProps extends GlassSurfaceProps {
  /** Set on the single primary action so it reads as separate from the rest of the bar. */
  prominent?: boolean;
  /**
   * The group's items as data, which is what lets the group collapse the ones that do not fit
   * into a "More" menu at its trailing end.
   *
   * Children can do everything else a group does, and cannot do this: to put a button in a
   * menu the group has to know what that button is *called*, and reading a name back out of an
   * arbitrary child is guesswork that fails silently on the day someone passes an icon with no
   * label. So the overflow lives behind the one shape that carries names.
   */
  items?: ToolbarItem[];
}
/**
 * One shared glass background for a set of related items — group by function and frequency,
 * not by whatever happens to fit. Items inside are `.lg-item`s on the group's material, never
 * glass of their own: glass on glass is the fastest way to lose the material entirely.
 *
 * Do not mix symbols and text in one group; a group of both reads as a single wide button.
 * Text buttons get their own container, and the primary action stands alone.
 */
export function ToolbarGroup(
  { className, children, prominent = false, radius = 'pill', items, ref, ...props }: ToolbarGroupProps,
) {
  const [root, merged] = useMergedRef<HTMLDivElement>(ref);
  const fusion = useFusion(root, { itemSelector: ':scope > .lg-content > .lg-button' });
  const strings = useGlassStrings();
  const { containerRef, itemRef, triggerRef, hidden, measuring } = useOverflow(items?.length ?? 0);
  useEffect(() => {
    if (!inDevelopment()) return;
    const node = root.current; if (!node) return;
    const buttons = Array.from(node.querySelectorAll<HTMLElement>(':scope > .lg-content > .lg-button'));
    if (buttons.length < 2) return;
    const icons = buttons.filter(b => b.classList.contains('lg-icon-button')).length;
    if (icons > 0 && icons < buttons.length) {
      warnOnce(node, 'mixed-group', 'ToolbarGroup mixes icon-only and text buttons in one shared background; a mixed group reads as a single button. Split them into separate groups.');
    }
  }, [root, children]);

  /**
   * The group's own row is what gets measured, and it is `.lg-content` — the element the
   * surface puts its children in. Resolved from the root here rather than exposed as a second
   * ref on `GlassSurface`: one internal element, one place that knows about it.
   */
  const attach = useCallback((node: HTMLDivElement | null) => {
    merged(node);
    containerRef(node?.querySelector<HTMLElement>(':scope > .lg-content') ?? null);
  }, [merged, containerRef]);

  const folded = items && !measuring ? items.slice(items.length - Math.min(hidden, items.length)) : [];
  const shown = items ? items.slice(0, items.length - folded.length) : [];

  return <GlassSurface {...props} ref={items ? attach : merged} radius={radius} data-prominent={prominent ? 'true' : undefined}
    data-overflow={items ? 'true' : undefined}
    className={cx('lg-toolbar-group', className)}>
    <SharedSurface value={true}>
      {fusion}
      {items
        ? <>
          {shown.map((item, index) => (item.icon
            ? <GlassIconButton key={item.key} ref={itemRef(index)} aria-label={item.label}
              disabled={item.disabled} onClick={item.onSelect}>{item.icon}</GlassIconButton>
            : <GlassButton key={item.key} ref={itemRef(index)} disabled={item.disabled}
              onClick={item.onSelect}>{item.label}</GlassButton>))}
          {folded.length > 0 && <GlassMenu
            aria-label={strings.moreToolbarItems}
            items={folded.map(item => ({
              key: item.key, label: item.label, icon: item.icon, shortcut: item.shortcut,
              disabled: item.disabled, onSelect: item.onSelect,
            }))}
            trigger={<GlassIconButton ref={triggerRef} aria-label={strings.moreToolbarItems}>
              <LibraryIcon name="ellipsis" size={18} />
            </GlassIconButton>} />}
        </>
        : children}
    </SharedSurface>
  </GlassSurface>;
}

export interface ToolbarSpacerProps extends Omit<HTMLAttributes<HTMLSpanElement>, 'children'>, RefAttributes<HTMLSpanElement> {
  variant?: 'fixed' | 'flexible';
}
/**
 * Separates groups. `fixed` leaves a consistent gap between two related clusters;
 * `flexible` pushes them to opposite ends of the bar. This replaces the drawn divider —
 * the gap between two glass surfaces is the separator.
 */
export function ToolbarSpacer({ variant = 'fixed', className, ref, ...props }: ToolbarSpacerProps) {
  return <span {...props} ref={ref} className={cx('lg-toolbar-spacer', className)} data-variant={variant} aria-hidden="true" />;
}

'use client';
import { useId, useRef, type HTMLAttributes, type ReactNode, type RefAttributes } from 'react';
import { useGlassSurface, type GlassSurfaceOptions } from '../system/material.js';
import { splitSurface } from '../system/props.js';
import { useSizeClass } from '../system/size-class.js';
import { cx, useControllable } from '../system/utils.js';
import { triggerElement, usePopover, type Align, type OpenProps } from './anchor.js';
import { useGlassStrings } from '../system/strings.js';

export interface ActionSheetItem {
  key: string;
  label: string;
  onSelect?: () => void;
  destructive?: boolean;
  disabled?: boolean;
  icon?: ReactNode;
}
export interface GlassActionSheetProps extends Omit<HTMLAttributes<HTMLDivElement>, 'title' | 'children'>, RefAttributes<HTMLDivElement>, GlassSurfaceOptions, OpenProps {
  /** Optional heading explaining what the choices apply to. */
  title?: string;
  message?: string;
  /** Keep this short — around six choices. A longer list is a menu or a list screen. */
  actions: ActionSheetItem[];
  cancelLabel?: string;
  onCancel?: () => void;
  'aria-label': string;
  align?: Align;
}

/**
 * A short list of choices that springs from the control that triggered it. Destructive
 * choices sit at the bottom of the list in red, and Cancel is separated from the rest so it
 * cannot be hit by accident.
 *
 * The rest of the interface stays interactive: this is a set of options, not a modal task.
 * On a phone it anchors to the bottom of the screen; on wider layouts it stays attached to
 * its source control.
 */
export function GlassActionSheet({
  trigger, open: controlled, defaultOpen = false, onOpenChange, title, message, actions,
  cancelLabel, onCancel, 'aria-label': label, align = 'center', className, style, id: providedId, ref, ...rest
}: GlassActionSheetProps) {
  const [surface, props] = splitSurface(rest);
  const strings = useGlassStrings();
  const generated = useId(); const id = providedId ?? generated; const triggerRef = useRef<HTMLButtonElement>(null);
  const [open, setOpen] = useControllable(controlled, defaultOpen, onOpenChange);
  // The same size class the rest of the library switches on, not a second 768 of its own.
  const wide = useSizeClass() === 'regular';
  const glass = useGlassSurface<HTMLDivElement>({ ...surface, material: 'regular', size: 'large' }, ref);
  usePopover(open, setOpen, glass.root, triggerRef, align, true, wide ? 'auto' : 'above');
  const close = () => { setOpen(false); triggerRef.current?.focus(); };
  // Destructive choices are ordered last so a mis-tap lands on something recoverable.
  const ordered = [...actions].sort((a, b) => Number(!!a.destructive) - Number(!!b.destructive));
  return <>
    {triggerElement(trigger, triggerRef, id, open, 'menu', setOpen)}
    <div {...props} id={id} ref={glass.ref} popover="auto" role="menu" tabIndex={-1} aria-label={label}
      {...glass.attributes} className={cx('lg-root lg-action-sheet', className)} style={{ ...glass.style, ...style }}
      data-anchor={wide ? 'source' : 'bottom'}
      onKeyDown={event => {
        if (event.key === 'Escape') { event.preventDefault(); close(); onCancel?.(); return; }
        if (event.key === 'Tab') { close(); return; }
        const enabled = Array.from(glass.root.current?.querySelectorAll<HTMLButtonElement>('[role="menuitem"]:not(:disabled)') ?? []);
        const index = enabled.indexOf(document.activeElement as HTMLButtonElement); if (!enabled.length) return;
        let next = index;
        if (event.key === 'ArrowDown') next = (index + 1) % enabled.length;
        else if (event.key === 'ArrowUp') next = (index - 1 + enabled.length) % enabled.length;
        else if (event.key === 'Home') next = 0;
        else if (event.key === 'End') next = enabled.length - 1;
        else return;
        event.preventDefault(); enabled[next]?.focus();
      }}>
      {glass.decoration}<div className="lg-content">
        {(title || message) && <div className="lg-sheet-heading" role="none">
          {title && <p className="lg-overlay-title">{title}</p>}
          {message && <p className="lg-overlay-description">{message}</p>}
        </div>}
        <div className="lg-action-list" role="none">
          {ordered.map(action => <button key={action.key} type="button" role="menuitem" tabIndex={-1}
            className="lg-action-item" data-destructive={action.destructive ? 'true' : undefined} disabled={action.disabled}
            onClick={() => { close(); action.onSelect?.(); }}>
            {action.icon && <span className="lg-action-icon" aria-hidden="true">{action.icon}</span>}
            {action.label}
          </button>)}
        </div>
        <button type="button" role="menuitem" tabIndex={-1} className="lg-action-cancel"
          onClick={() => { close(); onCancel?.(); }}>{cancelLabel ?? strings.cancel}</button>
      </div>
    </div>
  </>;
}

'use client';
import { useId, useRef, type DialogHTMLAttributes, type RefAttributes } from 'react';
import { useGlassSurface, type GlassSurfaceOptions } from '../system/material.js';
import { splitSurface } from '../system/props.js';
import { GlassButton } from '../controls/button.js';
import { SharedSurface } from '../system/surface.js';
import { cx, useControllable } from '../system/utils.js';
import { triggerElement, type OpenProps } from './anchor.js';
import { useModalDialog } from './modal.js';

export interface AlertAction {
  key: string;
  /** A verb in title case — "Delete", "Move to Trash". Never "OK" for something destructive. */
  label: string;
  onSelect?: () => void;
  /**
   * `cancel` is the safe way out and takes focus when a destructive action is present;
   * `destructive` renders red; `default` is the ordinary confirming action.
   */
  role?: 'default' | 'cancel' | 'destructive';
}
/** `open` is the controlled state, not the `<dialog>` attribute — the element is opened with `showModal`. */
export interface GlassAlertProps extends Omit<DialogHTMLAttributes<HTMLDialogElement>, 'title' | 'children' | 'open'>, RefAttributes<HTMLDialogElement>, GlassSurfaceOptions, OpenProps {
  title: string;
  /** One or two short sentences saying what happened and what happens next. */
  message?: string;
  actions: AlertAction[];
}

/**
 * A short, unavoidable decision. The title is bold and **left-aligned** — centred alert text
 * is the old design — and there are at most three actions.
 *
 * Reserve alerts for things the user must act on. A destructive action needs either this
 * (with a red action and Cancel focused) or an immediate Undo; routine information needs
 * neither, and marketing never belongs here.
 */
export function GlassAlert({ trigger, open: controlled, defaultOpen = false, onOpenChange, title, message, actions, className, style, id: providedId, ref, ...rest }: GlassAlertProps) {
  const [surface, props] = splitSurface(rest);
  if (actions.length === 0) throw new Error('GlassAlert requires at least one action');
  if (actions.length > 3) throw new RangeError('GlassAlert supports at most three actions; use an action sheet for longer lists');
  const generated = useId(); const id = providedId ?? generated; const triggerRef = useRef<HTMLButtonElement>(null);
  const [open, setOpen] = useControllable(controlled, defaultOpen, onOpenChange);
  const glass = useGlassSurface<HTMLDialogElement>({ ...surface, material: 'regular', size: 'large', radius: surface.radius ?? 26 }, ref);
  const hasDestructive = actions.some(action => action.role === 'destructive');
  useModalDialog(open, glass.root, triggerRef, node => {
    // When something irreversible is on offer, the safe option is the one under the user's hands.
    const preferred = node.querySelector<HTMLButtonElement>(hasDestructive ? '[data-role="cancel"]' : '[data-role="default"]')
      ?? node.querySelector<HTMLButtonElement>('.lg-alert-action');
    preferred?.focus({ preventScroll: true });
  });
  const run = (action: AlertAction) => { setOpen(false); action.onSelect?.(); };
  return <>
    {triggerElement(trigger, triggerRef, id, open, 'dialog', setOpen)}
    <dialog {...props} id={id} ref={glass.ref} role="alertdialog" aria-labelledby={`${id}-title`} aria-describedby={message ? `${id}-msg` : undefined}
      {...glass.attributes} className={cx('lg-root lg-dialog lg-alert', className)} style={{ ...glass.style, ...style }}
      onCancel={event => {
        event.preventDefault();
        // Escape means "get me out", so it runs the cancel action rather than silently closing.
        const cancel = actions.find(action => action.role === 'cancel');
        setOpen(false); cancel?.onSelect?.();
      }}>
      {glass.decoration}<div className="lg-content"><SharedSurface value={true}>
        <h2 id={`${id}-title`} className="lg-overlay-title lg-alert-title">{title}</h2>
        {message && <p id={`${id}-msg`} className="lg-overlay-description lg-alert-message">{message}</p>}
        <div className="lg-alert-actions" data-count={actions.length}>
          {actions.map(action => <GlassButton key={action.key} className="lg-alert-action" data-role={action.role ?? 'default'}
            variant={action.role === 'destructive' ? 'destructive' : action.role === 'cancel' ? 'gray' : 'tinted'}
            independent onClick={() => run(action)}>{action.label}</GlassButton>)}
        </div>
      </SharedSurface></div>
    </dialog>
  </>;
}

'use client';
import { cloneElement, useEffect, useRef, type ButtonHTMLAttributes, type ReactElement, type Ref, type RefObject } from 'react';
import { assignRef, focusable } from '../system/utils.js';

export type TriggerProps = ButtonHTMLAttributes<HTMLButtonElement> & { ref?: Ref<HTMLButtonElement> };
export interface OpenProps {
  open?: boolean;
  defaultOpen?: boolean;
  onOpenChange?: (open: boolean) => void;
  trigger?: ReactElement<TriggerProps>;
}
export type Align = 'start' | 'center' | 'end';

/** Wires the caller's own button up as the opener without taking its props away from it. */
export function triggerElement(
  trigger: ReactElement<TriggerProps> | undefined, ref: Ref<HTMLButtonElement>, id: string,
  open: boolean, kind: 'dialog' | 'menu', setOpen: (value: boolean) => void,
) {
  if (!trigger) return null;
  return cloneElement(trigger, {
    'aria-haspopup': kind, 'aria-expanded': open, 'aria-controls': id,
    ref: node => {
      const originalCleanup = assignRef(trigger.props.ref, node), localCleanup = assignRef(ref, node);
      return () => {
        if (typeof originalCleanup === 'function') originalCleanup(); else assignRef(trigger.props.ref, null);
        if (typeof localCleanup === 'function') localCleanup(); else assignRef(ref, null);
      };
    },
    onClick: event => { trigger.props.onClick?.(event); if (!event.defaultPrevented) setOpen(!open); },
  });
}

/**
 * Native top-layer popover with controlled React state and bounded anchor positioning.
 *
 * The panel grows out of the control that opened it and stays anchored to it — menus,
 * popovers and action sheets morph from their source rather than appearing from nowhere,
 * so the origin is projected onto the panel box every time it is repositioned.
 */
/**
 * The side the panel will land on, without being able to measure it.
 *
 * `26` is the 10px gap plus the 16px the panel keeps from the edge of the window — the same
 * two numbers `position()` uses, so a prediction and the decision cannot drift apart.
 */
function predictPlacement(node: HTMLElement, trigger: Element | null, placement: 'below' | 'above' | 'auto') {
  if (placement !== 'auto') return placement;
  const rect = trigger?.getBoundingClientRect();
  if (!rect) return 'below';
  const room = innerHeight - rect.bottom - 26;
  const height = Number(node.dataset.height) || 0;
  return height ? (room >= height ? 'below' : 'above') : (room >= rect.top ? 'below' : 'above');
}

export function usePopover(
  open: boolean, setOpen: (value: boolean) => void,
  panel: RefObject<HTMLDivElement | null>, trigger: RefObject<HTMLButtonElement | null>,
  align: Align, menu: boolean, placement: 'below' | 'above' | 'auto' = 'auto',
  /**
   * `bottom` pins the panel to the bottom edge of the viewport across the full width instead
   * of anchoring it to the trigger — the compact form, where a 300px panel with an arrow
   * pointing at a control is the wrong shape for the screen.
   */
  anchor: 'source' | 'bottom' = 'source',
) {
  const onChange = useRef(setOpen); onChange.current = setOpen;
  useEffect(() => {
    const node = panel.current; if (!node) return;
    const toggled = (event: Event) => onChange.current((event as Event & { newState: string }).newState === 'open');
    node.addEventListener('toggle', toggled);
    return () => node.removeEventListener('toggle', toggled);
  }, [panel]);
  useEffect(() => {
    const node = panel.current; if (!node) return;
    if (!open) { if (node.matches(':popover-open')) node.hidePopover(); return; }
    if (typeof node.showPopover !== 'function') { onChange.current(false); return; }
    /**
     * Which way it is about to open, decided **before** it is shown.
     *
     * `@starting-style` is read at the moment the panel stops being `display: none`, and
     * `showPopover()` is that moment — so anything written afterwards is too late to be the
     * style it grows from. `position()` runs a few lines below and sets the same attribute
     * correctly, which is why this went unnoticed: the arrow, the shadow and everything else
     * that reads `data-placement` were right, and only the one frame that decides the
     * direction of the entrance was wrong. Measured on the `placement="above"` example: the
     * panel opened 16px above the button and settled at 10, growing away from it.
     *
     * For an explicit placement this is simply the answer. For `auto` it is a prediction, made
     * the same way `position()` makes the decision — against the panel's height from last time
     * if it has been open before, and otherwise against whichever side has more room.
     */
    if (anchor === 'source') node.dataset.placement = predictPlacement(node, trigger.current, placement);
    if (!node.matches(':popover-open')) node.showPopover();
    let frame = 0;
    const position = () => {
      if (anchor === 'bottom') {
        node.style.left = '16px';
        node.style.top = `${Math.max(16, innerHeight - node.offsetHeight - 16)}px`;
        node.style.setProperty('--lg-origin-x', '50%');
        node.style.setProperty('--lg-origin-y', '100%');
        node.removeAttribute('data-placement');
        return;
      }
      const rect = trigger.current?.getBoundingClientRect();
      if (!rect) { node.style.left = `${Math.max(16, (innerWidth - node.offsetWidth) / 2)}px`; node.style.top = '96px'; return; }
      const width = node.offsetWidth, height = node.offsetHeight;
      /**
       * `start` and `end` are leading and trailing, not left and right: in an RTL document the
       * trailing edge is the left one. Resolve against the trigger's own direction rather than
       * the document's, so a single RTL subtree inside an LTR page anchors correctly too.
       */
      const rtl = getComputedStyle(trigger.current!).direction === 'rtl';
      const edge = align === 'center' ? 'center' : (align === 'end') !== rtl ? 'right' : 'left';
      const x = edge === 'right' ? rect.right - width : edge === 'center' ? rect.left + (rect.width - width) / 2 : rect.left;
      const below = rect.bottom + 10, above = rect.top - height - 10;
      const fitsBelow = below + height <= innerHeight - 16;
      const top = placement === 'above' ? Math.max(16, above)
        : placement === 'below' ? below
        : fitsBelow ? below : Math.max(16, above);
      const left = Math.max(16, Math.min(x, innerWidth - width - 16));
      const resolvedTop = Math.min(top, Math.max(16, innerHeight - height - 16));
      node.style.left = `${left}px`;
      node.style.top = `${resolvedTop}px`;
      // Grow out of the trigger: the transform origin is the trigger centre projected onto the panel box.
      const originX = Math.max(0, Math.min(100, (rect.left + rect.width / 2 - left) / width * 100));
      node.style.setProperty('--lg-origin-x', `${originX}%`);
      const landedBelow = resolvedTop >= rect.bottom;
      node.style.setProperty('--lg-origin-y', landedBelow ? '0%' : '100%');
      /* Which side it actually landed on, for anything that has to draw an edge — the arrow
         cannot be derived from `--lg-origin-y` in CSS, and `placement="auto"` means the
         requested side and the resolved side are often not the same. */
      node.dataset.placement = landedBelow ? 'below' : 'above';
      // What it actually measured, so the next open can predict with it rather than guess.
      node.dataset.height = String(Math.round(height));
    };
    const schedule = () => { cancelAnimationFrame(frame); frame = requestAnimationFrame(position); };
    position();
    /**
     * Any of the three menu item roles, not just the plain one: a menu made entirely of
     * checkable items would otherwise open with focus on the panel and no item selected.
     *
     * A single-choice menu opens on the item that is currently chosen, which is what a pop-up
     * button does on every Apple platform — the menu is showing you where you are before it
     * asks where you want to go. Opening on the first item instead means one arrow press does
     * something different depending on what was already selected.
     */
    const first = menu
      ? node.querySelector<HTMLElement>('[role="menuitemradio"][aria-checked="true"]:not(:disabled)')
        ?? node.querySelector<HTMLElement>('[role="menuitem"]:not(:disabled),[role="menuitemcheckbox"]:not(:disabled),[role="menuitemradio"]:not(:disabled)')
      : focusable(node)[0];
    (first ?? node).focus({ preventScroll: true });
    const resize = new ResizeObserver(schedule); resize.observe(node); if (trigger.current) resize.observe(trigger.current);
    window.addEventListener('resize', schedule); window.addEventListener('scroll', schedule, true);
    return () => { resize.disconnect(); cancelAnimationFrame(frame); window.removeEventListener('resize', schedule); window.removeEventListener('scroll', schedule, true); };
  }, [open, panel, trigger, align, menu, placement, anchor]);
}

let scrollLocks = 0; let previousOverflow = '';
/** Reference-counted, so nested modals do not release the page scroll too early. */
export function lockScroll() {
  if (scrollLocks++ === 0) { previousOverflow = document.body.style.overflow; document.body.style.overflow = 'hidden'; }
  return () => { if (--scrollLocks === 0) document.body.style.overflow = previousOverflow; };
}

'use client';
import { useEffect, useRef, type HTMLAttributes, type ReactNode, type RefAttributes } from 'react';
import { GlassButton, GlassIconButton } from '../controls/button.js';
import { useGlassSurface, type GlassSurfaceOptions } from '../system/material.js';
import { splitSurface } from '../system/props.js';
import { SharedSurface } from '../system/surface.js';
import { LibraryIcon, type LibraryIconName } from '../system/icon.js';
import { useGlassStrings } from '../system/strings.js';
import { attachPull } from '../system/pull.js';
import { useGlassPolicy } from '../system/provider.js';
import { useLeave } from '../system/leave.js';
import { cx } from '../system/utils.js';

/**
 * What the banner is reporting. The glyphs match `ToastTone`'s on purpose: the same outcome
 * should not be a tick in one place and something else in another.
 */
export type BannerTone = 'info' | 'success' | 'warning' | 'error';

const TONE_ICON: Record<BannerTone, LibraryIconName | null> = {
  info: null, success: 'checkmark', warning: 'minus', error: 'close',
};

/** Past this far up, the release is a dismissal rather than a fidget. */
const DISMISS_TRAVEL = 44;

export interface BannerProps extends Omit<HTMLAttributes<HTMLDivElement>, 'title'>,
  RefAttributes<HTMLDivElement>, GlassSurfaceOptions {
  /** One line, the thing that happened. */
  title: string;
  /** A second line saying what it means or what to do about it. */
  message?: ReactNode;
  tone?: BannerTone;
  /** A glyph before the text. Defaults to the tone's own; pass `null` for none. */
  icon?: ReactNode | null;
  /** One action, at most. A banner with three buttons is a dialog that forgot to be modal. */
  action?: { label: string; onSelect: () => void };
  /**
   * Called when the reader dismisses it, by the close button or by flicking it upwards.
   * Passing this is what makes the banner dismissible: without it there is no close button,
   * which is right only for a banner the application itself takes down.
   *
   * It arrives **after** the exit has played, not when the button was pressed — the banner has
   * to still be in the tree to animate out of it, and the caller is what takes it out. Under
   * reduced motion there is nothing to play and it arrives immediately. A banner the caller
   * removes for its own reasons simply disappears; nothing here can animate a render that has
   * already happened.
   */
  onDismiss?: () => void;
  /** The close button's name. Defaults to the provider's `close`. */
  dismissLabel?: string;
  /**
   * `inline` — the default — puts it in the flow where you place it, usually at the top of the
   * content or in a `Screen`'s `top` slot. `top` pins it across the top of the window instead.
   *
   * Inline is the default because a component that positions itself cannot be composed: the
   * layout already knows where its top is, and two things that both believe they own the top
   * of the window end up on top of each other.
   */
  placement?: 'inline' | 'top';
}

/**
 * A short notice at the top of a view: something arrived, something failed, something is
 * available.
 *
 * Not a toast, and the difference is what it is for. A toast reports the result of something
 * the reader just did and leaves on its own; a banner reports something that happened
 * elsewhere, stays until it is dealt with, and therefore has a title, room for a sentence, and
 * a way to get rid of it. If the reader must answer before going on, neither is right — that
 * is an alert.
 *
 * Control layer: it floats over the content it is about, so it is glass, and large glass
 * because it is a panel rather than a control.
 */
export function Banner({
  title, message, tone = 'info', icon, action, onDismiss, dismissLabel,
  placement = 'inline', className, style, ref, ...rest
}: BannerProps) {
  const strings = useGlassStrings();
  const [surface, props] = splitSurface(rest);
  const glass = useGlassSurface<HTMLDivElement>({ material: 'regular', size: 'large', ...surface }, ref);
  const reduceMotion = useGlassPolicy().reduceMotion;

  /**
   * Flick it up to get rid of it, which is how the system's own notifications go away.
   *
   * It is an addition to the close button, never a replacement: a gesture with no visible
   * affordance is not a way to dismiss something for anyone using a keyboard, and the same
   * applies to anyone who has not been told the gesture exists.
   */
  const latest = useRef(onDismiss); latest.current = onDismiss;
  const { leaving, close } = useLeave(reduceMotion, () => latest.current?.());
  const closeRef = useRef(close); closeRef.current = close;
  useEffect(() => {
    const node = glass.root.current;
    if (!node || !onDismiss) return;
    return attachPull(node, () => ({
      axis: 'y', limit: 20, stretch: reduceMotion ? 0 : .3,
      targets: () => [node],
      // Downwards is nothing: it has nowhere to go and an elastic sag is not an affordance.
      range: () => ({ y: [-9999, 0] }),
      onRelease: ({ dy, cancelled }) => { if (!cancelled && dy < -DISMISS_TRAVEL) closeRef.current(); },
    }));
  }, [glass.root, onDismiss, reduceMotion]);

  const glyph = icon === null ? null
    : icon ?? (TONE_ICON[tone] && <LibraryIcon name={TONE_ICON[tone]!} size={17} />);

  return <div {...props} ref={glass.ref} {...glass.attributes}
    className={cx('lg-root lg-banner', className)} style={{ ...glass.style, ...style }}
    data-tone={tone} data-placement={placement} data-leaving={leaving ? 'true' : undefined}
    /* Polite: a banner reports, it does not interrupt. Something that must be answered before
       the reader goes on is an alert, and saying so here would not make this one. */
    role="status" aria-live="polite">
    {glass.decoration}
    <div className="lg-content"><SharedSurface value={true}>
      {glyph && <span className="lg-banner-icon" aria-hidden="true">{glyph}</span>}
      <div className="lg-banner-text">
        <span className="lg-banner-title">{title}</span>
        {message && <span className="lg-banner-message">{message}</span>}
      </div>
      {action && <GlassButton className="lg-banner-action" controlSize="small"
        onClick={action.onSelect}>{action.label}</GlassButton>}
      {onDismiss && <GlassIconButton className="lg-banner-dismiss" variant="plain" controlSize="small"
        aria-label={dismissLabel ?? strings.close} onClick={close}>
        <LibraryIcon name="close" size={15} />
      </GlassIconButton>}
    </SharedSurface></div>
  </div>;
}

'use client';
import {
  useEffect, useId, useMemo, useRef, useState,
  type DialogHTMLAttributes, type ReactNode, type RefAttributes,
} from 'react';
import { Kbd } from '../content/kbd.js';
import { LibraryIcon } from '../system/icon.js';
import { useGlassSurface, type GlassSurfaceOptions } from '../system/material.js';
import { splitSurface } from '../system/props.js';
import { useShortcut } from '../system/shortcut.js';
import { useGlassStrings } from '../system/strings.js';
import { SharedSurface } from '../system/surface.js';
import { cx, useControllable } from '../system/utils.js';
import { triggerElement, type OpenProps } from './anchor.js';
import { useModalDialog } from './modal.js';

export interface PaletteCommand {
  id: string;
  /** What it does, as a command: a verb. "Export as PDF", not "PDF export". */
  label: string;
  /** Section heading. Commands keep the order they were given in, inside their section. */
  group?: string;
  /** A second line — where this lives, or what it will do. */
  detail?: string;
  icon?: ReactNode;
  /** Written the way `Kbd` writes one: `"mod k"`, `"⇧⌘P"`. Drawn on the trailing edge. */
  shortcut?: string;
  /** Words this should match on without showing them — synonyms, an old name. */
  keywords?: string;
  /** Shown but not runnable. A command that does not apply right now still belongs in the list. */
  disabled?: boolean;
  onSelect: () => void;
}

export interface CommandPaletteProps extends Omit<DialogHTMLAttributes<HTMLDialogElement>, 'title' | 'children' | 'open'>, RefAttributes<HTMLDialogElement>, GlassSurfaceOptions, OpenProps {
  commands: PaletteCommand[];
  /**
   * What this palette searches. Announced rather than drawn — the field says what to type, and
   * a title bar above a search field is the one thing Spotlight has never had.
   */
  title: string;
  placeholder?: string;
  /**
   * The keys that open it, resolved exactly as `Kbd` draws them. `null` binds nothing, for an
   * application that opens the palette its own way.
   */
  shortcut?: string | null;
  query?: string;
  defaultQuery?: string;
  onQueryChange?: (query: string) => void;
  /**
   * How a command is matched. `false` means the list already is the answer — the caller
   * filtered, ranked, or asked a server, and this should draw what it was handed.
   *
   * The default filter exists here and deliberately not in `SearchField`, and the difference is
   * not taste: a search field's results can be anywhere and only the application knows what
   * matching means for them, while a palette is handed every command it will ever show. Nothing
   * is hidden from a function that already has the whole list.
   */
  filter?: ((command: PaletteCommand, query: string) => boolean) | false;
  /** Shown when nothing matches. Say what would match instead of apologising. */
  emptyLabel?: ReactNode;
  /** How many matches to draw. The rest are still searchable; they are just not all on screen. */
  limit?: number;
}

/** Every word of the query has to turn up somewhere in the command. Case and order do not matter. */
const defaultFilter = (command: PaletteCommand, query: string) => {
  const haystack = `${command.label} ${command.group ?? ''} ${command.detail ?? ''} ${command.keywords ?? ''}`.toLocaleLowerCase();
  return query.toLocaleLowerCase().split(/\s+/).filter(Boolean).every(word => haystack.includes(word));
};

/**
 * One field, one list, one keystroke to get there: the way a desktop application is driven
 * once somebody knows it.
 *
 * The accessibility model is a combobox over a listbox with **virtual focus** — real focus
 * never leaves the field, and the highlighted row is named by `aria-activedescendant`. Moving
 * focus into the list instead is the usual mistake, and it breaks the one thing a palette is
 * for: the next keystroke has to keep filtering.
 *
 * It keeps nothing. No history, no recently-used ordering, nothing written anywhere — a list
 * of what somebody has been doing is not something to put on screen by default, and an
 * application that wants it can order `commands` itself and offer a way to clear it.
 */
export function CommandPalette({
  commands, title, placeholder, shortcut = 'mod k',
  query: controlledQuery, defaultQuery = '', onQueryChange,
  filter = defaultFilter, emptyLabel, limit = 50,
  trigger, open: controlledOpen, defaultOpen = false, onOpenChange,
  className, style, id: providedId, ref, ...rest
}: CommandPaletteProps) {
  const [surface, props] = splitSurface(rest);
  const strings = useGlassStrings();
  const generated = useId(); const id = providedId ?? generated;
  const triggerRef = useRef<HTMLButtonElement>(null);
  const inputRef = useRef<HTMLInputElement>(null);
  const [open, setOpen] = useControllable(controlledOpen, defaultOpen, onOpenChange);
  const [query, setQuery] = useControllable(controlledQuery, defaultQuery, onQueryChange);
  const glass = useGlassSurface<HTMLDialogElement>({ ...surface, material: 'regular', size: 'large', radius: surface.radius ?? 22 }, ref);

  useModalDialog(open, glass.root, triggerRef, () => inputRef.current?.focus({ preventScroll: true }));

  /**
   * Two bindings, not one toggle, because they are two different shortcuts.
   *
   * The one that opens it is the application's and must not fire while a modal is up — that is
   * `useShortcut`'s rule and it is the right one. The one that closes it is scoped to this
   * dialog, which is exactly what makes it the exception: the same keys, asked for from inside
   * the thing they opened.
   */
  useShortcut(shortcut, () => setOpen(true), { enabled: !open });
  useShortcut(shortcut, () => setOpen(false), { enabled: open, scope: glass.root });

  const matches = useMemo(() => {
    const matching = filter === false || query.trim() === ''
      ? commands
      : commands.filter(command => filter(command, query));
    return matching.slice(0, limit);
  }, [commands, query, filter, limit]);

  const [active, setActive] = useState(0);
  /**
   * The highlight is reset by what the list *contains*, not by the array's identity: `commands`
   * is nearly always built inline and is therefore a new array every render, and keying on
   * identity would clear the highlight one render after every arrow press.
   */
  const listKey = matches.map(command => command.id).join(' ');
  useEffect(() => { setActive(matches.findIndex(command => !command.disabled)); }, [listKey]); // eslint-disable-line react-hooks/exhaustive-deps
  useEffect(() => { if (!open) { setQuery(''); } }, [open]); // eslint-disable-line react-hooks/exhaustive-deps

  const listId = `${id}-list`;
  const optionId = (index: number) => `${listId}-${index}`;

  /** The next runnable row in a direction, wrapping. A disabled command is drawn, never landed on. */
  const step = (from: number, delta: number) => {
    if (!matches.length) return -1;
    for (let hop = 1; hop <= matches.length; hop++) {
      const index = (from + delta * hop + matches.length * hop) % matches.length;
      if (!matches[index].disabled) return index;
    }
    return -1;
  };

  const run = (index: number) => {
    const command = matches[index];
    if (!command || command.disabled) return;
    // Closed first, so focus is back where it came from before the command does anything with it.
    setOpen(false);
    command.onSelect();
  };

  const onKeyDown = (event: React.KeyboardEvent<HTMLInputElement>) => {
    if (event.key === 'ArrowDown') { event.preventDefault(); setActive(current => step(current, 1)); }
    else if (event.key === 'ArrowUp') { event.preventDefault(); setActive(current => step(current, -1)); }
    else if (event.key === 'Home') { event.preventDefault(); setActive(step(-1, 1)); }
    else if (event.key === 'End') { event.preventDefault(); setActive(step(0, -1)); }
    else if (event.key === 'Enter') { event.preventDefault(); run(active); }
    /* Escape is left alone: it reaches the dialog, which cancels, which closes — the platform's
       own way out rather than a second one that has to be kept in step with it. */
  };

  /** Keep the highlighted row on screen without moving focus or the page. */
  useEffect(() => {
    if (!open || active < 0) return;
    glass.root.current?.querySelector(`#${CSS.escape(optionId(active))}`)?.scrollIntoView({ block: 'nearest' });
  }, [active, open, listKey]); // eslint-disable-line react-hooks/exhaustive-deps

  /* Section headings, in the order the sections first appear. A command with no group comes
     first and without a heading — it is not "Other", it is simply the list. */
  const sections: { name?: string; entries: { command: PaletteCommand; index: number }[] }[] = [];
  matches.forEach((command, index) => {
    const last = sections[sections.length - 1];
    if (last && last.name === command.group) last.entries.push({ command, index });
    else sections.push({ name: command.group, entries: [{ command, index }] });
  });

  return <>
    {triggerElement(trigger, triggerRef, id, open, 'dialog', setOpen)}
    <dialog {...props} id={id} ref={glass.ref} aria-labelledby={`${id}-title`} {...glass.attributes}
      className={cx('lg-root lg-dialog lg-palette', className)} style={{ ...glass.style, ...style }}
      onCancel={event => { event.preventDefault(); setOpen(false); }}
      onClose={() => { if (!glass.root.current?.open) setOpen(false); }}
      /* A press on the dimmed area closes. Measured rather than inferred from the target: the
         dialog's own padding is also the dialog, and closing on a press there would mean the
         panel dismissed itself when somebody missed the field by four pixels. */
      onPointerDown={event => {
        if (event.target !== event.currentTarget) return;
        const rect = glass.root.current?.getBoundingClientRect(); if (!rect) return;
        if (event.clientX < rect.left || event.clientX > rect.right
          || event.clientY < rect.top || event.clientY > rect.bottom) setOpen(false);
      }}>
      {glass.decoration}<div className="lg-content"><SharedSurface value={true}>
        <h2 id={`${id}-title`} className="lg-visually-hidden">{title}</h2>
        <div className="lg-palette-field">
          <LibraryIcon name="search" size={18} className="lg-palette-icon" />
          <input ref={inputRef} type="text" className="lg-palette-input"
            role="combobox" aria-expanded={matches.length > 0} aria-controls={listId}
            aria-autocomplete="list" aria-label={title}
            aria-activedescendant={active >= 0 && matches.length ? optionId(active) : undefined}
            autoComplete="off" spellCheck={false}
            placeholder={placeholder ?? strings.searchCommands}
            value={query} onChange={event => setQuery(event.currentTarget.value)} onKeyDown={onKeyDown} />
        </div>
        <div id={listId} role="listbox" aria-label={title} className="lg-palette-list">
          {sections.map((section, sectionIndex) => {
            const headingId = `${listId}-section-${sectionIndex}`;
            const rows = section.entries.map(({ command, index }) => <div key={command.id}
              id={optionId(index)} role="option" className="lg-palette-option"
              aria-selected={index === active} aria-disabled={command.disabled || undefined}
              /* `pointerdown` with its default prevented, rather than `click`: the press is
                 what takes focus off the field, and a row is not focusable, so focus lands on
                 nothing at all. Most visible on the press that runs nothing — a disabled row
                 leaves the palette open, and typing would have stopped working. */
              onPointerDown={event => { event.preventDefault(); run(index); }}
              onPointerMove={() => { if (!command.disabled && index !== active) setActive(index); }}>
              {command.icon && <span className="lg-palette-option-icon" aria-hidden="true">{command.icon}</span>}
              <span className="lg-palette-option-text">
                <span className="lg-palette-option-label">{command.label}</span>
                {command.detail && <span className="lg-palette-option-detail">{command.detail}</span>}
              </span>
              {command.shortcut && <Kbd className="lg-palette-option-shortcut" keys={command.shortcut} aria-hidden="true" />}
            </div>);
            return section.name
              ? <div key={headingId} role="group" aria-labelledby={headingId}>
                <div id={headingId} role="presentation" className="lg-palette-section">{section.name}</div>
                {rows}
              </div>
              : <div key={headingId} role="presentation">{rows}</div>;
          })}
        </div>
        {matches.length === 0 && <p className="lg-palette-empty" role="status">{emptyLabel ?? strings.noResults}</p>}
      </SharedSurface></div>
    </dialog>
  </>;
}

'use client';
import { useEffect, useId, useRef, useState, type HTMLAttributes, type ReactNode, type RefAttributes } from 'react';
import { useGlassSurface, type GlassSurfaceOptions } from '../system/material.js';
import { splitSurface } from '../system/props.js';
import { Kbd } from '../content/kbd.js';
import { cx } from '../system/utils.js';
import { inDevelopment, warnOnce } from '../system/warn.js';
import { menuKeyboard, type GlassMenuItem } from './menu.js';

export interface ContextMenuProps extends Omit<HTMLAttributes<HTMLDivElement>, 'children'>,
  RefAttributes<HTMLDivElement>, GlassSurfaceOptions {
  /**
   * The commands. Keep it short: a context menu is what is most likely wanted *here*, not a
   * catalogue of everything possible.
   */
  items: GlassMenuItem[];
  /** What the menu is for, e.g. "照片操作". */
  'aria-label': string;
  /**
   * What it is a menu *on*. Wrapped rather than cloned, because the region has to be a real
   * box: the keyboard route has no pointer position and opens at the region's centre instead.
   */
  children: ReactNode;
  /** Milliseconds of touch before it opens. */
  longPressDelay?: number;
}

/** How far a finger may wander during a long press before it is a scroll instead. */
const SLOP = 10;

/**
 * A menu on the thing itself: right-click, long-press, or the keyboard's own menu key.
 *
 * The rule that matters most is the one that is not about the menu at all: **everything in it
 * has to be reachable some other way.** A context menu is a shortcut for people who know it
 * is there, and a command that lives only inside one is a command most people will never find.
 * Development mode cannot check that, so it is said here instead.
 *
 * Three triggers, because there are three kinds of user:
 *
 * - `contextmenu` — right-click, and also what a trackpad two-finger tap produces.
 * - A long press, for touch. Cancelled by movement, because a finger that moves was scrolling,
 *   and a menu that opens mid-scroll is a menu that appears when nobody asked.
 * - **Shift+F10 and the Menu key**, which is how the platform's own context menus are opened
 *   from a keyboard. Without them the whole feature is pointer-only.
 */
export function ContextMenu({
  items, 'aria-label': label, children, longPressDelay = 500, className, style, id: providedId, ref, ...rest
}: ContextMenuProps) {
  const [surface, props] = splitSurface(rest);
  const generated = useId(); const id = providedId ?? generated;
  const region = useRef<HTMLDivElement>(null);
  const glass = useGlassSurface<HTMLDivElement>({ ...surface, material: 'regular', size: 'large' });
  const [open, setOpen] = useState(false);
  const [at, setAt] = useState<{ x: number; y: number } | null>(null);
  const restore = useRef<HTMLElement | null>(null);

  useEffect(() => {
    if (!inDevelopment() || !region.current || items.length <= 12) return;
    warnOnce(region.current, 'context-menu-long',
      `ContextMenu has ${items.length} commands. A context menu is what is most likely wanted here, not everything that is possible — past about a dozen it is a list to read rather than a shortcut.`);
  }, [items.length]);

  /**
   * Open at a point, or — for the keyboard, which has no pointer — at the region's centre.
   *
   * Stored in **document** coordinates. A menu pinned to a viewport position drifts off the
   * thing it belongs to the moment anything scrolls, and something always does: right-clicking
   * moves focus, and moving focus scrolls.
   */
  const show = (point: { x: number; y: number } | null) => {
    restore.current = document.activeElement as HTMLElement | null;
    const box = region.current?.getBoundingClientRect();
    const client = point ?? (box
      ? { x: box.left + box.width / 2, y: box.top + box.height / 2 }
      : { x: 0, y: 0 });
    setAt({ x: client.x + scrollX, y: client.y + scrollY });
    setOpen(true);
  };
  const close = (returnFocus = true) => {
    setOpen(false);
    if (returnFocus && restore.current?.isConnected) restore.current.focus({ preventScroll: true });
  };

  /* Touch. `pointerdown` on the region, cancelled by movement or by the finger lifting early. */
  useEffect(() => {
    const node = region.current; if (!node) return;
    let timer: ReturnType<typeof setTimeout> | null = null;
    let start = { x: 0, y: 0 };
    const cancel = () => { if (timer) { clearTimeout(timer); timer = null; } };
    const down = (event: PointerEvent) => {
      if (event.pointerType !== 'touch' || !event.isPrimary) return;
      start = { x: event.clientX, y: event.clientY };
      cancel();
      timer = setTimeout(() => { timer = null; show(start); }, longPressDelay);
    };
    const move = (event: PointerEvent) => {
      if (!timer) return;
      if (Math.abs(event.clientX - start.x) > SLOP || Math.abs(event.clientY - start.y) > SLOP) cancel();
    };
    node.addEventListener('pointerdown', down);
    window.addEventListener('pointermove', move, { passive: true });
    window.addEventListener('pointerup', cancel);
    window.addEventListener('pointercancel', cancel);
    return () => {
      cancel();
      node.removeEventListener('pointerdown', down);
      window.removeEventListener('pointermove', move);
      window.removeEventListener('pointerup', cancel);
      window.removeEventListener('pointercancel', cancel);
    };
    // eslint-disable-next-line react-hooks/exhaustive-deps
  }, [longPressDelay]);

  /** Place it at the pointer, kept inside the window. */
  useEffect(() => {
    const panel = glass.root.current;
    const anchor = at;
    if (!open || !panel || !anchor) return;
    if (typeof panel.showPopover !== 'function') { setOpen(false); return; }
    if (!panel.matches(':popover-open')) panel.showPopover();
    const place = () => {
      // Back to viewport coordinates, wherever the page has scrolled to since.
      const at = { x: anchor.x - scrollX, y: anchor.y - scrollY };
      const width = panel.offsetWidth, height = panel.offsetHeight;
      /* Opens down-and-trailing from the pointer, the way a system context menu does, and
         flips rather than overflows when there is no room that way. */
      const rtl = getComputedStyle(panel).direction === 'rtl';
      const preferred = rtl ? at.x - width : at.x;
      const left = Math.max(8, Math.min(preferred, innerWidth - width - 8));
      const top = at.y + height + 8 <= innerHeight ? at.y : Math.max(8, at.y - height);
      panel.style.left = `${left}px`;
      panel.style.top = `${top}px`;
      panel.style.setProperty('--lg-origin-x', `${Math.max(0, Math.min(100, (at.x - left) / width * 100))}%`);
      panel.style.setProperty('--lg-origin-y', top >= at.y ? '0%' : '100%');
    };
    place();
    panel.querySelector<HTMLElement>('[role="menuitem"]:not(:disabled),[role="menuitemcheckbox"]:not(:disabled)')?.focus({ preventScroll: true });

    /**
     * Dismissal is ours, which is why the popover is `manual`.
     *
     * An `auto` popover light-dismisses on the pointer event that follows the one which opened
     * it — and a right-click is pointerdown → contextmenu → **pointerup**, so the menu closed
     * itself on the way up. Deferring the open by a frame appeared to fix that and did not:
     * the frame and the pointerup race, and it worked at one window height and failed at
     * another. A race that resolves differently by viewport is not a fix.
     *
     * The rule is stated instead: a press that starts outside the panel closes it, and the
     * press that opened it has already finished by the time this listener exists.
     */
    const outside = (event: PointerEvent) => {
      if (!panel.contains(event.target as Node)) close(false);
    };
    /* Scrolling moves the menu with the content rather than closing it. Closing on any scroll
       was the other half of the same bug: right-clicking moves focus, moving focus scrolls,
       and the menu dismissed itself on a scroll it had caused. */
    const follow = () => { frame ||= requestAnimationFrame(() => { frame = 0; place(); }); };
    let frame = 0;
    window.addEventListener('pointerdown', outside, true);
    window.addEventListener('resize', follow);
    window.addEventListener('scroll', follow, true);
    return () => {
      if (frame) cancelAnimationFrame(frame);
      window.removeEventListener('pointerdown', outside, true);
      window.removeEventListener('resize', follow);
      window.removeEventListener('scroll', follow, true);
      if (panel.matches(':popover-open')) panel.hidePopover();
    };
    // eslint-disable-next-line react-hooks/exhaustive-deps
  }, [open, at, glass.root]);

  return <>
    <div
      {...props}
      ref={node => {
        region.current = node;
        if (typeof ref === 'function') ref(node); else if (ref) ref.current = node;
      }}
      className={cx('lg-context-region', className)}
      style={style}
      /* No `aria-haspopup` here: on a wrapper with no role it is announced by nothing. It
         belongs on the caller's own control, where there is a role to qualify — and the
         keyboard route works regardless, because the key event bubbles from whatever inside
         has focus. */
      onContextMenu={event => { event.preventDefault(); show({ x: event.clientX, y: event.clientY }); }}
      onKeyDown={event => {
        // The platform's own keyboard route into a context menu, and the only one there is.
        if (event.key === 'ContextMenu' || (event.key === 'F10' && event.shiftKey)) {
          event.preventDefault();
          show(null);
        }
      }}>
      {children}
    </div>

    <div id={id} ref={glass.ref} popover="manual" role="menu" tabIndex={-1} aria-label={label}
      {...glass.attributes} className="lg-root lg-menu lg-context-menu" style={glass.style}
      onToggle={event => { if ((event as unknown as { newState: string }).newState === 'closed') setOpen(false); }}
      onKeyDown={event => menuKeyboard(event, glass.root.current, close)}>
      {glass.decoration}<div className="lg-content">
        {items.map(item => <div key={item.key} role="none">
          {item.separatorBefore && <div role="separator" className="lg-menu-separator" />}
          <button type="button" role={item.checked === undefined ? 'menuitem' : 'menuitemcheckbox'}
            aria-checked={item.checked} tabIndex={-1} className="lg-menu-item" data-label={item.label}
              aria-keyshortcuts={item.shortcut}
            data-destructive={item.destructive ? 'true' : 'false'} disabled={item.disabled}
            onClick={() => { close(); item.onSelect(); }}>
            {item.icon && <span className="lg-menu-icon" aria-hidden="true">{item.icon}</span>}
            <span className="lg-menu-label">{item.label}</span>
            {item.shortcut && <Kbd className="lg-menu-shortcut" keys={item.shortcut} aria-hidden="true" />}
          </button>
        </div>)}
      </div>
    </div>
  </>;
}

'use client';
import { useCallback, useId, useRef, type DialogHTMLAttributes, type ReactNode, type RefAttributes } from 'react';
import { useGlassSurface, type GlassSurfaceOptions } from '../system/material.js';
import { splitSurface } from '../system/props.js';
import { GlassIconButton } from '../controls/button.js';
import { SharedSurface } from '../system/surface.js';
import { LibraryIcon } from '../system/icon.js';
import { cx, useControllable } from '../system/utils.js';
import { triggerElement, type OpenProps } from './anchor.js';
import { useModalDialog } from './modal.js';
import { useGlassStrings } from '../system/strings.js';

/** `open` is the controlled state, not the `<dialog>` attribute — the element is opened with `showModal`. */
export interface GlassDialogProps extends Omit<DialogHTMLAttributes<HTMLDialogElement>, 'title' | 'children' | 'open'>, RefAttributes<HTMLDialogElement>, GlassSurfaceOptions, OpenProps {
  title: string; description: string; children: ReactNode;
  closeLabel?: string; dismissOnBackdrop?: boolean;
}

/**
 * A modal task on large glass, built on the native `<dialog>` so focus containment, the
 * top layer and Escape come from the platform rather than from a hand-rolled focus trap.
 *
 * Titles are bold and left-aligned, and the task is paired with a dimming layer because it
 * interrupts the main flow — parallel tasks get glass separation without the dim.
 */
export function GlassDialog({ trigger, open: controlled, defaultOpen = false, onOpenChange, title, description, children, className, style, closeLabel, dismissOnBackdrop = true, id: providedId, ref, ...rest }: GlassDialogProps) {
  const [surface, props] = splitSurface(rest);
  const strings = useGlassStrings();
  const generated = useId(); const id = providedId ?? generated; const triggerRef = useRef<HTMLButtonElement>(null);
  const downOutside = useRef(false);
  const [open, setOpen] = useControllable(controlled, defaultOpen, onOpenChange);
  const glass = useGlassSurface<HTMLDialogElement>({ ...surface, material: 'regular', size: 'large', radius: surface.radius ?? 28 }, ref);
  useModalDialog(open, glass.root, triggerRef);
  const outside = useCallback((x: number, y: number) => {
    const rect = glass.root.current?.getBoundingClientRect();
    return !!rect && (x < rect.left || x > rect.right || y < rect.top || y > rect.bottom);
  }, [glass.root]);
  return <>
    {triggerElement(trigger, triggerRef, id, open, 'dialog', setOpen)}
    <dialog {...props} id={id} ref={glass.ref} aria-labelledby={`${id}-title`} aria-describedby={`${id}-desc`} {...glass.attributes} className={cx('lg-root lg-dialog', className)} style={{ ...glass.style, ...style }}
      onCancel={event => { event.preventDefault(); setOpen(false); }} onClose={() => { if (!glass.root.current?.open) setOpen(false); }}
      onPointerDown={event => { downOutside.current = event.target === event.currentTarget && outside(event.clientX, event.clientY); }}
      onClick={event => { if (dismissOnBackdrop && downOutside.current && event.target === event.currentTarget && outside(event.clientX, event.clientY)) setOpen(false); downOutside.current = false; }}>
      {glass.decoration}<div className="lg-content"><SharedSurface value={true}>
        <h2 id={`${id}-title`} className="lg-overlay-title">{title}</h2>
        <p id={`${id}-desc`} className="lg-overlay-description">{description}</p>
        <div className="lg-dialog-body">{children}</div>
        <GlassIconButton className="lg-dialog-close" aria-label={closeLabel ?? strings.close} variant="plain" onClick={() => setOpen(false)}>
          <LibraryIcon name="close" size={18} />
        </GlassIconButton>
      </SharedSurface></div>
    </dialog>
  </>;
}

'use client';
import { useEffect, useRef, type ButtonHTMLAttributes, type ReactNode, type RefAttributes } from 'react';
import { GlassButton, type ControlSize, type GlassButtonVariant } from '../controls/button.js';
import { LibraryIcon } from '../system/icon.js';
import { type GlassSurfaceOptions } from '../system/material.js';
import { useControllable } from '../system/utils.js';
import { inDevelopment, warnOnce } from '../system/warn.js';
import { GlassMenu, type GlassMenuItem } from './menu.js';
import { type Align } from './anchor.js';

/**
 * One choice in a pop-up button. Deliberately not a `GlassMenuItem`: a pop-up button's items
 * are values, not commands, so they have no `onSelect` of their own — the button reports the
 * new value once, in one place.
 */
export interface GlassMenuOption {
  value: string;
  label: string;
  icon?: ReactNode;
  disabled?: boolean;
  separatorBefore?: boolean;
}

/**
 * `value` and `type` are taken back from `<button>`: a pop-up button's `value` is the choice
 * it is showing, and its element is always `type="button"` — a menu opener that submitted a
 * form would be a trap. Everything else passes through to the button, which is the element on
 * the page and the one the `ref` points at.
 */
interface CommonProps extends Omit<ButtonHTMLAttributes<HTMLButtonElement>, 'value' | 'type' | 'children'>,
  RefAttributes<HTMLButtonElement>, GlassSurfaceOptions {
  variant?: GlassButtonVariant;
  controlSize?: ControlSize;
  align?: Align;
  placement?: 'below' | 'above' | 'auto';
}

export interface PullDownButtonProps extends CommonProps {
  kind?: 'pullDown';
  /** What the button says. Stays put — a pull-down button's label describes its own action. */
  label: ReactNode;
  items: GlassMenuItem[];
  'aria-label'?: string;
}

export interface PopUpButtonProps extends CommonProps {
  kind: 'popUp';
  options: GlassMenuOption[];
  value?: string;
  defaultValue?: string;
  onValueChange?: (value: string) => void;
  /**
   * What the choice is for. Required, because a pop-up button's own label is the current
   * selection and therefore never says what is being chosen.
   */
  'aria-label': string;
  /** Shown when nothing is selected yet. Prefer a real default selection to a placeholder. */
  placeholder?: string;
}

export type GlassMenuButtonProps = PullDownButtonProps | PopUpButtonProps;

/**
 * A button whose menu grows out of it.
 *
 * Two kinds, and the HIG is precise about the difference. A **pull-down** button performs or
 * clarifies its own action: the label stays put and the menu lists commands related to it.
 * A **pop-up** button presents a flat list of mutually exclusive options and *updates its own
 * label to show the current selection* — which is why its items are values rather than
 * commands, and why they read as `menuitemradio` rather than as checkboxes.
 *
 * Either can be assembled from `GlassButton` plus `GlassMenu`, but not the part that matters:
 * the chevron, the label that tracks the selection, the single-choice semantics, and the menu
 * morphing out of the button rather than appearing beside it.
 */
export function GlassMenuButton(props: GlassMenuButtonProps) {
  const triggerRef = useRef<HTMLButtonElement>(null);
  const popUp = props.kind === 'popUp';

  /**
   * "Listing a minimum of three items can help the interaction feel worthwhile" — below that,
   * the menu costs a press to reveal less than the buttons it replaced would have shown.
   * A warning, not an error: two items is a judgement call, not a broken component.
   */
  const count = popUp ? props.options.length : props.items.length;
  useEffect(() => {
    if (!inDevelopment() || !triggerRef.current || count >= 3) return;
    warnOnce(triggerRef.current, 'menu-button-too-few',
      `GlassMenuButton has ${count} item${count === 1 ? '' : 's'}. A menu has to be opened before it can be read, so below about three items plain buttons show more for less effort.`);
  }, [count]);

  return popUp ? <PopUp {...props} triggerRef={triggerRef} /> : <PullDown {...props} triggerRef={triggerRef} />;
}

type WithTrigger<P> = P & { triggerRef: React.RefObject<HTMLButtonElement | null> };

function Chevron() {
  return <LibraryIcon name="chevronDown" size={15} className="lg-menu-button-chevron" />;
}

function PullDown({
  label, items, variant = 'glass', controlSize = 'regular', align = 'end',
  placement = 'auto', className, id, ref, triggerRef, 'aria-label': ariaLabel,
  kind: _kind, ...rest
}: WithTrigger<PullDownButtonProps>) {
  return <GlassMenu
    aria-label={ariaLabel ?? (typeof label === 'string' ? label : 'Menu')}
    items={items} align={align} placement={placement} id={id}
    trigger={<GlassButton {...rest} ref={mergeRefs(ref, triggerRef)} variant={variant}
      controlSize={controlSize} className={cxButton(className)}>
      {label}<Chevron />
    </GlassButton>} />;
}

function PopUp({
  options, value, defaultValue, onValueChange, placeholder, variant = 'glass', controlSize = 'regular',
  align = 'end', placement = 'auto', className, id, ref, triggerRef,
  'aria-label': ariaLabel, kind: _kind, ...rest
}: WithTrigger<PopUpButtonProps>) {
  const [current, setCurrent] = useControllable(value, defaultValue ?? options[0]?.value ?? '', onValueChange);
  const selected = options.find(option => option.value === current);

  /* Values, turned into menu items at the edge. The checkmark is state rather than colour, and
     `selection="single"` makes it a radio group so picking one is understood to clear the rest. */
  const items: GlassMenuItem[] = options.map(option => ({
    key: option.value,
    label: option.label,
    icon: option.icon,
    disabled: option.disabled,
    separatorBefore: option.separatorBefore,
    checked: option.value === current,
    onSelect: () => setCurrent(option.value),
  }));

  return <GlassMenu
    aria-label={ariaLabel} items={items} selection="single" align={align} placement={placement} id={id}
    trigger={<GlassButton {...rest} ref={mergeRefs(ref, triggerRef)} variant={variant}
      controlSize={controlSize} aria-label={ariaLabel} className={cxButton(className)}>
      {/* The button's content *is* the current selection — that is what makes it a pop-up button. */}
      <span className="lg-menu-button-value">{selected?.label ?? placeholder ?? ''}</span><Chevron />
    </GlassButton>} />;
}

const cxButton = (className?: string) => className ? `lg-menu-button ${className}` : 'lg-menu-button';

/** Two refs onto one button: the caller's, and the one the item-count warning needs. */
function mergeRefs(outer: PullDownButtonProps['ref'], inner: React.RefObject<HTMLButtonElement | null>) {
  return (node: HTMLButtonElement | null) => {
    inner.current = node;
    if (typeof outer === 'function') outer(node);
    else if (outer) outer.current = node;
  };
}

'use client';
import { useEffect, useId, useRef, useState, type CSSProperties, type HTMLAttributes, type ReactNode, type RefAttributes } from 'react';
import { useGlassSurface, type GlassSurfaceOptions } from '../system/material.js';
import { splitSurface } from '../system/props.js';
import { Kbd } from '../content/kbd.js';
import { cx, useControllable } from '../system/utils.js';
import { triggerElement, usePopover, type Align, type OpenProps } from './anchor.js';

/**
 * What an item becomes while Option is held — Close becoming Close All, Duplicate becoming
 * Save As. It **replaces** the item it belongs to rather than appearing beside it, which is
 * what makes a long menu stay short.
 *
 * An alternate is a shorthand, never the only route to a command: nothing about holding a
 * modifier is discoverable, and a command that exists only there does not exist for anyone
 * using the keyboard by voice or one key at a time.
 */
export interface GlassMenuAlternate {
  label: string;
  onSelect: () => void;
  destructive?: boolean;
  shortcut?: string;
}

export interface GlassMenuItem {
  key: string; label: string; onSelect: () => void;
  disabled?: boolean; destructive?: boolean; shortcut?: string;
  alternate?: GlassMenuAlternate;
  /** Leading glyph. Introduce a related group with one symbol; do not decorate every row. */
  icon?: ReactNode;
  /** Checkmark for state. Reads as `aria-checked`, so it is not colour-only meaning. */
  checked?: boolean;
  separatorBefore?: boolean;
}
export interface GlassMenuProps extends Omit<HTMLAttributes<HTMLDivElement>, 'children'>, RefAttributes<HTMLDivElement>, GlassSurfaceOptions, OpenProps {
  items: GlassMenuItem[]; 'aria-label': string; align?: Align;
  /** Where the menu opens relative to its trigger. `auto` flips up when there is no room below. */
  placement?: 'below' | 'above' | 'auto';
  /**
   * What a checkmark in this menu means. `multiple` (the default) is a set of independent
   * toggles, each item a `menuitemcheckbox`. `single` is one choice out of the list — a pop-up
   * button's menu — and the items become `menuitemradio`, which is what tells assistive
   * technology that picking one clears the others.
   */
  selection?: 'multiple' | 'single';
}

/**
 * A menu on large glass that morphs out of its trigger.
 *
 * The menu keyboard model is a contract, so the roles are real: Up/Down move, Home/End jump,
 * typing jumps to a matching label, Escape closes and returns focus, Tab closes. Keep groups
 * to about seven items and separate them rather than growing one long list.
 */
/**
 * The menu keyboard model, shared by every menu panel in the library.
 *
 * It is a contract rather than a convenience — Up and Down move, Home and End jump, typing
 * skips to a matching label, Escape closes and returns focus, Tab closes — so it lives in one
 * place. `ContextMenu` opens by a different route but is the same thing once it is open, and
 * two copies of this would drift.
 */
export function menuKeyboard(
  event: React.KeyboardEvent, panel: HTMLElement | null, close: () => void,
  search: { text: string; time: number } = shared,
) {
  if (event.key === 'Escape') { event.preventDefault(); close(); return; }
  if (event.key === 'Tab') { close(); return; }
  const enabled = Array.from(panel?.querySelectorAll<HTMLButtonElement>(
    '[role="menuitem"]:not(:disabled),[role="menuitemcheckbox"]:not(:disabled),[role="menuitemradio"]:not(:disabled)') ?? []);
  const index = enabled.indexOf(document.activeElement as HTMLButtonElement);
  if (!enabled.length) return;
  let next = index;
  if (event.key === 'ArrowDown') next = (index + 1) % enabled.length;
  else if (event.key === 'ArrowUp') next = (index - 1 + enabled.length) % enabled.length;
  else if (event.key === 'Home') next = 0;
  else if (event.key === 'End') next = enabled.length - 1;
  else if (event.key.length === 1 && event.key !== ' ' && !event.ctrlKey && !event.metaKey && !event.altKey) {
    const now = Date.now();
    search.text = (now - search.time > 700 ? '' : search.text) + event.key.toLocaleLowerCase();
    search.time = now;
    const match = [...enabled.slice(index + 1), ...enabled.slice(0, index + 1)]
      .find(button => button.dataset.label?.toLocaleLowerCase().startsWith(search.text));
    if (match) { event.preventDefault(); match.focus(); }
    return;
  } else return;
  event.preventDefault();
  enabled[next]?.focus();
}

/** Type-ahead state for a caller that does not keep its own. One menu is open at a time. */
const shared = { text: '', time: 0 };

/**
 * Whether Option is down right now, asked only while `active`.
 *
 * `keydown` and `keyup` both carry `altKey`, so one handler reads both edges and there is no
 * state to keep in step. The listener that matters most is the third one: a key held while the
 * window loses focus never delivers its `keyup`, and a menu left showing its alternates after
 * the user has tabbed away would run the wrong command on the next click.
 */
export function useOptionHeld(active: boolean) {
  const [held, setHeld] = useState(false);
  useEffect(() => {
    if (!active) { setHeld(false); return; }
    const sync = (event: KeyboardEvent) => setHeld(event.altKey);
    const release = () => setHeld(false);
    window.addEventListener('keydown', sync);
    window.addEventListener('keyup', sync);
    window.addEventListener('blur', release);
    return () => {
      window.removeEventListener('keydown', sync);
      window.removeEventListener('keyup', sync);
      window.removeEventListener('blur', release);
    };
  }, [active]);
  return held;
}

export function GlassMenu({ trigger, open: controlled, defaultOpen = false, onOpenChange, items, 'aria-label': label, className, style, align = 'end', placement = 'auto', selection = 'multiple', id: providedId, ref, ...rest }: GlassMenuProps) {
  const [surface, props] = splitSurface(rest);
  const generated = useId(); const id = providedId ?? generated; const triggerRef = useRef<HTMLButtonElement>(null);
  const [open, setOpen] = useControllable(controlled, defaultOpen, onOpenChange);
  const glass = useGlassSurface<HTMLDivElement>({ ...surface, material: 'regular', size: 'large' }, ref);
  const search = useRef({ text: '', time: 0 });
  usePopover(open, setOpen, glass.root, triggerRef, align, true, placement);
  const close = () => { setOpen(false); triggerRef.current?.focus(); };
  /* Only listened for when this menu is open and something in it has an alternate — a menu
     without one has no reason to re-render on every Option press anywhere in the window. */
  const optionHeld = useOptionHeld(open && items.some(item => item.alternate !== undefined));
  return <>
    {triggerElement(trigger, triggerRef, id, open, 'menu', setOpen)}
    <div {...props} id={id} ref={glass.ref} popover="auto" role="menu" tabIndex={-1} aria-label={label} {...glass.attributes}
      className={cx('lg-root lg-menu', className)} style={{ ...glass.style, ...style }}
      onKeyDown={event => menuKeyboard(event, glass.root.current, close, search.current)}>
      {glass.decoration}<div className="lg-content">{items.map((item, index) => {
        /* What this row is right now. An alternate replaces the item in place — same position,
           same row — which is the whole point: it is the command you were already reaching for,
           said differently. */
        const shown = optionHeld && item.alternate ? item.alternate : item;
        return <div key={item.key} role="none" style={{ '--lg-index': index } as CSSProperties}>
        {item.separatorBefore && <div role="separator" className="lg-menu-separator" />}
        <button type="button" role={item.checked === undefined ? 'menuitem' : selection === 'single' ? 'menuitemradio' : 'menuitemcheckbox'}
          aria-checked={item.checked} tabIndex={-1} className="lg-menu-item" data-label={shown.label}
            aria-keyshortcuts={shown.shortcut}
          data-alternate={shown === item ? undefined : 'true'}
          data-destructive={shown.destructive ? 'true' : 'false'} disabled={item.disabled}
          onClick={() => { close(); shown.onSelect(); }}>
          {item.icon && <span className="lg-menu-icon" aria-hidden="true">{item.icon}</span>}
          <span className="lg-menu-label">{shown.label}</span>
          {shown.shortcut && <Kbd className="lg-menu-shortcut" keys={shown.shortcut} aria-hidden="true" />}
        </button>
      </div>;
      })}</div>
    </div>
  </>;
}

'use client';
import { useEffect, useRef, type RefObject } from 'react';
import { lockScroll } from './anchor.js';

/**
 * A native modal `<dialog>`, driven by controlled React state.
 *
 * Four overlays in this library are the same dialog with different contents, and the part they
 * share is not styling — it is the sequence that makes a modal a modal: remember what had
 * focus, `showModal()` so the browser owns the top layer and the focus containment, lock the
 * page behind it, and on the way out close, unlock, and put focus back where it came from.
 * Written four times it drifts four ways, and the half anybody notices is the last step: a
 * dialog that closes and leaves focus on `<body>` drops a keyboard user at the top of the page.
 *
 * `onOpen` is for whatever each overlay does once it is up — an alert moving focus to the safe
 * action, a sheet painting its first detent. Held in a ref rather than taken as a dependency so
 * that it can close over fresh state without re-running the effect, which would close and
 * reopen the dialog mid-interaction.
 */
export function useModalDialog(
  open: boolean,
  node: RefObject<HTMLDialogElement | null>,
  trigger: RefObject<HTMLButtonElement | null>,
  onOpen?: (dialog: HTMLDialogElement) => void,
) {
  const latest = useRef(onOpen); latest.current = onOpen;
  const restore = useRef<HTMLElement | null>(null);
  useEffect(() => {
    const dialog = node.current; if (!dialog) return;
    if (!open) { if (dialog.open) dialog.close(); return; }
    restore.current = document.activeElement as HTMLElement | null;
    if (!dialog.open) dialog.showModal();
    latest.current?.(dialog);
    const unlock = lockScroll();
    return () => {
      if (dialog.open) dialog.close();
      unlock();
      /* The trigger if there was one, otherwise whatever had focus when this opened — a
         palette opened by a keyboard shortcut has no trigger at all. */
      const target = trigger.current ?? restore.current;
      if (target?.isConnected) target.focus({ preventScroll: true });
    };
  }, [open, node, trigger]);
}

'use client';
import {
  useId, useState,
  type CSSProperties, type HTMLAttributes, type KeyboardEvent, type PointerEvent, type ReactNode, type RefAttributes,
} from 'react';
import { cx, useControllable, useMeasureEffect } from '../system/utils.js';
import { useGlassStrings } from '../system/strings.js';
import { useGlassSurface, type GlassSurfaceOptions } from '../system/material.js';
import { splitSurface } from '../system/props.js';
import { LibraryIcon } from '../system/icon.js';

export interface PanelPoint { x: number; y: number }

export interface PanelProps extends Omit<HTMLAttributes<HTMLDivElement>, 'title' | 'onDrag'>, RefAttributes<HTMLDivElement>, GlassSurfaceOptions {
  /** A short noun or noun phrase, title case — "Inspector", "Colors", "Find and Replace". */
  title: string;
  children: ReactNode;
  /** Whether the panel is on screen. Uncontrolled panels start open. */
  open?: boolean;
  defaultOpen?: boolean;
  onOpenChange?: (open: boolean) => void;
  /** Rolled up to its title bar. The panel stays where it is and keeps its place on screen. */
  collapsed?: boolean;
  defaultCollapsed?: boolean;
  onCollapsedChange?: (collapsed: boolean) => void;
  /** Offset from the top-leading corner of the positioned ancestor it lives in. */
  position?: PanelPoint;
  defaultPosition?: PanelPoint;
  onPositionChange?: (position: PanelPoint) => void;
  /** Panels are sized by their content and by this; they are not resizable by a drag. */
  width?: number;
  /** Adds a close button to the title bar. Without it the panel has no way to dismiss itself. */
  onClose?: () => void;
  /** Extra controls at the trailing end of the title bar, before collapse and close. */
  accessory?: ReactNode;
}

const STEP = 8, BIG_STEP = 40;

/**
 * A small window that floats above the content, holding controls for whatever is selected.
 *
 * From the HIG's panels page:
 *
 * - **It floats above the window and is not modal.** Nothing behind it is disabled, there is no
 *   backdrop and no focus trap — the whole point is to adjust something and watch the result.
 *   That also settles the `role`: a non-modal `dialog`, which is what the panel is, rather than
 *   the modal one `GlassDialog` uses.
 * - **"It needs a title bar so people can position it where they want."** So the title bar is
 *   the handle, and — because a panel that can only be moved with a mouse cannot be moved by
 *   everyone — the handle takes focus and answers the arrow keys, the same bargain the split
 *   view's divider makes.
 * - **"Prefer simple adjustment controls."** Sliders and steppers over text fields: a panel is
 *   for turning things, not for filling in forms. Guidance for the caller, not something this
 *   component can enforce.
 * - **"Avoid making a panel's minimize button available."** There is no minimize. `collapsed`
 *   rolls it up to its title bar, which is the thing Apple's own panels do and is not the same
 *   as sending it to the Dock.
 *
 * **HUD style is deliberately not here.** The HIG allows a dark translucent panel for
 * media-heavy apps and then spends a paragraph on when not to: most system controls do not
 * match it, and it does not follow the appearance setting. A `variant="hud"` would be a prop
 * whose documentation is mostly a warning. `material="clear"` over a photograph is the same
 * idea, reachable, and already carries the dimming rule with it.
 *
 * Positioned absolutely inside the nearest positioned ancestor, so a panel belongs to a region
 * of the application rather than to the viewport. Give that ancestor `position: relative`.
 */
export function Panel({
  title, children,
  open: controlledOpen, defaultOpen = true, onOpenChange,
  collapsed: controlledCollapsed, defaultCollapsed = false, onCollapsedChange,
  position: controlledPosition, defaultPosition = { x: 24, y: 24 }, onPositionChange,
  width = 280, onClose, accessory,
  className, style, ref, ...rest
}: PanelProps) {
  const [surface, props] = splitSurface(rest);
  const strings = useGlassStrings();
  const generated = useId();
  const [open, setOpen] = useControllable(controlledOpen, defaultOpen, onOpenChange);
  const [collapsed, setCollapsed] = useControllable(controlledCollapsed, defaultCollapsed, onCollapsedChange);
  const [point, setPoint] = useControllable(controlledPosition, defaultPosition, onPositionChange);
  const [moving, setMoving] = useState(false);
  const glass = useGlassSurface<HTMLDivElement>({ radius: 18, ...surface, material: surface.material ?? 'regular', size: 'large' }, ref);
  const glassNode = glass.root;

  /**
   * Clamped to the container it lives in, so a panel cannot be dragged out of reach.
   *
   * Measured at the start of each drag rather than held in state: the container can be resized
   * while the panel sits there, and a bound captured on mount would be a bound for a window
   * that no longer exists.
   */
  const boundsOf = () => {
    const self = glassNode.current;
    const parent = self?.offsetParent as HTMLElement | null;
    if (!self) return null;
    const width = self.offsetWidth, height = self.offsetHeight;
    const room = parent
      ? { w: parent.clientWidth, h: parent.clientHeight }
      : { w: typeof window === 'undefined' ? width : window.innerWidth, h: typeof window === 'undefined' ? height : window.innerHeight };
    /* A panel taller than its container still has to have somewhere to go: the maximum is
       floored at the minimum rather than left negative, which would pin it to the bottom. */
    return { maxX: Math.max(0, room.w - width), maxY: Math.max(0, room.h - height) };
  };
  const clamp = (next: PanelPoint): PanelPoint => {
    const bounds = boundsOf();
    if (!bounds) return next;
    return {
      x: Math.min(bounds.maxX, Math.max(0, Math.round(next.x))),
      y: Math.min(bounds.maxY, Math.max(0, Math.round(next.y))),
    };
  };

  /**
   * And clamped when it arrives, not only when it is dragged.
   *
   * `defaultPosition` is a guess made before anything has been measured — the caller does not
   * know how wide the container will be, and on a phone it is routinely narrower than the
   * offset the panel was given. Without this the panel opens half outside its frame, where it
   * is clipped by the container's overflow and cannot be dragged back because the title bar is
   * the part that is gone. Re-run on resize for the same reason.
   */
  useMeasureEffect(() => {
    if (!open) return;
    const node = glassNode.current;
    if (!node) return;
    const settle = () => {
      const next = clamp(point);
      if (next.x !== point.x || next.y !== point.y) setPoint(next);
    };
    settle();
    const parent = node.offsetParent as HTMLElement | null;
    if (!parent || typeof ResizeObserver === 'undefined') return;
    const observer = new ResizeObserver(settle);
    observer.observe(parent);
    return () => observer.disconnect();
  });

  const startDrag = (event: PointerEvent<HTMLDivElement>) => {
    if (event.button !== 0 || !event.isPrimary) return;
    /* A press on the collapse or close button is a press on that button. */
    if ((event.target as HTMLElement).closest('button')) return;
    const origin = { x: event.clientX, y: event.clientY };
    const from = point;
    event.currentTarget.setPointerCapture(event.pointerId);
    setMoving(true);
    let frame = 0;
    const move = (moveEvent: globalThis.PointerEvent) => {
      cancelAnimationFrame(frame);
      frame = requestAnimationFrame(() => setPoint(clamp({
        x: from.x + (moveEvent.clientX - origin.x),
        y: from.y + (moveEvent.clientY - origin.y),
      })));
    };
    const end = () => {
      cancelAnimationFrame(frame);
      setMoving(false);
      window.removeEventListener('pointermove', move);
      window.removeEventListener('pointerup', end);
      window.removeEventListener('pointercancel', end);
    };
    window.addEventListener('pointermove', move, { passive: true });
    window.addEventListener('pointerup', end);
    window.addEventListener('pointercancel', end);
  };

  const onKeyDown = (event: KeyboardEvent<HTMLDivElement>) => {
    const step = event.shiftKey ? BIG_STEP : STEP;
    const moves: Record<string, PanelPoint> = {
      ArrowLeft: { x: point.x - step, y: point.y },
      ArrowRight: { x: point.x + step, y: point.y },
      ArrowUp: { x: point.x, y: point.y - step },
      ArrowDown: { x: point.x, y: point.y + step },
    };
    const next = moves[event.key];
    if (next) { setPoint(clamp(next)); event.preventDefault(); return; }
    if (event.key === 'Escape' && onClose) { onClose(); event.preventDefault(); }
  };

  if (!open) return null;

  return <div {...props} ref={glass.ref} {...glass.attributes}
    className={cx('lg-root lg-panel', className)}
    role="dialog" aria-modal="false" aria-labelledby={`${generated}-title`}
    data-collapsed={collapsed ? 'true' : undefined} data-moving={moving ? 'true' : undefined}
    style={{ ...glass.style, insetInlineStart: `${point.x}px`, insetBlockStart: `${point.y}px`, width: `${width}px`, ...style } as CSSProperties}>
    {glass.decoration}
    {/* The handle is a `separator`-less thing: it moves a window rather than resizing a pane,
        and there is no ARIA role for that. So it is a focusable group with an accessible name
        that says what the arrows will do, which is the part that has to reach the reader. */}
    <div className="lg-panel-bar" tabIndex={0} role="group" aria-label={strings.movePanel(title)}
      onPointerDown={startDrag} onKeyDown={onKeyDown}>
      <span className="lg-panel-title" id={`${generated}-title`}>{title}</span>
      {accessory && <span className="lg-panel-accessory">{accessory}</span>}
      <button type="button" className="lg-panel-action" aria-expanded={!collapsed}
        aria-label={collapsed ? strings.expandPanel(title) : strings.collapsePanel(title)}
        onClick={() => setCollapsed(!collapsed)}>
        <LibraryIcon name="chevronDown" size={14} className="lg-panel-chevron" />
      </button>
      {onClose && <button type="button" className="lg-panel-action" aria-label={strings.close}
        onClick={() => { setOpen(false); onClose(); }}>
        <LibraryIcon name="close" size={14} />
      </button>}
    </div>
    <div className="lg-panel-body" hidden={collapsed}>{children}</div>
  </div>;
}

'use client';
import { useId, useRef, type HTMLAttributes, type ReactNode, type RefAttributes } from 'react';
import { useGlassSurface, type GlassSurfaceOptions } from '../system/material.js';
import { splitSurface } from '../system/props.js';
import { SharedSurface } from '../system/surface.js';
import { cx, useControllable } from '../system/utils.js';
import { triggerElement, usePopover, type Align, type OpenProps } from './anchor.js';
import { useSizeClass } from '../system/size-class.js';

/**
 * `title` is the panel's heading, not the HTML tooltip. An `id` is accepted and becomes the
 * base the internal `-title` / `-desc` ids are derived from, so the ARIA wiring still holds
 * together — that is why it is taken rather than ignored.
 */
export interface GlassPopoverProps extends Omit<HTMLAttributes<HTMLDivElement>, 'title' | 'children'>, RefAttributes<HTMLDivElement>, GlassSurfaceOptions, OpenProps {
  title: string; children: ReactNode; description?: string; align?: Align;
  /** Where the panel opens relative to its trigger. `auto` flips up when there is no room below. */
  placement?: 'below' | 'above' | 'auto';
}

/**
 * A non-modal panel anchored to the control that opened it, on large glass, with an arrow
 * pointing as directly as it can at that control. Escape closes it and returns focus to the
 * trigger; a click outside light-dismisses it.
 *
 * A popover with an arrow is an iPad and Mac idiom, so in a compact environment it presents
 * as a bottom sheet instead — full width, pinned to the bottom edge, no arrow, because an
 * arrow from the bottom of the screen to a control halfway up it points at nothing. The
 * content, the roles and the keyboard path are the same either way; only the shape changes.
 */
export function GlassPopover({ trigger, open: controlled, defaultOpen = false, onOpenChange, title, description, children, align = 'end', placement = 'auto', className, style, id: providedId, ref, ...rest }: GlassPopoverProps) {
  const [surface, props] = splitSurface(rest);
  const generated = useId(); const id = providedId ?? generated; const triggerRef = useRef<HTMLButtonElement>(null);
  const [open, setOpen] = useControllable(controlled, defaultOpen, onOpenChange);
  const compact = useSizeClass() === 'compact';
  const glass = useGlassSurface<HTMLDivElement>({ ...surface, material: 'regular', size: 'large' }, ref);
  usePopover(open, setOpen, glass.root, triggerRef, align, false, placement, compact ? 'bottom' : 'source');
  return <>
    {triggerElement(trigger, triggerRef, id, open, 'dialog', setOpen)}
    <div {...props} popover="auto" id={id} ref={glass.ref} role="dialog" tabIndex={-1} aria-labelledby={`${id}-title`} aria-describedby={description ? `${id}-desc` : undefined}
      {...glass.attributes} className={cx('lg-root lg-popover', className)} style={{ ...glass.style, ...style }}
      data-anchor={compact ? 'bottom' : 'source'}
      onKeyDown={event => { if (event.key === 'Escape') { event.preventDefault(); setOpen(false); triggerRef.current?.focus(); } }}>
      {glass.decoration}<div className="lg-content"><SharedSurface value={true}>
        <h3 id={`${id}-title`} className="lg-overlay-title">{title}</h3>
        {description && <p id={`${id}-desc`} className="lg-overlay-description">{description}</p>}
        {children}
      </SharedSurface></div>
    </div>
  </>;
}

export interface GlassMenuDescriptionProps extends HTMLAttributes<HTMLParagraphElement>, RefAttributes<HTMLParagraphElement> {}
export function GlassMenuDescription({ className, ref, ...props }: GlassMenuDescriptionProps) {
  return <p {...props} ref={ref} className={cx('lg-overlay-description', className)} />;
}

'use client';
import { useCallback, useEffect, useId, useRef, useState, type CSSProperties, type DialogHTMLAttributes, type ReactNode, type RefAttributes } from 'react';
import { createSpring } from '../../core/index.js';
import { useGlassSurface, type GlassSurfaceOptions } from '../system/material.js';
import { splitSurface } from '../system/props.js';
import { useGlassPolicy } from '../system/provider.js';
import { SharedSurface } from '../system/surface.js';
import { cx, useControllable } from '../system/utils.js';
import { triggerElement, type OpenProps } from './anchor.js';
import { useModalDialog } from './modal.js';
import { useGlassStrings } from '../system/strings.js';

export type SheetDetent = 'medium' | 'large';
/** Fraction of the viewport each detent occupies. `large` stops just short of the top. */
const DETENT_FRACTION: Record<SheetDetent, number> = { medium: .5, large: .94 };
/** At or above this fraction the sheet is effectively full height: opaque, anchored to the edge. */
const FULL = .9;

/** `open` is the controlled state, not the `<dialog>` attribute — the element is opened with `showModal`. */
export interface GlassSheetProps extends Omit<DialogHTMLAttributes<HTMLDialogElement>, 'title' | 'children' | 'open'>, RefAttributes<HTMLDialogElement>, GlassSurfaceOptions, OpenProps {
  title: string;
  description?: string;
  children: ReactNode;
  /** Heights the sheet settles at. Ordered smallest first. */
  detents?: SheetDetent[];
  defaultDetent?: SheetDetent;
  onDetentChange?: (detent: SheetDetent) => void;
  /** The drag handle. Hide it only if the sheet has a single detent and cannot be dragged. */
  grabber?: boolean;
}

/**
 * A sheet that is inset from the display edge on glass and grows as it is dragged up,
 * becoming **opaque and anchored to the edge at full height** — translucency at full height
 * would just be a blurry app behind a wall of text.
 *
 * The drag is the point: the sheet tracks the finger 1:1 and settles on a spring at the
 * nearest detent, and it is interruptible mid-flight. Only `transform` moves, never `height`,
 * so the drag stays on the compositor.
 *
 * **On a pointer it is a different object with the same API.** The HIG's sheets page describes
 * the macOS form in one sentence — "a cardlike view with rounded corners that floats on top of
 * its parent window", with the parent dimmed — and none of the paragraph above survives it:
 * there is no edge to rise from, no finger to track, and no reason to drag something that is
 * already the size it should be. So on desktop the sheet drops in from the top of the window,
 * sits centred at a size taken from its content, and has no grabber. `detents` is then inert,
 * and that is written down rather than silently true: a caller who passes `['medium','large']`
 * has expressed a preference the platform has no way to honour.
 */
export function GlassSheet({
  trigger, open: controlled, defaultOpen = false, onOpenChange, title, description, children,
  detents = ['medium', 'large'], defaultDetent, onDetentChange, grabber = true, className, style, id: providedId, ref, ...rest
}: GlassSheetProps) {
  const [surface, props] = splitSurface(rest);
  const strings = useGlassStrings();
  if (detents.length === 0) throw new Error('GlassSheet requires at least one detent');
  const generated = useId(); const id = providedId ?? generated; const triggerRef = useRef<HTMLButtonElement>(null);
  const [open, setOpen] = useControllable(controlled, defaultOpen, onOpenChange);
  const [detent, setDetent] = useControllable(undefined, defaultDetent ?? detents[0], onDetentChange);
  const policy = useGlassPolicy();
  /* The card form. Everything below that talks about detents, dragging or the display edge is
     skipped when this is true, rather than being drawn and then disabled. */
  const card = policy.resolvedPlatform === 'desktop';
  const glass = useGlassSurface<HTMLDialogElement>({ ...surface, material: 'regular', size: 'large', radius: surface.radius ?? (card ? 20 : 38) }, ref);
  const fractions = detents.map(name => DETENT_FRACTION[name]);
  const [full, setFull] = useState(DETENT_FRACTION[detent] >= FULL);
  const spring = useRef<ReturnType<typeof createSpring> | null>(null);

  /** One writer for the visible fraction, so the drag and the spring cannot fight each other. */
  const paint = useCallback((fraction: number) => {
    const node = glass.root.current; if (!node) return;
    node.style.setProperty('--lg-sheet-offset', `${((1 - fraction) * 100).toFixed(3)}%`);
    setFull(fraction >= FULL);
  }, [glass.root]);

  /* `detent` is read through the callback rather than taken as a dependency: re-running the
     open sequence on every detent change would close and reopen the dialog mid-drag. */
  useModalDialog(open, glass.root, triggerRef, () => paint(DETENT_FRACTION[detent]));

  useEffect(() => { if (open) paint(DETENT_FRACTION[detent]); }, [detent, open, paint]);

  /**
   * The drag.
   *
   * The whole panel is the handle, not just the little bar at the top — that is what the
   * system does, and the rule it uses is about the scroll position rather than about which
   * element was touched. A gesture that starts in the body belongs to the sheet only while
   * the content is scrolled to the top, and even then only in the direction that does not
   * have somewhere else to go: downwards always, upwards only while there is a taller detent
   * left to grow into. Once the sheet is at its tallest, pulling up is the user reading, and
   * a sheet that took that gesture would make its own content unreachable.
   *
   * Nothing here calls `preventDefault` or captures the pointer before the direction is known,
   * so buttons and fields inside the sheet keep working: a body-wide handler that swallowed
   * `pointerdown` would break every control in the panel, which is worse than the bug it fixes.
   */
  useEffect(() => {
    const node = glass.root.current;
    if (!node || !open || card) return;
    const handle = node.querySelector<HTMLElement>('.lg-sheet-grabber');
    const scroller = node.querySelector<HTMLElement>('.lg-sheet-scroll');
    /** Movement, in px, before a gesture is called vertical or horizontal. */
    const SLOP = 6;
    let active = false, startY = 0, startX = 0, startFraction = 0, height = 1, pointer = -1, frame = 0, latest = 0;
    /** `false` until the gesture has committed to the sheet; the grabber commits immediately. */
    let owned = false;
    const settle = (fraction: number) => {
      // Nearest detent wins; below the smallest one the gesture is a dismissal.
      if (fraction < fractions[0] * .6) { setOpen(false); return; }
      const nearest = fractions.reduce((best, value) => Math.abs(value - fraction) < Math.abs(best - fraction) ? value : best, fractions[0]);
      const name = detents[fractions.indexOf(nearest)];
      if (policy.reduceMotion) { paint(nearest); setDetent(name); return; }
      spring.current?.stop();
      const animation = createSpring(fraction, paint, { stiffness: 260, damping: 26 });
      spring.current = animation;
      animation.to(nearest);
      setDetent(name);
    };
    /** Does a gesture from the body, moving this way, belong to the sheet or to the content? */
    const claim = (dy: number) => {
      if (!scroller) return true;
      if (scroller.scrollTop > 0) return false;             // the content is the scroll view's
      if (dy > 0) return true;                              // pulling down from the top
      return startFraction < Math.max(...fractions) - .01;  // pulling up, with room left to grow
    };
    const detach = () => {
      window.removeEventListener('pointermove', move); window.removeEventListener('pointerup', end);
      window.removeEventListener('pointercancel', end);
    };
    const move = (event: PointerEvent) => {
      if (!active || event.pointerId !== pointer) return;
      const dy = event.clientY - startY, dx = event.clientX - startX;
      if (!owned) {
        if (Math.abs(dy) < SLOP && Math.abs(dx) < SLOP) return;
        // A sideways gesture is not a sheet gesture; neither is one the content has a use for.
        if (Math.abs(dx) > Math.abs(dy) || !claim(dy)) { active = false; pointer = -1; detach(); return; }
        owned = true;
        node.setAttribute('data-dragging', 'true');
      }
      latest = startFraction - dy / height;
      cancelAnimationFrame(frame);
      // Rubber-band past the top so the sheet never detaches from the finger.
      frame = requestAnimationFrame(() => paint(Math.min(1, Math.max(.04, latest > 1 ? 1 + (latest - 1) * .2 : latest))));
    };
    const end = () => {
      if (!active) return;
      const committed = owned;
      active = false; owned = false; pointer = -1; cancelAnimationFrame(frame);
      node.removeAttribute('data-dragging');
      detach();
      if (committed) settle(Math.min(1, Math.max(.04, latest)));
    };
    const begin = (event: PointerEvent, immediate: boolean) => {
      if (event.button !== 0 || !event.isPrimary || active) return;
      spring.current?.stop();
      // Measured once at gesture start; reading layout inside pointermove is what drops frames.
      height = window.innerHeight || 1;
      const offset = parseFloat(getComputedStyle(node).getPropertyValue('--lg-sheet-offset')) || 0;
      startFraction = 1 - offset / 100;
      latest = startFraction;
      startY = event.clientY; startX = event.clientX; active = true; pointer = event.pointerId;
      owned = immediate;
      if (immediate) node.setAttribute('data-dragging', 'true');
      window.addEventListener('pointermove', move, { passive: true });
      window.addEventListener('pointerup', end); window.addEventListener('pointercancel', end);
    };
    /* The grabber has nothing else the gesture could mean, so it commits at once. The body
       waits to see where the finger goes. */
    const onHandle = (event: PointerEvent) => begin(event, true);
    const onBody = (event: PointerEvent) => { if (!handle?.contains(event.target as Node)) begin(event, false); };
    handle?.addEventListener('pointerdown', onHandle);
    node.addEventListener('pointerdown', onBody);
    return () => {
      handle?.removeEventListener('pointerdown', onHandle);
      node.removeEventListener('pointerdown', onBody);
      end(); spring.current?.stop();
    };
  }, [open, card, glass.root, detents.join(), fractions.join(), policy.reduceMotion, paint, setDetent, setOpen]);

  return <>
    {triggerElement(trigger, triggerRef, id, open, 'dialog', setOpen)}
    <dialog {...props} id={id} ref={glass.ref} aria-labelledby={`${id}-title`} aria-describedby={description ? `${id}-desc` : undefined}
      {...glass.attributes} className={cx('lg-root lg-sheet', className)}
      data-form={card ? 'card' : 'edge'} data-full={!card && full ? 'true' : undefined}
      style={{ '--lg-sheet-offset': `${(1 - DETENT_FRACTION[detent]) * 100}%`, ...glass.style, ...style } as CSSProperties}
      onCancel={event => { event.preventDefault(); setOpen(false); }}
      onClose={() => { if (!glass.root.current?.open) setOpen(false); }}>
      {glass.decoration}
      <div className="lg-content">
        <SharedSurface value={true}>
          {!card && grabber && detents.length > 1 && <div className="lg-sheet-grabber" role="slider" tabIndex={0}
            aria-label={strings.sheetHeight(title)} aria-valuetext={detent}
            aria-valuenow={fractions.indexOf(DETENT_FRACTION[detent])} aria-valuemin={0} aria-valuemax={detents.length - 1}
            onKeyDown={event => {
              const index = detents.indexOf(detent);
              if (event.key === 'ArrowUp' && index < detents.length - 1) { event.preventDefault(); setDetent(detents[index + 1]); }
              else if (event.key === 'ArrowDown') { event.preventDefault(); if (index > 0) setDetent(detents[index - 1]); else setOpen(false); }
            }}><span aria-hidden="true" /></div>}
          <div className="lg-sheet-scroll">
            <h2 id={`${id}-title`} className="lg-overlay-title">{title}</h2>
            {description && <p id={`${id}-desc`} className="lg-overlay-description">{description}</p>}
            {children}
          </div>
        </SharedSurface>
      </div>
    </dialog>
  </>;
}

'use client';
import { createContext, useCallback, useContext, useEffect, useRef, useState, type ReactNode } from 'react';
import { useGlassSurface } from '../system/material.js';
import { SharedSurface } from '../system/surface.js';
import { GlassButton, GlassIconButton } from '../controls/button.js';
import { LibraryIcon, type LibraryIconName } from '../system/icon.js';
import { useGlassStrings } from '../system/strings.js';
import { useGlassPolicy } from '../system/provider.js';
import { EXIT_MS } from '../system/leave.js';
import { cx } from '../system/utils.js';

/**
 * What a toast is reporting. `neutral` is the default and is right for almost everything —
 * "Deleted", "Copied". A tone is not decoration: use it only where the outcome itself is the
 * message, and never as the only carrier of it, which is why each tone also has a glyph.
 */
export type ToastTone = 'neutral' | 'success' | 'warning' | 'error';

export interface ToastOptions {
  message: string;
  tone?: ToastTone;
  /**
   * A glyph before the message. Defaults to the tone's own, which is what keeps the tone from
   * being colour alone; pass `null` for none.
   */
  icon?: ReactNode | null;
  /** The undo affordance. This is what lets a reversible action skip the confirmation dialog. */
  action?: { label: string; onSelect: () => void };
  /** Milliseconds on screen. Undo needs long enough to read and reach — five seconds or more. */
  duration?: number;
  /**
   * The close button's name. Defaults to the provider's `close`. Set it to `null` only for a
   * toast that genuinely must not be dismissed — which is almost never, because a message
   * that cannot be got rid of is one that sits over the thing it is talking about.
   */
  dismissLabel?: string | null;
}
interface ToastRecord extends Required<Pick<ToastOptions, 'message' | 'duration'>> {
  id: number;
  action?: ToastOptions['action'];
  dismissLabel?: string | null;
  tone: ToastTone;
  icon?: ReactNode | null;
  /** On its way out: still in the tree so the exit can play, no longer counted as on screen. */
  leaving?: boolean;
}

/** The glyph each tone carries, so the tone is never only a colour. */
const TONE_ICON: Record<ToastTone, LibraryIconName | null> = {
  neutral: null, success: 'checkmark', warning: 'minus', error: 'close',
};

const ToastContext = createContext<((options: ToastOptions) => void) | null>(null);

/**
 * The counterpart to confirmation dialogs.
 *
 * Irreversible actions get an alert or an action sheet; **reversible** ones should just
 * happen, with an Undo here. Making every delete stop and ask is how an interface becomes
 * tiring, and offering neither is how it becomes untrustworthy.
 */
export function useToast() {
  const show = useContext(ToastContext);
  if (!show) throw new Error('useToast must be used inside a <ToastProvider>');
  return show;
}

export interface ToastProviderProps {
  children: ReactNode;
  /** How many can stack before the oldest is dropped. */
  limit?: number;
}
export function ToastProvider({ children, limit = 3 }: ToastProviderProps) {
  const [toasts, setToasts] = useState<ToastRecord[]>([]);
  const nextId = useRef(0);
  const reduceMotion = useGlassPolicy().reduceMotion;

  /**
   * Going away is a state, not an event.
   *
   * Every route out — the close button, Escape, the timer running down, being pushed off the
   * end by a newer one — comes through here, so all four look the same on screen. Holding the
   * record in the list with `leaving` set is what gives the exit something to animate: React
   * cannot animate a node it has already removed, and neither can CSS.
   */
  const leaving = useRef(new Set<number>());
  const list = useRef<ToastRecord[]>([]); list.current = toasts;
  const remove = useCallback((id: number) => {
    leaving.current.delete(id);
    setToasts(current => current.filter(toast => toast.id !== id));
  }, []);
  const dismiss = useCallback((id: number) => {
    if (reduceMotion) return remove(id);
    if (leaving.current.has(id)) return;
    leaving.current.add(id);
    setToasts(current => current.map(toast => toast.id === id ? { ...toast, leaving: true } : toast));
    setTimeout(() => remove(id), EXIT_MS);
  }, [reduceMotion, remove]);
  const dismissRef = useRef(dismiss); dismissRef.current = dismiss;

  /**
   * Escape closes the newest one.
   *
   * A toast is not modal and takes no focus, so there is nothing for a key handler to hang
   * off — it has to listen at the window while any toast is on screen. Newest first, because
   * that is the one that just appeared over whatever the user was reading.
   *
   * It does not `preventDefault`: a toast is the least important thing on screen, and Escape
   * inside an open dialog belongs to the dialog. The dialog stops the event before it gets
   * here; if nothing does, this is the only thing Escape had to close anyway.
   */
  useEffect(() => {
    if (!toasts.length) return;
    const onKey = (event: KeyboardEvent) => {
      if (event.key !== 'Escape' || event.defaultPrevented) return;
      // The newest one still on screen — one already leaving is not the one they meant.
      const newest = list.current.filter(toast => !toast.leaving).at(-1);
      if (newest) dismissRef.current(newest.id);
    };
    window.addEventListener('keydown', onKey);
    return () => window.removeEventListener('keydown', onKey);
  }, [toasts.length]);
  const show = useCallback((options: ToastOptions) => {
    const record: ToastRecord = { id: nextId.current++, message: options.message, duration: options.duration ?? 6000, action: options.action, dismissLabel: options.dismissLabel, tone: options.tone ?? 'neutral', icon: options.icon };
    setToasts(current => [...current, record]);
    /* Over the limit, the oldest goes — through `dismiss`, so it leaves the way the others do
       rather than being cut. Counted against the ones actually on screen: a toast that is
       already playing its exit must not push a live one off the end. */
    const live = list.current.filter(toast => !toast.leaving);
    for (const extra of live.slice(0, live.length + 1 - limit)) dismissRef.current(extra.id);
  }, [limit]);
  return <ToastContext.Provider value={show}>
    {children}
    {/* Polite, not assertive: a toast reports something that already happened. */}
    <div className="lg-toast-region" role="status" aria-live="polite" aria-relevant="additions">
      {toasts.map(toast => <Toast key={toast.id} toast={toast} onDismiss={() => dismiss(toast.id)} />)}
    </div>
  </ToastContext.Provider>;
}

function Toast({ toast, onDismiss }: { toast: ToastRecord; onDismiss: () => void }) {
  const strings = useGlassStrings();
  const glass = useGlassSurface<HTMLDivElement>({ material: 'regular', size: 'large', radius: 'pill' });
  const [paused, setPaused] = useState(false);
  const dismissRef = useRef(onDismiss); dismissRef.current = onDismiss;
  useEffect(() => {
    if (paused || toast.leaving || toast.duration === Infinity) return;
    const timer = setTimeout(() => dismissRef.current(), toast.duration);
    return () => clearTimeout(timer);
  }, [paused, toast.leaving, toast.duration]);
  const glyph = toast.icon === null ? null
    : toast.icon ?? (TONE_ICON[toast.tone] && <LibraryIcon name={TONE_ICON[toast.tone]!} size={16} />);
  return <div ref={glass.ref} {...glass.attributes} className={cx('lg-root lg-toast')} data-tone={toast.tone}
    data-leaving={toast.leaving ? 'true' : undefined} style={glass.style}
    // Hovering or focusing holds the toast so the undo window is not lost while reaching for it.
    onPointerEnter={() => setPaused(true)} onPointerLeave={() => setPaused(false)}
    onFocusCapture={() => setPaused(true)} onBlurCapture={() => setPaused(false)}>
    {glass.decoration}
    <div className="lg-content"><SharedSurface value={true}>
      {glyph && <span className="lg-toast-icon" aria-hidden="true">{glyph}</span>}
      <span className="lg-toast-message">{toast.message}</span>
      {toast.action && <GlassButton className="lg-toast-action" controlSize="small"
        onClick={() => { toast.action!.onSelect(); onDismiss(); }}>{toast.action.label}</GlassButton>}
      {/* Waiting six seconds is not a way to dismiss something, and hovering to pause it is
          not available to a keyboard user at all. */}
      {toast.dismissLabel !== null && <GlassIconButton className="lg-toast-dismiss" variant="plain"
        controlSize="small" aria-label={toast.dismissLabel ?? strings.close} onClick={onDismiss}>
        <LibraryIcon name="close" size={15} />
      </GlassIconButton>}
    </SharedSurface></div>
  </div>;
}

'use client';
import {
  cloneElement, useEffect, useId, useRef, useState,
  type HTMLAttributes, type ReactElement, type ReactNode, type Ref, type RefAttributes,
} from 'react';
import { useGlassSurface, type GlassSurfaceOptions } from '../system/material.js';
import { splitSurface } from '../system/props.js';
import { assignRef, cx } from '../system/utils.js';

type AnchorProps = HTMLAttributes<HTMLElement> & { ref?: Ref<HTMLElement> };

export interface TooltipProps extends Omit<HTMLAttributes<HTMLDivElement>, 'children' | 'content'>,
  RefAttributes<HTMLDivElement>, GlassSurfaceOptions {
  /**
   * What the control does, starting with a verb — "Restore default settings". Not an
   * explanation of how a standard control works: that is the platform's job, not this one's.
   */
  content: ReactNode;
  /** The control it describes. Cloned, not wrapped, so nothing changes about its layout. */
  children: ReactElement<AnchorProps>;
  /** Milliseconds of hover before it appears. Focus shows it immediately. */
  delay?: number;
  placement?: 'above' | 'below';
}

/** One at a time, and the second one replaces the first rather than joining it. */
let openTooltip: symbol | null = null;

/**
 * The name of an icon-only control, shown to the people who cannot hear it.
 *
 * An `aria-label` tells a screen reader what a button does. It tells a sighted mouse user
 * nothing at all — they are left guessing from a glyph. This is the other half of that: the
 * same words, on screen, after a pause long enough that moving the pointer across a toolbar
 * does not set off a row of them.
 *
 * Three rules it will not break:
 *
 * - **Never on touch.** There is no hover on a touch screen, so a tooltip there can only be a
 *   thing that appears on tap and swallows the tap that was meant for the button. The whole
 *   component renders nothing under `(pointer: coarse)`.
 * - **Never the only source of the name.** It attaches with `aria-describedby`, which is
 *   supplementary. The control still needs its own accessible name, and this does not provide
 *   one — a tooltip is help, not a label.
 * - **Never in the way of the keyboard.** Focus shows it at once with no delay, and Escape
 *   dismisses it without closing anything else.
 */
export function Tooltip({
  content, children, delay = 600, placement = 'above', className, style, id: providedId, ref, ...rest
}: TooltipProps) {
  const [surface, props] = splitSurface(rest);
  const generated = useId(); const id = providedId ?? `${generated}-tip`;
  const anchor = useRef<HTMLElement>(null);
  const [open, setOpen] = useState(false);
  const timer = useRef<ReturnType<typeof setTimeout> | null>(null);
  const token = useRef(Symbol('tooltip'));
  const glass = useGlassSurface<HTMLDivElement>({ ...surface, material: 'regular', size: 'small' }, ref);

  /**
   * Hover exists or it does not; there is no useful middle. Read once per mount rather than
   * subscribed, because a pointer type does not change under a running page — and if it does,
   * the user has picked up a mouse and will hover again.
   */
  const [hoverable, setHoverable] = useState(false);
  useEffect(() => { setHoverable(window.matchMedia('(hover: hover) and (pointer: fine)').matches); }, []);

  const cancel = () => { if (timer.current) { clearTimeout(timer.current); timer.current = null; } };
  const hide = () => { cancel(); if (openTooltip === token.current) openTooltip = null; setOpen(false); };
  const show = (after: number) => {
    cancel();
    timer.current = setTimeout(() => { openTooltip = token.current; setOpen(true); }, after);
  };
  useEffect(() => cancel, []);

  /* Escape closes it, wherever the focus is — a tooltip is not modal, so it has no key
     handling of its own and has to listen while it is open. */
  useEffect(() => {
    if (!open) return;
    const onKey = (event: KeyboardEvent) => { if (event.key === 'Escape') hide(); };
    window.addEventListener('keydown', onKey);
    return () => window.removeEventListener('keydown', onKey);
  });

  /** Positioned against the anchor, like the other overlays, but never focused. */
  useEffect(() => {
    const panel = glass.root.current, target = anchor.current;
    if (!open || !panel || !target) return;
    if (typeof panel.showPopover !== 'function') { setOpen(false); return; }
    if (!panel.matches(':popover-open')) panel.showPopover();
    let frame = 0;
    const position = () => {
      const rect = target.getBoundingClientRect();
      const width = panel.offsetWidth, height = panel.offsetHeight;
      const above = rect.top - height - 8, below = rect.bottom + 8;
      const top = placement === 'below'
        ? (below + height <= innerHeight - 8 ? below : Math.max(8, above))
        : (above >= 8 ? above : below);
      panel.style.left = `${Math.max(8, Math.min(rect.left + (rect.width - width) / 2, innerWidth - width - 8))}px`;
      panel.style.top = `${top}px`;
    };
    const schedule = () => { cancelAnimationFrame(frame); frame = requestAnimationFrame(position); };
    position();
    const resize = new ResizeObserver(schedule); resize.observe(panel); resize.observe(target);
    window.addEventListener('resize', schedule); window.addEventListener('scroll', schedule, true);
    return () => {
      resize.disconnect(); cancelAnimationFrame(frame);
      window.removeEventListener('resize', schedule); window.removeEventListener('scroll', schedule, true);
      if (panel.matches(':popover-open')) panel.hidePopover();
    };
  }, [open, glass.root, placement]);

  // No hover, no tooltip — and no wrapper, no attribute, nothing. The control is untouched.
  if (!hoverable) return children;

  const anchored = cloneElement(children, {
    ref: node => {
      const outer = assignRef(children.props.ref, node);
      anchor.current = node;
      return () => {
        if (typeof outer === 'function') outer(); else assignRef(children.props.ref, null);
        anchor.current = null;
      };
    },
    /* `aria-describedby`, never `aria-labelledby`: this is help about a control that already
       has a name. Pointing the name at a node that only exists on hover would leave the
       control nameless the rest of the time. */
    'aria-describedby': open ? cx(children.props['aria-describedby'], id) : children.props['aria-describedby'],
    onPointerEnter: event => { children.props.onPointerEnter?.(event); show(delay); },
    onPointerLeave: event => { children.props.onPointerLeave?.(event); hide(); },
    onPointerDown: event => { children.props.onPointerDown?.(event); hide(); },
    // Focus is deliberate, so it does not wait: a keyboard user asked for this control.
    onFocus: event => { children.props.onFocus?.(event); if (event.target === anchor.current) show(0); },
    onBlur: event => { children.props.onBlur?.(event); hide(); },
  });

  return <>
    {anchored}
    <div {...props} id={id} ref={glass.ref} popover="manual" role="tooltip" {...glass.attributes}
      className={cx('lg-root lg-tooltip', className)} style={{ ...glass.style, ...style }}>
      {glass.decoration}<div className="lg-content">{content}</div>
    </div>
  </>;
}

'use client';
import { createContext, useContext, type HTMLAttributes, type ReactNode, type RefAttributes } from 'react';
import type { BackdropTone } from '../../tokens/index.js';

/**
 * Small Liquid Glass flips light/dark with whatever is behind it. Doing that honestly
 * needs to know the tone of the backdrop, and this library deliberately does not read it:
 * sampling would mean rasterising the page (DOM screenshots, cross-origin pixel reads),
 * which the project forbids. Instead a region declares its own tone once, and every
 * small glass surface inside inherits it.
 *
 * `mixed` is the safe default: an unknown backdrop keeps the app appearance and forces
 * `clear` back to `regular` rather than guessing.
 */
const BackdropToneContext = createContext<BackdropTone>('mixed');
export const useBackdropTone = () => useContext(BackdropToneContext);

export interface BackdropToneProviderProps { tone: BackdropTone; children: ReactNode }
/** Context-only form, for when you do not want an extra element in the tree. */
export function BackdropToneProvider({ tone, children }: BackdropToneProviderProps) {
  return <BackdropToneContext.Provider value={tone}>{children}</BackdropToneContext.Provider>;
}

export interface GlassBackdropProps extends HTMLAttributes<HTMLDivElement>, RefAttributes<HTMLDivElement> { tone: BackdropTone }
/**
 * A region whose tone is known — a photo, a video, a dark hero. Glass inside adapts to it
 * without any surface having to be told individually.
 */
export function GlassBackdrop({ tone, children, ref, ...props }: GlassBackdropProps) {
  return <div {...props} ref={ref} data-lg-backdrop-tone={tone}>
    <BackdropToneContext.Provider value={tone}>{children}</BackdropToneContext.Provider>
  </div>;
}

'use client';
import { useEffect, useId, useRef, type ReactNode, type RefObject } from 'react';
