  /** Fusable items inside the surface, e.g. `':scope > .lg-content > .lg-button'`. Disabled items never fuse. */
  itemSelector: string;
  /** Selection-lens mode: the lens is the primary blob and its previous slot leaves a collapsing trail. */
  lensSelector?: string;
