  .lg-root > .lg-decoration .lg-glow, .lg-decoration::after, .lg-fusion { display: none; }
  .lg-backdrop { backdrop-filter: none !important; -webkit-backdrop-filter: none !important; }
  .lg-selection-lens, .lg-switch-thumb { border: 1px solid var(--lg-label); }
  .lg-toolbar-separator, .lg-menu-separator { background: var(--lg-label); }
}
.lg-root[data-lg-contrast="more"]:not([data-renderer="shared"]) { background: var(--lg-opaque); }
.lg-root[data-lg-contrast="more"] > .lg-decoration .lg-tint { background: var(--lg-opaque); box-shadow: none; }
.lg-root[data-lg-contrast="more"] > .lg-decoration .lg-rim { background: none; border-color: var(--lg-label); mask: none; -webkit-mask: none; }
.lg-root[data-lg-contrast="more"] > .lg-decoration .lg-glow, .lg-root[data-lg-contrast="more"] .lg-decoration::after, .lg-root[data-lg-contrast="more"] .lg-fusion { display: none; }
.lg-root[data-lg-contrast="more"] .lg-backdrop { backdrop-filter: none !important; -webkit-backdrop-filter: none !important; }
@media (forced-colors: active) {
  .lg-root { background: Canvas; color: CanvasText; box-shadow: none; border: 1px solid ButtonText; }
  .lg-rim { background: none !important; mask: none !important; -webkit-mask: none !important; }
  .lg-decoration, .lg-fusion { display: none; }
  .lg-button:disabled { color: GrayText; opacity: 1; }
  .lg-root[data-renderer="shared"] { border-color: ButtonText; }
  .lg-button[data-variant="primary"], .lg-tab[aria-selected="true"] { background: Highlight; color: HighlightText; }
  .lg-root:focus-visible,.lg-root :focus-visible { outline: 3px solid Highlight; }
  .lg-selection-lens { border: 2px solid Highlight; background: Canvas; }
  .lg-slider-fill,.lg-switch-thumb { background: Highlight; }
  .lg-slider-track { border: 1px solid ButtonText; }
  .lg-switch-track[data-checked="true"] { background: Highlight; }
  .lg-switch-track[data-checked="true"] .lg-switch-thumb { background: HighlightText; }
  /* The panel is a bordered Canvas box here, so a filled triangle hanging off one edge with no
     border of its own reads as a stray shape rather than as part of it. The border is what
     says where the popover is; the arrow has nothing left to add. */
  .lg-popover[data-placement]::before { content: none; }
}

/* ---------- Kbd: a shortcut hint, in the content layer ---------- */
.lg-kbd { display: inline-flex; align-items: center; justify-content: center; min-width: 22px;
  padding: 2px 6px; border-radius: var(--lg-radius-xs); border: 1px solid var(--lg-separator);
  background: var(--lg-fill-quaternary); color: var(--lg-label-secondary);
  font-family: var(--lg-font-text); font-size: var(--lg-text-caption1-size); line-height: 1.5;
  font-variant-numeric: tabular-nums; white-space: nowrap; }

/* ---------- Tooltip: the name of an icon-only control, for the people who cannot hear it ---------- */
/* Small glass, and never on touch — the component renders nothing where there is no hover, so
   there is no `(pointer: coarse)` rule here to forget. */
.lg-tooltip { position: fixed; inset: auto; margin: 0; border: 0; max-width: 260px;
  padding: var(--lg-space-2) var(--lg-space-3); z-index: var(--lg-z-toast);
  font-size: var(--lg-text-caption1-size); line-height: var(--lg-text-caption1-leading);
  pointer-events: none; }
.lg-tooltip:not(:popover-open) { display: none; }
.lg-tooltip:popover-open { opacity: 1; scale: 1;
  transition: opacity var(--lg-duration-release) var(--lg-ease-out), scale var(--lg-duration-spring) var(--lg-spring),
    display var(--lg-duration-release) allow-discrete, overlay var(--lg-duration-release) allow-discrete; }
@starting-style { .lg-tooltip:popover-open { opacity: 0; scale: .94; } }
.lg-tooltip::backdrop { background: transparent; }

/* ---------- NavigationStack: one bar that follows a stack of screens ---------- */
/* `overflow-x: clip` contains the push/pop slide. The incoming screen starts 16px to one side,
   so without this the stack is 16px wider than itself for the length of the transition — and a
   stack that fills the window gives the page a horizontal scrollbar that flashes on every
   navigation. `clip` rather than `hidden`: it does not create a scroll container, so sticky
   bars inside the stack keep working. */
.lg-stack { display: flex; flex-direction: column; min-width: 0; overflow-x: clip; }
.lg-stack-screen { min-width: 0; outline: none; }
/* The back button reads as a destination, not a control: no glass, no fill, just the chevron
   and the previous screen's name. The chevron points backwards, which is the leading edge and
   therefore mirrors itself in RTL along with everything else. */
.lg-stack-back { padding-inline: var(--lg-space-1) var(--lg-space-2); color: var(--lg-accent); max-width: 40vw; }
.lg-stack-back-chevron { transform: scaleX(-1); flex: 0 0 auto; }
:dir(rtl) .lg-stack-back-chevron { transform: none; }
.lg-stack-back-title { overflow: hidden; text-overflow: ellipsis; white-space: nowrap; }

/* A cross-fade with a small slide. The slide is the part Reduce Motion removes — direction is
   what reads as movement, and a fade on its own still says "this is different now". */
@keyframes lg-stack-push { from { opacity: 0; translate: 16px 0; } }
@keyframes lg-stack-pop { from { opacity: 0; translate: -16px 0; } }
@keyframes lg-stack-fade { from { opacity: 0; } }
.lg-stack-screen[data-direction="push"] { animation: lg-stack-push var(--lg-duration-layout) var(--lg-ease-out); }
.lg-stack-screen[data-direction="pop"] { animation: lg-stack-pop var(--lg-duration-layout) var(--lg-ease-out); }
:dir(rtl) .lg-stack-screen[data-direction="push"] { animation-name: lg-stack-pop; }
:dir(rtl) .lg-stack-screen[data-direction="pop"] { animation-name: lg-stack-push; }
.lg-stack-screen[data-direction="none"] { animation: lg-stack-fade var(--lg-duration-release) var(--lg-ease); }
@media (prefers-reduced-motion: reduce) {
  .lg-stack-screen { animation: lg-stack-fade var(--lg-duration-release) var(--lg-ease) !important; }
}

/* The toast's close button. Drawn small — the message is what matters — but the hit region is
   the shared 44 that `.lg-button::after` gives every button on a coarse pointer. */
.lg-toast-dismiss { flex: 0 0 auto; margin-inline-start: calc(var(--lg-space-1) * -1); opacity: .6; }
@media (hover: hover) { .lg-toast-dismiss:hover { opacity: 1; } }

/* A badge is a custom element, and Increase Contrast asks custom elements for a border. White
   on the notification red measures 4.6:1 and passes AA on its own, so this is consistency:
   every other surface grows an edge here, and one that does not looks forgotten. */
@media (prefers-contrast: more) {
  .lg-badge { border: 1px solid var(--lg-label); }
}
/* `data-lg-contrast`, not `data-contrast`: the material stamps the former, so the latter was a
   selector that could never match — the opt-in path had no border at all. */
[data-lg-contrast="more"] .lg-badge, .lg-badge[data-lg-contrast="more"] { border: 1px solid var(--lg-label); }

/* ---------- DisclosureGroup: a row that folds, on a real <details> ---------- */
/**
 * `interpolate-size` is what makes `auto` an animatable height, and `::details-content` is the
 * box the browser puts the folded content in — together they are the whole animation, done by
 * the browser, on the real `<details>` that find-in-page and the accessibility tree already
 * understand.
 *
 * This was measured and published by the component and then never used: the element carried a
 * `--lg-disclosure-height` that no rule read, the chevron rotated, and the body appeared in one
 * frame. The custom property is the fallback target — where `interpolate-size` is missing, the
 * component measures and this animates to a length instead of to `auto`, which is the same
 * animation by another route. Where `::details-content` itself is missing there is no box to
 * animate and it opens at once; that is stated rather than pretended away.
 */
.lg-disclosure { border-radius: var(--lg-radius-m); background: var(--lg-bg-grouped-2); overflow: hidden;
  interpolate-size: allow-keywords; }
.lg-disclosure::details-content {
  block-size: 0; overflow: clip;
  transition: block-size var(--lg-duration-layout) var(--lg-ease-out),
    content-visibility var(--lg-duration-layout) allow-discrete; }
.lg-disclosure[open]::details-content { block-size: var(--lg-disclosure-height, auto); }
.lg-disclosure-summary { display: flex; align-items: center; gap: var(--lg-space-3);
  min-height: var(--lg-hit-min); padding: var(--lg-space-2) var(--lg-space-4); cursor: pointer;
  list-style: none; user-select: none; -webkit-user-select: none;
  font-family: var(--lg-font-text); color: var(--lg-label);
  /* The hover and press tints were already there and arrived between frames. A summary is a
     row you press, and the rule is the same one list rows follow. */
  transition: background var(--lg-duration-press) var(--lg-ease); }
.lg-disclosure-summary:active { background: var(--lg-fill-tertiary); }
/* The UA triangle is replaced, not hidden by opacity: two markers is worse than the wrong one. */
.lg-disclosure-summary::-webkit-details-marker { display: none; }
.lg-disclosure-summary::marker { content: ''; }
.lg-disclosure-summary:focus-visible { outline: var(--lg-focus-width) solid var(--lg-focus); outline-offset: calc(var(--lg-focus-offset) * -1); }
@media (hover: hover) { .lg-disclosure-summary:hover { background: var(--lg-fill-quaternary); } }
.lg-disclosure-labels { display: flex; flex-direction: column; gap: 1px; flex: 1; min-width: 0; }
.lg-disclosure-label { font-size: var(--lg-text-body-size); line-height: var(--lg-text-body-leading); }
.lg-disclosure-secondary { font-size: var(--lg-text-footnote-size); line-height: var(--lg-text-footnote-leading); color: var(--lg-label-secondary); }
.lg-disclosure-chevron { flex: 0 0 auto; color: var(--lg-label-tertiary); rotate: 90deg;
  transition: rotate var(--lg-duration-spring) var(--lg-spring); }
.lg-disclosure[data-open="true"] .lg-disclosure-chevron { rotate: 270deg; }
.lg-disclosure-body { padding: 0 var(--lg-space-4) var(--lg-space-4); }

/* ---------- PageControl: where you are in an ordered set ---------- */
.lg-page-control { display: inline-flex; width: fit-content; padding: var(--lg-space-2) var(--lg-space-3); touch-action: none; }
.lg-page-control > .lg-content { display: flex; align-items: center; gap: var(--lg-space-1); }
.lg-page-control[data-orientation="vertical"] > .lg-content { flex-direction: column; }
/* The dot is drawn at 8px and hit at 44, the same way every other small control here works. */
.lg-page-dot { position: relative; display: grid; place-items: center; width: 18px; height: 18px;
  border: 0; padding: 0; background: transparent; cursor: pointer; }
.lg-page-dot > span { width: 7px; height: 7px; border-radius: 999px; background: var(--lg-glass-fg-secondary);
  opacity: .42; transition: opacity var(--lg-duration-release) var(--lg-ease), scale var(--lg-duration-spring) var(--lg-spring); }
.lg-page-dot[aria-selected="true"] > span { opacity: 1; scale: 1.15; }
.lg-page-dot:focus-visible { outline: var(--lg-focus-width) solid var(--lg-focus); outline-offset: -1px; border-radius: 999px; }
@media (hover: hover) {
  .lg-page-dot:not([aria-selected="true"]):hover > span { opacity: .7; }
  /* The current dot had nothing: it is already at full opacity, and the rule above excludes
     it. It grows instead — it is the dot the gesture is carried from. */
  .lg-page-dot[aria-selected="true"]:hover > span { scale: 1.35; }
}
/* The touch region grows on the **cross** axis only.
   Growing it on both, the way a standalone button does, makes each dot's 44px square overlap
   its neighbours': the dots are 18px apart, so dot 2's region covers dot 1's centre entirely,
   and being later in the DOM it wins the hit test. Measured: tapping the first dot selected
   the second. Along the row the dots are adjacent targets and share the axis between them —
   which is fine, because the row is draggable and nobody has to hit one exactly. */
@media (pointer: coarse) {
  .lg-page-dot::after { content: ''; position: absolute; inset-block-start: 50%; inset-inline-start: 50%;
    translate: -50% -50%; width: 100%; height: var(--lg-hit-min); }
  .lg-page-control[data-orientation="vertical"] .lg-page-dot::after { width: var(--lg-hit-min); height: 100%; }
}
@media (forced-colors: active) {
  .lg-page-dot > span { background: ButtonText; opacity: 1; }
  .lg-page-dot[aria-selected="true"] > span { background: Highlight; }
}

/* ---------- SplitView: columns in a regular environment, a stack in a compact one ---------- */
.lg-split { display: flex; align-items: stretch; min-width: 0; min-height: 0; }
/**
 * Scrolling moved inside, so a column can be closed without its contents reflowing.
 *
 * While the width animates to zero the text inside would otherwise re-wrap on every frame —
 * a column that rearranges itself on the way out reads as a bug, not as a column closing. The
 * inner box keeps the width the column was given and is clipped by it; only the clip moves.
 */
.lg-split-column { min-width: 0; min-height: 0; overflow: hidden; }
.lg-split-inner { height: 100%; overflow: auto; }
.lg-split-column[data-column="sidebar"] > .lg-split-inner { width: var(--lg-split-sidebar, 260px); }
.lg-split-column[data-column="inspector"] > .lg-split-inner { width: var(--lg-split-inspector, 300px); }
/* `0 1`, not `0 0`: the columns keep their widths until there is nothing left to give, and
   then they give. With a rigid basis a split view narrower than sidebar + inspector overflowed
   its own box — measured at 161px inside a 320px container — which is the one thing a layout
   container must never do, because its parent has no idea the columns exist. The content column
   shrinks first (it has the flexible basis), so the sidebar only narrows once it has to. */
.lg-split-column[data-column="sidebar"] { flex: 0 1 var(--lg-split-sidebar, 260px); }
/* Basis `0`, not `auto`: with `auto` the content column's hypothetical size is its text's
   max-content width, which over-constrains the line even in a wide view — and the shrink was
   then shared with the sidebar, so a 260px sidebar rendered at 231 with 200px of room to
   spare. At zero the content column absorbs the whole difference and the sidebar keeps the
   width it was given until there is genuinely nothing left. */
.lg-split-column[data-column="content"] { flex: 1 1 0%; }
.lg-split-column[data-column="inspector"] { flex: 0 1 var(--lg-split-inspector, 300px); }
/**
 * Closing and opening a column.
 *
 * `flex-basis` is a layout property and animating one is normally the thing not to do — but
 * here the layout change *is* the message ("the column went that way"), and no transform gives
 * the other columns their space back.
 *
 * `visibility` rather than `display: none`, and that choice is the whole design: a visibility
 * transition holds `visible` for the full duration on the way out and flips to `visible`
 * immediately on the way in, so both directions animate with no `@starting-style` — and
 * without one, the first paint is not an entrance. A split view that unfolds itself every time
 * the page loads would be motion nobody asked for. `visibility: hidden` is also what takes the
 * closed column out of the tab order and out of the accessibility tree; a zero-width column
 * whose buttons could still be tabbed into would be a trap with nothing visible in it.
 *
 * After the per-column `flex` shorthands above, because `flex` sets `flex-basis` too and the
 * later rule of equal specificity is the one that wins — the first version of this sat before
 * them and animated an opacity nobody could see while the width never moved.
 *
 * And gated on `data-toggling`, which the component sets only while a column is being shown or
 * hidden. Declared unconditionally, the same transition also caught every *resize*: the
 * sidebar chased the divider a quarter of a second behind the pointer, and the arrow keys
 * looked like they did nothing. A width the reader is setting has to be exactly as fast as
 * they are; a column appearing or going away is the only part that is worth watching.
 */
.lg-split-column[data-toggling="true"] {
  transition: flex-basis var(--lg-duration-layout) var(--lg-ease),
    opacity var(--lg-duration-exit) var(--lg-ease), visibility var(--lg-duration-layout); }
.lg-split-column[data-hidden="true"] { flex-basis: 0; opacity: 0; visibility: hidden; }
/* "Keep the divider visible": a hairline that is always there, with a grab region around it
   wider than the line — the line is 1px and a pointer target is not. */
.lg-split-divider { position: relative; flex: 0 0 1px; background: var(--lg-separator);
  cursor: col-resize; touch-action: none;
  /* It brightens under the pointer and again while it is being dragged; both were instant.
     A hairline that snaps between two greys reads as a repaint, not as a control answering. */
  transition: background var(--lg-duration-press) var(--lg-ease); }
/* The grab region, sized by whatever is pointing at it: 44 for a finger, 24 for a cursor.
   11px was neither, and `pnpm test:matrix` reported it as a target nobody can hit once the
   desktop rows started asking the 24px question. Twelve pixels of slop either side is less
   than the twenty-two a finger has always had here. */
.lg-split-divider::before { content: ''; position: absolute; inset-block: 0;
  inset-inline-start: 50%; translate: -50% 0; width: var(--lg-hit-min); }
.lg-split-divider:focus-visible { outline: var(--lg-focus-width) solid var(--lg-focus); outline-offset: 1px; }
@media (hover: hover) { .lg-split-divider:hover { background: var(--lg-label-tertiary); } }
.lg-split[data-dragging="true"] { user-select: none; -webkit-user-select: none; cursor: col-resize; }
.lg-split[data-dragging="true"] .lg-split-divider { background: var(--lg-accent); }
@media (forced-colors: active) { .lg-split-divider { background: ButtonText; } }

/* ---------- Inspector: the trailing column ---------- */
/* Content layer, not glass: it is a region of the window, and a translucent panel between the
   reader and the thing they are editing helps nobody. */
.lg-inspector { display: flex; flex-direction: column; min-width: 0;
  background: var(--lg-bg-grouped); border-inline-start: 1px solid var(--lg-separator); }
.lg-inspector-title { padding: var(--lg-space-4) var(--lg-space-4) var(--lg-space-2);
  font-size: var(--lg-text-subhead-size); font-weight: var(--lg-weight-semibold); color: var(--lg-label); }
.lg-inspector-body { flex: 1; min-height: 0; overflow: auto; padding: var(--lg-space-2) var(--lg-space-4) var(--lg-space-4);
  display: flex; flex-direction: column; gap: var(--lg-space-4); }
/* Dense controls: rounded rectangles rather than capsules, which at this width are mostly gap. */
.lg-inspector .lg-button { --lg-radius: var(--lg-radius-s); border-radius: var(--lg-radius-s); }

/* ---------- The small additions of 0.0.2's 1.5 ---------- */

/* Button icon slots. A fixed gap, which is the reason they are slots and not children: the
   space between a glyph and its words is a system value, not a per-caller decision. */
.lg-button-icon { display: inline-flex; flex: 0 0 auto; align-items: center; }
.lg-button .lg-content:has(.lg-button-icon) { gap: var(--lg-space-2); }
.lg-icon-button .lg-button-icon { margin: 0; }

/* Slider tick marks. Under the fill, so a passed mark reads as passed rather than as a hole
   punched through the accent. */
.lg-slider-marks { position: absolute; inset-block-start: calc(50% - 1px); inset-inline: 13px; height: 2px; pointer-events: none; }
.lg-slider-mark { position: absolute; inset-block-start: 0; inset-inline-start: calc(var(--lg-mark) * 100%);
  translate: -50% 0; width: 2px; height: 2px; border-radius: 999px;
  background: var(--lg-label-tertiary); opacity: .9; }
.lg-slider-mark[data-passed="true"] { background: var(--lg-accent-contrast); opacity: .5; }
@media (forced-colors: active) { .lg-slider-mark { background: ButtonText; } }

/* Toast tone. The glyph carries it as well as the colour — a tone nobody can see is a tone
   that is not there. */
.lg-toast-icon { display: inline-flex; flex: 0 0 auto; align-items: center; }
.lg-toast[data-tone="success"] .lg-toast-icon { color: var(--lg-green); }
.lg-toast[data-tone="warning"] .lg-toast-icon { color: var(--lg-orange); }
.lg-toast[data-tone="error"] .lg-toast-icon { color: var(--lg-red); }

/* Field sizes and the multi-line form. The *control* gets smaller; the text does not, because
   anything under 16px makes iOS Safari zoom the page on focus. */
/* The input's own line box is 22px of leading plus 8px of padding either side — 38 — so a
   `min-height` of 36 was a floor the content was already above, and the small field rendered
   two pixels taller than every page that documents it says. The padding is what has to give;
   the 16px type does not, because anything smaller makes iOS Safari zoom on focus. */
.lg-field[data-control-size="small"] .lg-field-box { min-height: var(--lg-height-field-small); }
.lg-field[data-control-size="small"] .lg-field-input { padding-block: calc(var(--lg-field-padding-block) - 1px); }
.lg-field[data-control-size="large"] .lg-field-box { min-height: var(--lg-height-field-large); }
.lg-field[data-multiline="true"] .lg-field-box { min-height: 0; align-items: flex-start; padding-block: var(--lg-space-2); }
.lg-field[data-multiline="true"] textarea.lg-field-input { resize: vertical; min-height: 4lh; line-height: 1.45; }
.lg-field[data-multiline="true"] textarea.lg-field-input[data-autosize="true"] { resize: none; field-sizing: content; min-height: 2lh; max-height: 12lh; }

/* Search suggestions. A listbox under the field, in the content layer — it belongs to the
   field rather than floating over the page, and glass here would be glass on glass. */
.lg-search { position: relative; }
.lg-search-suggestions { position: absolute; inset-inline: 0; inset-block-start: calc(100% + var(--lg-space-1));
  z-index: var(--lg-z-popover); margin: 0; padding: var(--lg-space-1); list-style: none;
  max-height: 44vh; overflow-y: auto; overscroll-behavior: contain;
  border-radius: var(--lg-radius-m); background: var(--lg-bg-grouped-2);
  box-shadow: var(--lg-glass-shadow-large); border: 1px solid var(--lg-separator); }
.lg-search-suggestion { display: flex; align-items: center; gap: var(--lg-space-2);
  min-height: var(--lg-hit-min); padding: var(--lg-space-1) var(--lg-space-3);
  border-radius: var(--lg-radius-s); cursor: pointer; color: var(--lg-label);
  font-size: var(--lg-text-subhead-size); }
.lg-search-suggestion[aria-selected="true"] { background: var(--lg-fill-tertiary); }
.lg-search-suggestion-icon { display: inline-flex; flex: 0 0 auto; color: var(--lg-label-secondary); }
@media (forced-colors: active) {
  .lg-search-suggestion[aria-selected="true"] { background: Highlight; color: HighlightText; }
}

/* ---------- ContextMenu ---------- */
/* A plain wrapper with a real box. `display: contents` would be tidier in the layout and is
   wrong: it takes the element out of the accessibility tree and leaves nothing to measure when
   the menu is opened from the keyboard and has no pointer position to open at.
   `-webkit-touch-callout` stops iOS putting its own long-press sheet over this one. */
.lg-context-region { min-width: 0; -webkit-touch-callout: none; }
.lg-context-menu { transform-origin: var(--lg-origin-x, 0%) var(--lg-origin-y, 0%); }

/* ---------- Grid: same-kind items that reflow by the space they have ---------- */
/* `auto-fill` with a floor rather than a breakpoint list: the grid is told how small an item
   may get and works the columns out, so it is right inside a sidebar and full width without
   either being written down. `min()` keeps a single narrow column from overflowing when the
   container is narrower than one item. */
.lg-grid { display: grid; gap: var(--lg-grid-gap, 16px);
  grid-template-columns: repeat(auto-fill, minmax(min(var(--lg-grid-min, 220px), 100%), 1fr)); }
.lg-grid[data-fixed="true"] { grid-template-columns: repeat(var(--lg-grid-columns), minmax(0, 1fr)); }
/* Items may be anything, so the grid does not restyle them; it only stops them overflowing.
   The room a focus ring needs is the gap, which is floored at 8 in the component. */
.lg-grid > * { min-width: 0; }

/* ---------- Form: grouped, labelled rows ---------- */
.lg-form { display: flex; flex-direction: column; gap: var(--lg-space-8); font-family: var(--lg-font-text); color: var(--lg-label); }
.lg-form-section { display: flex; flex-direction: column; gap: var(--lg-space-2); }
.lg-form-header { padding-inline: var(--lg-space-4); }
.lg-form-footer { padding-inline: var(--lg-space-4); }
.lg-form-group { display: flex; flex-direction: column; border-radius: var(--lg-radius-m);
  background: var(--lg-bg-grouped-2); overflow: hidden; }
.lg-form-row { position: relative; }
.lg-form-row + .lg-form-row::before { content: ''; position: absolute; inset-block-start: 0;
  inset-inline: var(--lg-space-4) 0; height: 1px; background: var(--lg-separator); }
