  padding-block: var(--lg-space-3); }
.lg-form-row-labels { display: flex; flex-direction: column; gap: 1px; flex: 1; min-width: 0; }
.lg-form-row-control { display: flex; align-items: center; justify-content: flex-end; flex: 0 0 auto; min-width: 0; }
