/* Above the box, which is where macOS puts it. Headline weight at body size: it is a label for
   a region, not a heading in the document, and giving it a heading's size would make the page's
   outline read as though a box were a section. */
.lg-groupbox-title { font: var(--lg-weight-semibold) var(--lg-text-subhead-size)/var(--lg-text-subhead-leading) var(--lg-font-text);
  color: var(--lg-label); }
