.lg-groupbox[data-variant="outline"] > .lg-groupbox-body { border: 1px solid var(--lg-separator); }

.lg-path { min-width: 0; font-family: var(--lg-font-text); }
.lg-path-list { display: flex; align-items: center; flex-wrap: nowrap; gap: var(--lg-space-1);
