.lg-panel-title { flex: 1; min-width: 0; overflow: hidden; text-overflow: ellipsis; white-space: nowrap;
  font-size: var(--lg-text-subhead-size); line-height: var(--lg-text-subhead-leading);
  font-weight: var(--lg-weight-semibold); }
.lg-panel-accessory { display: inline-flex; align-items: center; gap: var(--lg-space-1); }
