/* The single stylesheet consumers import.
   Order matters: the tokens define the variables everything else reads. */
@import './tokens.css';
@import './components.css';

/* ==========================================================================
   Liquid Glass UI — token layer
   Sources: Apple HIG (Color, Typography, Layout, Materials), WWDC25 219 / 356.
   Values are design references for an independent study; they are NOT Apple's
   shipped constants and no Apple font, symbol or wallpaper asset is included.

   Theming is attribute-driven, not `color-scheme`-driven: the provider stamps
   `data-lg-theme="light|dark"` on every surface, so a dark toolbar can sit in a
   light page. `light-dark()` cannot express that, hence the explicit blocks.
   ========================================================================== */
@layer lg.tokens {

/* --------------------------------------------------------------------------
   1. Non-color foundations
   -------------------------------------------------------------------------- */
:root {
  /* Fonts. -apple-system resolves to SF only on Apple devices; everywhere else
     it falls back to Segoe UI / Roboto, whose metrics differ. SF is NOT bundled
     — self-hosting it on the web is outside its licence. */
  --lg-font-text: -apple-system, BlinkMacSystemFont, "Segoe UI", Roboto, "PingFang SC", "Microsoft YaHei", sans-serif;
  --lg-font-display: var(--lg-font-text);
  --lg-font-rounded: ui-rounded, "SF Pro Rounded", var(--lg-font-text);
  --lg-font-mono: ui-monospace, SFMono-Regular, "SF Mono", Menlo, Consolas, monospace;
  --lg-font: var(--lg-font-text); /* legacy alias */

  /* Dynamic Type. One multiplier over the whole scale — Apple compresses large
     titles slightly at accessibility sizes, so this is an approximation, but it
     is the axis that matters: every layout must still reflow at AX5.
     Root attribute: data-lg-text-size="xs|s|m|l|xl|xxl|xxxl|ax1..ax5". */
