  /* iOS text styles at the Large (default) content size.
     Tracking is in em (1/1000 em column of the HIG table) so it survives scaling. */
  --lg-text-largetitle-size: calc(34px * var(--lg-text-scale));
  --lg-text-largetitle-leading: calc(41px * var(--lg-text-scale));
  --lg-text-largetitle-tracking: .012em;
  --lg-text-title1-size: calc(28px * var(--lg-text-scale));
  --lg-text-title1-leading: calc(34px * var(--lg-text-scale));
  --lg-text-title1-tracking: .014em;
  --lg-text-title2-size: calc(22px * var(--lg-text-scale));
  --lg-text-title2-leading: calc(28px * var(--lg-text-scale));
  --lg-text-title2-tracking: -.012em;
  --lg-text-title3-size: calc(20px * var(--lg-text-scale));
  --lg-text-title3-leading: calc(25px * var(--lg-text-scale));
  --lg-text-title3-tracking: -.023em;
  --lg-text-headline-size: calc(17px * var(--lg-text-scale));
  --lg-text-headline-leading: calc(22px * var(--lg-text-scale));
  --lg-text-headline-tracking: -.026em;
  --lg-text-body-size: calc(17px * var(--lg-text-scale));
  --lg-text-body-leading: calc(22px * var(--lg-text-scale));
  --lg-text-body-tracking: -.026em;
  --lg-text-callout-size: calc(16px * var(--lg-text-scale));
  --lg-text-callout-leading: calc(21px * var(--lg-text-scale));
  --lg-text-callout-tracking: -.020em;
  --lg-text-subhead-size: calc(15px * var(--lg-text-scale));
  --lg-text-subhead-leading: calc(20px * var(--lg-text-scale));
  --lg-text-subhead-tracking: -.016em;
  --lg-text-footnote-size: calc(13px * var(--lg-text-scale));
  --lg-text-footnote-leading: calc(18px * var(--lg-text-scale));
  --lg-text-footnote-tracking: -.006em;
  --lg-text-caption1-size: calc(12px * var(--lg-text-scale));
  --lg-text-caption1-leading: calc(16px * var(--lg-text-scale));
  --lg-text-caption1-tracking: 0em;
  /* 11pt is the HIG floor for readable text. Nothing may go below caption2. */
  --lg-text-caption2-size: calc(11px * var(--lg-text-scale));
  --lg-text-caption2-leading: calc(13px * var(--lg-text-scale));
  --lg-text-caption2-tracking: .006em;

  --lg-weight-regular: 400;
  --lg-weight-medium: 500;
  --lg-weight-semibold: 600;
  --lg-weight-bold: 700;

  /* Spacing: 4pt grid */
  --lg-space-1: 4px;  --lg-space-2: 8px;  --lg-space-3: 12px; --lg-space-4: 16px;
  --lg-space-5: 20px; --lg-space-6: 24px; --lg-space-8: 32px; --lg-space-10: 40px;

  /* Layout metrics */
  /* The layout margin for the current size class. It switches itself at the breakpoint below,
     so a caller writes var(--lg-margin) once rather than restating the media query. */
  --lg-margin: 16px;            /* compact */
  --lg-margin-regular: 20px;    /* regular, kept for anything that wants the value explicitly */
  --lg-hit-min: 44px;           /* minimum hit region, 44x44pt */
  /**
   * How wide that region is allowed to grow — a question about the pointer, and the one metric
   * here that is *not* answered by the table below.
   *
   * A fingertip is round and imprecise, so it needs both axes. A cursor is one pixel and needs
   * the block axis only: `layout-matrix.spec.ts` measured five layout pages scrolling 53–244px
   * sideways in RTL when every button carried a 44px-wide absolutely positioned region, and a
   * horizontal scrollbar is a real defect where an invisible hit region is not.
   *
   * The two questions come apart at phone width with a mouse: the *heights* are the touch ones
   * there, because a 390px window is a phone-shaped layout — but the thing pointing at it is
   * still a cursor. So this follows `(pointer: coarse)`, with `platform` able to override it in
   * both directions like everything else. Default 0: growing sideways is the exception.
   */
  --lg-hit-width: 0px;
  /**
   * Control heights, as tokens rather than as numbers in the components.
   *
   * They are here and not in the stylesheet's own rules because the desktop block below has to
   * be able to restate all of them in one place, and because `--lg-control-height` is written
   * onto every glass surface: if that came out of JavaScript, a server-rendered page would
   * arrive with touch metrics and re-lay itself out the moment it hydrated. It is a `var()`
   * reference, so the answer is decided by the same CSS that decides everything else.
   */
  --lg-height-compact: 36px;
  --lg-height-comfortable: 44px;
  --lg-height-small: 32px;
  --lg-height-large: 50px;
  --lg-height-extra-large: 60px;
  --lg-height-field-small: 36px;
  --lg-height-field-large: 52px;
  /* Text inside a field. Its own token because the floor under it is iOS Safari's zoom-on-focus
     rule, not a design decision — see `.lg-field-input`. */
  --lg-field-font: max(16px, var(--lg-text-body-size));
  /* A control's label: one step down from the text around it, on both platforms. 15px against
     a 36px desktop button is what Ant Design, MUI, Radix and Chakra all draw at 14 against a
     32–36px one, and it leaves the box room to be a box. */
  --lg-control-font: var(--lg-text-subhead-size);
  /* Air above and below the text in a field, for the sizes whose height is not pinned. */
  --lg-field-padding-block: var(--lg-space-2);
  --lg-readable: 672px;         /* readable content guide */
  --lg-sidebar-width: 260px;

  /* Shapes. Three types (WWDC25/356): fixed, capsule (height/2), concentric
     (parent radius - inset). --lg-radius-container / --lg-concentric-inset are
     the inputs to the concentric helper. */
  --lg-radius-xs: 6px;  --lg-radius-s: 10px;  --lg-radius-m: 14px;
  --lg-radius-l: 20px;  --lg-radius-xl: 26px; --lg-radius-xxl: 34px;
  --lg-radius-capsule: 9999px;
  --lg-radius-sheet: 38px;      /* nests into the display corner */
  --lg-radius-window: 24px;
  --lg-radius-container: var(--lg-radius-xl);
  --lg-concentric-inset: 0px;

  /* Stacking bands. New overlays pick a band, they do not invent numbers. */
  --lg-z-content: 0; --lg-z-scroll-edge: 10; --lg-z-sidebar: 15; --lg-z-tabbar: 20;
  --lg-z-sheet-backdrop: 30; --lg-z-sheet: 31; --lg-z-menu: 40; --lg-z-alert: 41; --lg-z-toast: 60;

  /* Motion. Press is immediate; release springs back with a small overshoot.
     Spring curves sampled from a damped oscillator (Chrome linear() easing). */
  --lg-duration-press: 90ms;
  --lg-duration-release: 220ms;
  --lg-duration-layout: 280ms;
  --lg-duration-spring: 520ms;
  --lg-duration-overlay: 360ms;
  /* Leaving is quicker than arriving — the thing is already understood, so the exit only has
     to say "it is going", not introduce anything. Anything that has to be taken out of the
     tree by JavaScript afterwards reads the same number from `EXIT_MS` in `leave.ts`; the two
     are asserted equal in `tests/core/stylesheet.test.mjs`. */
  --lg-duration-exit: 220ms;
  --lg-ease: cubic-bezier(.2,.8,.2,1);
  --lg-ease-out: cubic-bezier(.16,1,.3,1);
  --lg-spring: linear(0, .008 1.1%, .03 2.2%, .118 4.6%, .43 9.6%, .657 13.4%, .84 17.4%, .94 20.7%, 1.006 23.9%, 1.05 27.5%, 1.072 31.5%, 1.07 35.9%, 1.05 41.4%, 1.011 51.3%, .995 61.4%, .994 70.3%, 1.001 87.4%, 1);
  --lg-spring-soft: linear(0, .011 1.6%, .045 3.4%, .164 7%, .49 14%, .71 19.4%, .866 24.8%, .955 30.3%, 1.004 36%, 1.02 42.2%, 1.018 49.3%, 1.005 61.3%, .999 78%, 1);
  --lg-spring-bouncy: linear(0, .01 .9%, .043 2%, .152 4.3%, .49 9.2%, .74 12.9%, .91 16.2%, 1.05 19.8%, 1.13 23.4%, 1.16 26.4%, 1.15 29.5%, 1.11 33.6%, 1.03 40.8%, .985 47.3%, .972 53.2%, .985 63%, 1.004 75.2%, 1);

  /* Gel flex: glass "instantly flexes" on touch and moves in tandem with the
     interaction. Independent glass grows toward the pointer; shared pills lift
     out of their bar. */
  --lg-press-scale: 1.06;
  --lg-press-scale-shared: 1.07;
  --lg-hover-scale: 1.015;
  /**
   * How much of a drag's elastic stretch is actually drawn.
   *
   * The HIG's motion page: Liquid Glass "responds more emphatically to direct touch, and more
   * subtly when you use a trackpad or a mouse". A finger is the thing itself and the material
   * answers it like a material; a cursor is an instrument several inches away, and the same
   * amount of squash under it reads as the interface being loose rather than alive. `pull.ts`
   * multiplies by this rather than each control passing a different number.
   */
  --lg-stretch-gain: 1;

  /* Glass geometry.
     Blur, saturation, refraction and edge width are NOT declared here: they vary per
     material x size and are the `materialTokens` table in `packages/tokens/src/index.ts`,
     which the surface writes out as an inline `--lg-backdrop`. Declaring them twice would
     mean a value you can edit that quietly has no effect. */
  /* One ring, one width, one offset. Two stacked 3px rings on a field read as a bug. */
  --lg-focus-width: 2px;
  --lg-focus-offset: 2px;

  --lg-glass-rim-width: 1px;
  /* Virtual light source. The pointer overwrites this per element; the value here is where
     the highlight rests. Registered as an <angle> in styles.css so it can be transitioned. */
  --lg-light-angle: 145deg;
  --lg-glass-contrast: 1.05;       /* re-level the backdrop instead of brightening it */
  --lg-material-blur: 30px;        /* standard materials, content layer */
}

/* Dynamic Type steps. Body 17pt is the reference; ratios follow the HIG size
   tables (xSmall 14 -> xxxLarge 23, AX1 28 -> AX5 53). */
:root[data-lg-text-size="xs"]   { --lg-text-scale: .824; }
:root[data-lg-text-size="s"]    { --lg-text-scale: .882; }
:root[data-lg-text-size="m"]    { --lg-text-scale: .941; }
:root[data-lg-text-size="l"]    { --lg-text-scale: 1; }
:root[data-lg-text-size="xl"]   { --lg-text-scale: 1.118; }
:root[data-lg-text-size="xxl"]  { --lg-text-scale: 1.235; }
:root[data-lg-text-size="xxxl"] { --lg-text-scale: 1.353; }
:root[data-lg-text-size="ax1"]  { --lg-text-scale: 1.647; }
:root[data-lg-text-size="ax2"]  { --lg-text-scale: 1.941; }
:root[data-lg-text-size="ax3"]  { --lg-text-scale: 2.353; }
:root[data-lg-text-size="ax4"]  { --lg-text-scale: 2.765; }
:root[data-lg-text-size="ax5"]  { --lg-text-scale: 3.118; }

/* --------------------------------------------------------------------------
   Desktop metrics
   --------------------------------------------------------------------------
   Everything above this line is the iOS table. On a machine with a mouse, one half of it is
   the wrong table and the other half is right, and this block used to get that backwards.

   It held the AppKit numbers — regular control 22pt, Body 13/16, Large Title 26/32 — on the
   reasoning that a cursor is not a fingertip. That much is true, and the control heights below
   still say so. Applying it to the *type* was the mistake, for two reasons that are checkable
   rather than a matter of taste:

   1. **A browser page is not an AppKit window.** 13pt Body is the size of a table row in a
      native inspector, next to a native menu bar, in a window the person sized themselves. A
      documentation page or a web application is read the way a web page is read, and the
      browser's own default body size is 16px — the AppKit table starts three pixels under the
      floor every other page on the machine is using.
   2. **Apple does not use it on the web either.** developer.apple.com, on a desktop with a
      mouse, draws Body at 17/25, its section-navigation rows at 44 and 30, and the page title
      at 48/52 — the iOS-sized table, not the AppKit one. Measured, not remembered.

   So does everyone else. Eleven component-library documentation sites at 1600px, measured the
   same way: body text 16px at nine of them (Ant Design and Naive UI use 14); the default
   button 32–36px tall with a 14px label (Ant 32, MUI 36.5, Radix 32, shadcn 30, Chakra 36–40,
   Primer 28–32, Element Plus 32, Naive 34); a call-to-action button 40–42; page titles 30–44.
   A 22px button carrying a 12px label — which is what this block used to produce — is not in
   the range, and at a desk it reads as an interface that failed to finish loading.

   What stays, and why the split is where it is: **size the hand, not the eye.** A pointer is
   more precise than a fingertip, so the *controls* come down from the 44px touch floor to a
   pointer-sized 36. Eyesight does not improve when a mouse is plugged in, so the *type scale*
   is left exactly as it is — one table, no desktop copy of it, nothing to keep in step. That
   also makes Dynamic Type's behaviour the same on both platforms instead of something this
   block had to promise separately.

   Written twice on purpose — once for the media query, once for `[data-lg-platform]` — for
   the same reason the Increase Contrast palette is, and with the same guard:
   `tests/core/stylesheet.test.mjs` asserts the two are declaration-for-declaration identical.
   The media query excludes `[data-lg-platform="touch"]` rather than there being a third block
   restating the iOS numbers: an explicit override has to win in *both* directions — a setting
   that can only be turned on is half a switch — and the way to do that without a third copy
   of the table is to let the one override turn the query off.

   `(min-width: 768px)` as well as `(pointer: fine)`: a Surface or an iPad with a trackpad
   reports a fine pointer at phone width, and a 36px control there is the wrong answer to the
   right question.

   The heights themselves: **36** regular / **32** compact / **28** small is the range the web
   has settled on for a pointer, and it is also the range a 15px control label fits in without
   the box gripping the text. 44 and 52 are the two sizes above it — a call to action and a
   hero — which is where the measured 40–42px buttons on Mantine and Radix land. A field is
   the same height as a button of the same name, because a form row that mixes the two and
   misses by four pixels is the most visible kind of wrong. */
@media (pointer: fine) and (min-width: 768px) {
  :root:not([data-lg-platform="touch"]) {
    --lg-height-compact: 32px;
    --lg-height-comfortable: 36px;
    --lg-height-small: 28px;
    --lg-height-large: 44px;
    --lg-height-extra-large: 52px;
    --lg-height-field-small: 32px;
    --lg-height-field-large: 44px;
    /* WCAG 2.2 Target Size (Minimum) is 24×24 for a pointer. Every height above clears it, so
       the region `components.css` draws is enforcement rather than rescue — which is the point
       of writing the floor down: it goes on holding when a caller sets a smaller height. */
    --lg-hit-min: 24px;
    /* 8px each side would make a small field 38px tall — taller than the large one was. */
    --lg-field-padding-block: 5px;
    --lg-margin: 20px;
    --lg-press-scale: 1.03;
    --lg-press-scale-shared: 1.035;
    --lg-stretch-gain: .55;
  }
}
:root[data-lg-platform="desktop"] {
  --lg-height-compact: 32px;
  --lg-height-comfortable: 36px;
  --lg-height-small: 28px;
  --lg-height-large: 44px;
  --lg-height-extra-large: 52px;
  --lg-height-field-small: 32px;
  --lg-height-field-large: 44px;
  --lg-hit-min: 24px;
  --lg-field-padding-block: 5px;
  --lg-margin: 20px;
  --lg-press-scale: 1.03;
  --lg-press-scale-shared: 1.035;
  --lg-stretch-gain: .55;
}

/* The one metric keyed to the pointer rather than to the table above — see `--lg-hit-width`.
   Two rules and not one block per platform, because there is only one declaration to switch
   and the default is already the answer for a cursor. */
@media (pointer: coarse) {
  :root:not([data-lg-platform="desktop"]) { --lg-hit-width: var(--lg-hit-min); }
}
:root[data-lg-platform="touch"] { --lg-hit-width: var(--lg-hit-min); }

/* --------------------------------------------------------------------------
   2. Light appearance
   -------------------------------------------------------------------------- */
:root,
[data-lg-theme="light"] {
  /* System colors */
  --lg-red: rgb(255 56 60);      --lg-orange: rgb(255 141 40);  --lg-yellow: rgb(255 204 0);
  --lg-green: rgb(52 199 89);    --lg-mint: rgb(0 200 179);     --lg-teal: rgb(0 195 208);
  --lg-cyan: rgb(0 192 232);     --lg-blue: rgb(0 136 255);     --lg-indigo: rgb(97 85 245);
  --lg-purple: rgb(203 48 224);  --lg-pink: rgb(255 45 85);     --lg-brown: rgb(172 127 94);
  --lg-gray: rgb(142 142 147);   --lg-gray2: rgb(174 174 178);  --lg-gray3: rgb(199 199 204);
  --lg-gray4: rgb(209 209 214);  --lg-gray5: rgb(229 229 234);  --lg-gray6: rgb(242 242 247);

  /* App accent. System blue by default: one accent, reserved for the primary action and
     for selection. Fork this single pair to re-brand — nothing else encodes the colour. */
  --lg-accent: var(--lg-blue);
  --lg-accent-contrast: #fff;
  /**
   * How to turn an accent into *ink* — a label painted in the accent, on a surface washed with
   * that same accent. The `tinted` button is the only case so far.
   *
   * System blue is a background colour. As text on a light page it measures 3.4:1, and over the
   * 16% wash the tinted variant paints under it, 2.75:1. Darkening the ink rather than
   * deepening the wash keeps the variant quiet, which is the whole reason to reach for it
   * instead of a prominent button.
   *
   * A recipe rather than a finished colour, deliberately: a custom property is substituted
   * where it is *declared*, so a `--lg-accent-ink` computed up here would keep resolving
   * against the root accent and a caller's `tint` — which sets `--lg-accent` on the button
   * itself — would silently get the default blue's ink. Mixed at the point of use, it follows
   * whatever accent that element actually has. */
  --lg-ink-toward: #000;
  --lg-ink-amount: 66%;

  /**
   * Semantic labels and separators.
   *
   * The secondary and tertiary alphas are a step stronger than the iOS table's. That table is
   * written for a phone held at arm's length with the display's own contrast; on a desktop
   * panel — and especially on the grouped background rather than on white — 60% grey body text
   * reads as washed out, and 30% is the colour of something switched off. The hierarchy is the
   * point, not the exact number: each step is still clearly quieter than the one above it.
   */
  --lg-label: rgb(0 0 0);
  /* .74 rather than a rounder number: it is the point at which this grey over the grouped
     surface measures past 4.5:1, which `appearance.spec.ts` checks from the composited pair
     rather than from the token. Below it, secondary body text on a card is under AA. */
  --lg-label-secondary: rgb(60 60 67 / .74);
  --lg-label-tertiary: rgb(60 60 67 / .46);
  --lg-label-quaternary: rgb(60 60 67 / .28);
  --lg-placeholder: var(--lg-label-tertiary);
  --lg-separator: rgb(60 60 67 / .29);
  --lg-separator-opaque: rgb(198 198 200);
  --lg-link: var(--lg-blue);

  /**
   * Backgrounds and fills.
   *
   * Not pure white. A full-brightness `#fff` panel is the single harshest thing a light
   * interface can put on a screen — on a bright display it is the whole panel glaring back —
   * and the grouped background above it then has to be darker still to be told apart. Stepping
   * the top surface down by three points keeps every layer distinguishable and takes the glare
   * off. It is still the lightest surface in the system, which is all "white" ever meant here.
   */
  --lg-bg: rgb(252 252 253);
  --lg-bg-secondary: rgb(240 240 245);
  --lg-bg-tertiary: rgb(252 252 253);
  --lg-bg-grouped: rgb(240 240 245);
  --lg-bg-grouped-2: rgb(252 252 253);
  --lg-bg-grouped-3: rgb(240 240 245);
  --lg-fill: rgb(120 120 128 / .20);
  --lg-fill-secondary: rgb(120 120 128 / .16);
  --lg-fill-tertiary: rgb(118 118 128 / .12);
  --lg-fill-quaternary: rgb(116 116 128 / .08);

  /* Standard materials (content layer). Thickness = opacity of the fill. */
  --lg-material-ultrathin: rgb(255 255 255 / .55);
  --lg-material-thin: rgb(255 255 255 / .70);
  --lg-material-regular: rgb(255 255 255 / .82);
  --lg-material-thick: rgb(255 255 255 / .93);

  /* Liquid Glass. Light is bent, not painted: one hairline rim plus a faint
     inner refraction ring. No body-wide gloss gradient, no second bevel. */
  --lg-glass-fg: rgb(0 0 0 / .88);
  --lg-glass-fg-secondary: rgb(0 0 0 / .64);
  --lg-glass-rim-hi: rgb(255 255 255 / .82);
  --lg-glass-rim-lo: rgb(0 0 0 / .17);

  /**
   * The pointer glow and the press flash.
   *
   * Per theme, because they are white light and what white light does depends entirely on what
   * it lands on. The same 28% that reads as a soft sheen over a light panel is a bright blob
   * over a dark one — the dark values are roughly a third of these.
   */
  --lg-shine-alpha: .26;
  --lg-shine-strong: .46;
  --lg-flash-alpha: .5;

  /**
   * The selection lens: the capsule that marks the chosen segment, tab or sidebar row.
   *
   * It has to be legible against the surface it slides on, and that surface is glass — which
   * in a light appearance is already near-white. A translucent white capsule with a white rim
   * on a white track is invisible, which is what "I cannot tell which one is selected" means.
   * So: opaque, with a hairline that is *darker* than the track and a shadow that lifts it.
   */
  --lg-lens-bg: rgb(255 255 255);
  /* The same capsule as an opacity, for the goo layer that draws it mid-drag. Split out so the
     hand-back cannot step brightness between the blob and the lens it becomes. */
  --lg-lens-alpha: 1;
  /**
   * The well the capsule slides in.
   *
   * Without it the capsule is white on a white-tinted glass track: measured, the fill differed
   * from its surround by 5 parts in 255, which is why "I cannot tell which one is selected" was
   * the first thing anyone said about it. A shadow alone does not fix that — it buys three more
   * parts. The track has to be recessed, which is what the system's own segmented control does:
   * a grey groove with a raised white thumb in it. Darkening rather than greying, so the same
   * rule reads in both appearances.
   */
  --lg-well: rgb(0 0 0 / .06);
  --lg-lens-border: rgb(0 0 0 / .05);
  --lg-lens-shadow: 0 1px 2px rgb(0 0 0 / .14), 0 4px 10px rgb(0 0 0 / .10), inset 0 1px 0 rgb(255 255 255 / .9);
  --lg-lens-shadow-held: 0 2px 5px rgb(0 0 0 / .18), 0 10px 22px rgb(0 0 0 / .16), inset 0 1px 0 rgb(255 255 255 / .95);
  --lg-glass-shadow: 0 3px 8px rgb(0 0 0 / .05), 0 12px 36px rgb(0 0 0 / .10);
  --lg-glass-shadow-lift: 0 6px 14px rgb(0 0 0 / .08), 0 22px 48px rgb(0 0 0 / .15);
  --lg-glass-shadow-large: 0 12px 28px rgb(0 0 0 / .11), 0 32px 64px rgb(0 0 0 / .19);
  --lg-glass-opaque: #f2f2f7;    /* reduced-transparency substitute */

  /* Interaction states on a shared surface */
  --lg-hover: rgb(255 255 255 / .5);
  --lg-pressed: rgb(255 255 255 / .78);
  --lg-selected: rgb(255 255 255 / .84);
  --lg-pressed-alpha: .78;
  --lg-selected-alpha: .84;
  --lg-focus: var(--lg-blue);

  /* ---- Legacy aliases (0.1.x). Removed once every component is migrated. ---- */
  --lg-fg: var(--lg-label);
  --lg-muted: var(--lg-label-secondary);
  --lg-edge: var(--lg-separator);
  --lg-opaque: var(--lg-glass-opaque);
  --lg-shadow: var(--lg-glass-shadow);
  --lg-shadow-lift: var(--lg-glass-shadow-lift);
  /* The material fill, split into colour + opacity so component states can override the
     opacity alone (pressed, selected, large glass) without restating the colour. */
  /* Off-white by the same three points as the surfaces above, so a glass panel and a solid
     one do not read as two different whites sitting next to each other. */
  --lg-tint-color: 252 252 254;
  --lg-tint-opacity: .7;
}

/* --------------------------------------------------------------------------
   3. Dark appearance
   -------------------------------------------------------------------------- */
[data-lg-theme="dark"] {
  --lg-red: rgb(255 66 69);      --lg-orange: rgb(255 146 48);  --lg-yellow: rgb(255 214 0);
  --lg-green: rgb(48 209 88);    --lg-mint: rgb(0 218 195);     --lg-teal: rgb(0 210 224);
  --lg-cyan: rgb(60 211 254);    --lg-blue: rgb(0 145 255);     --lg-indigo: rgb(109 124 255);
  --lg-purple: rgb(219 52 242);  --lg-pink: rgb(255 55 95);     --lg-brown: rgb(183 138 102);
  --lg-gray: rgb(142 142 147);   --lg-gray2: rgb(99 99 102);    --lg-gray3: rgb(72 72 74);
  --lg-gray4: rgb(58 58 60);     --lg-gray5: rgb(44 44 46);     --lg-gray6: rgb(28 28 30);

  --lg-accent: var(--lg-blue);
  --lg-accent-contrast: #fff;
  /* Same rule as the light appearance, in the other direction: the ink is lifted away from the
     dark wash it sits on rather than pushed into it. */
  --lg-ink-toward: #fff;
  --lg-ink-amount: 80%;

  --lg-label: rgb(255 255 255);
  --lg-label-secondary: rgb(235 235 245 / .60);
  --lg-label-tertiary: rgb(235 235 245 / .30);
  --lg-label-quaternary: rgb(235 235 245 / .16);
  --lg-placeholder: var(--lg-label-tertiary);
  --lg-separator: rgb(84 84 88 / .60);
  --lg-separator-opaque: rgb(56 56 58);
  --lg-link: var(--lg-blue);

  --lg-bg: rgb(0 0 0);
  --lg-bg-secondary: rgb(28 28 30);
  --lg-bg-tertiary: rgb(44 44 46);
  --lg-bg-grouped: rgb(0 0 0);
  --lg-bg-grouped-2: rgb(28 28 30);
  --lg-bg-grouped-3: rgb(44 44 46);
  --lg-fill: rgb(120 120 128 / .36);
  --lg-fill-secondary: rgb(120 120 128 / .32);
  --lg-fill-tertiary: rgb(118 118 128 / .24);
  --lg-fill-quaternary: rgb(118 118 128 / .18);

  --lg-material-ultrathin: rgb(30 30 30 / .55);
  --lg-material-thin: rgb(30 30 30 / .70);
  --lg-material-regular: rgb(30 30 30 / .82);
  --lg-material-thick: rgb(30 30 30 / .93);

  --lg-glass-fg: rgb(255 255 255 / .94);
  --lg-glass-fg-secondary: rgb(255 255 255 / .66);
  --lg-glass-rim-hi: rgb(255 255 255 / .28);
  --lg-glass-rim-lo: rgb(0 0 0 / .45);

  /* A third of the light values. White light on a dark panel is the whole panel lighting up;
     at the light appearance's 26% the pointer drags a visible bright blob around the screen. */
  --lg-shine-alpha: .09;
  --lg-shine-strong: .16;
  --lg-flash-alpha: .18;

  /* The capsule cannot be "white, but more so" here. It is a lift out of the track — a step
     brighter than the surface it slides on, edged rather than shadowed. */
  --lg-lens-bg: rgb(255 255 255 / .20);
  --lg-lens-alpha: .20;
  --lg-well: rgb(0 0 0 / .22);
  --lg-lens-border: rgb(255 255 255 / .22);
  --lg-lens-shadow: 0 1px 2px rgb(0 0 0 / .32), 0 4px 12px rgb(0 0 0 / .28);
  --lg-lens-shadow-held: 0 2px 6px rgb(0 0 0 / .4), 0 10px 24px rgb(0 0 0 / .36);
  --lg-glass-shadow: 0 3px 8px rgb(0 0 0 / .1), 0 16px 40px rgb(0 0 0 / .24);
  --lg-glass-shadow-lift: 0 8px 18px rgb(0 0 0 / .18), 0 28px 56px rgb(0 0 0 / .34);
  --lg-glass-shadow-large: 0 16px 34px rgb(0 0 0 / .26), 0 40px 76px rgb(0 0 0 / .42);
  --lg-glass-opaque: #1c1c1e;

  --lg-hover: rgb(255 255 255 / .12);
  --lg-pressed: rgb(255 255 255 / .22);
  --lg-selected: rgb(255 255 255 / .16);
  --lg-pressed-alpha: .22;
  --lg-selected-alpha: .16;
  --lg-focus: var(--lg-blue);

  --lg-fg: var(--lg-label);
  --lg-muted: var(--lg-label-secondary);
  --lg-edge: var(--lg-separator);
  --lg-opaque: var(--lg-glass-opaque);
  --lg-shadow: var(--lg-glass-shadow);
  --lg-shadow-lift: var(--lg-glass-shadow-lift);
  --lg-tint-color: 30 30 32;
  --lg-tint-opacity: .78;
}

/* --------------------------------------------------------------------------
   3.5 Size class
   "Decide a layout from the size class, never from the device type or the
   orientation" (HIG, layout). On the web that is a width: compact below 768,
   regular at or above it. The React equivalent is useSizeClass(); both read
   the same breakpoint so a component and its stylesheet cannot disagree.
   -------------------------------------------------------------------------- */
@media (min-width: 768px) {
  :root { --lg-margin: var(--lg-margin-regular); }
}

/* --------------------------------------------------------------------------
   4. Increase Contrast

   The HIG ships a separate palette for this setting, and the material becomes
   predominantly black/white with a contrasting border (handled in styles.css).

   Two mechanisms, deliberately identical: the OS preference, and the explicit
   `contrast="more"` on GlassProvider, which the provider publishes as
   `data-lg-contrast="more"` on <html>. The opt-in used to swap three label
   alphas and leave the palette alone, which made it a much weaker setting than
   the media query it claims to layer on top of — and since Increase Contrast is
   the step the HIG allows a below-4.5:1 default to stand on, a hollow one turns
   every considered choice into a plain failure.

   The two palettes below are duplicated because CSS cannot share declarations
   between a media query and a selector; `tests/core/stylesheet.test.ts` asserts
   they stay identical, which is the part that would otherwise rot.
   -------------------------------------------------------------------------- */
@media (prefers-contrast: more) {
  :root,
  [data-lg-theme="light"] {
    --lg-red: rgb(233 21 45);     --lg-orange: rgb(197 83 0);   --lg-yellow: rgb(161 106 0);
    --lg-green: rgb(0 137 50);    --lg-mint: rgb(0 133 117);    --lg-teal: rgb(0 129 152);
    --lg-cyan: rgb(0 126 174);    --lg-blue: rgb(30 110 244);   --lg-indigo: rgb(86 74 222);
    --lg-purple: rgb(176 47 194); --lg-pink: rgb(231 18 77);    --lg-brown: rgb(149 109 81);
    --lg-label-secondary: rgb(60 60 67 / .82);
    --lg-label-tertiary: rgb(60 60 67 / .55);
    --lg-separator: rgb(0 0 0 / .55);
  }
  [data-lg-theme="dark"] {
    --lg-red: rgb(255 97 101);    --lg-orange: rgb(255 160 86);  --lg-yellow: rgb(254 223 67);
    --lg-green: rgb(74 217 104);  --lg-mint: rgb(84 223 203);    --lg-teal: rgb(59 221 236);
    --lg-cyan: rgb(109 217 255);  --lg-blue: rgb(92 184 255);    --lg-indigo: rgb(167 170 255);
    --lg-purple: rgb(234 141 255);--lg-pink: rgb(255 138 196);   --lg-brown: rgb(219 166 121);
    --lg-label-secondary: rgb(235 235 245 / .85);
    --lg-label-tertiary: rgb(235 235 245 / .60);
    --lg-separator: rgb(255 255 255 / .60);
  }
}
[data-lg-contrast="more"],
[data-lg-contrast="more"] [data-lg-theme="light"] {
  --lg-red: rgb(233 21 45);     --lg-orange: rgb(197 83 0);   --lg-yellow: rgb(161 106 0);
